local config = {
  ui_story_5032_50320101_1_dialog_content = "<color=#e8d9bb>PlayerName, Vice e Carleen, que está se sentindo perdida na busca pelo poder, estão indo para o movimentado porto de Harbour City.</color>",
  ui_story_5032_50320101_2_dialog_content = "<color=#e8d9bb>Em seu caminho para visitar Laird Elvis, o Caelestite mais uma vez encontra Fia, a extrozoóloga.</color>",
  ui_story_5032_50320101_3_dialog_content = "<color=#e8d9bb>Laird Elvis recebe calorosamente o grupo, mas parece estar escondendo algo sob seu corpo frágil e rosto cheio de cicatrizes.</color>",
  ui_story_5032_50320101_4_dialog_content = "<color=#e8d9bb>Uma reviravolta do destino leva o grupo ao Emerald, um navio onde um grande festival está sendo realizado.</color>",
  ui_story_5032_50320101_5_dialog_content = "<color=#e8d9bb>Aqui, PlayerName e outros conhecem Jeno, o misterioso e distante mestre de cerimônias.</color>",
  ui_story_5032_50320101_6_dialog_content = "<color=#e8d9bb>A alegre e entusiasmada Rainbow, que é apresentadora de circo, contato com o cliente, diretora de segurança e aprendiz de engenheiro naval.</color>",
  ui_story_5032_50320101_7_dialog_content = "<color=#e8d9bb>E os três trapezistas empolgantes, Merylt, Subli e Frimet.</color>",
  ui_story_5032_50320101_8_dialog_content = "<color=#e8d9bb>Fia está convencida de que a besta maravilhosa que ela está procurando, um <color=#FFB400>Baleia-nuvem</color>, está em algum lugar a bordo do Emerald.</color>",
  ui_story_5032_50320101_9_dialog_content = "<color=#e8d9bb>Para saber se ela está certa, o esquadrão Caelestite decide se inscrever em uma competição e ganhar mais tempo para explorar o circo.</color>",
  ui_story_5032_50320101_10_dialog_content = "<color=#e8d9bb>Enquanto isso, Carleen, ainda se sentindo perdida, pergunta a Vice como ela pode se tornar mais forte.</color>",
  ui_story_5032_50320101_11_dialog_content = "<color=#e8d9bb>A Esmeralda está cheia de alegria e risos, mas Laird Elvis, que está sentado entre os juízes, está perdido em pensamentos.</color>",
  ui_story_5032_50320101_12_dialog_content = "<color=#e8d9bb>Frustrada durante a competição, Carleen ganha alguns novos insights graças ao incentivo de PlayerName.</color>",
  ui_story_5032_50320101_13_dialog_content = "<color=#e8d9bb>Em última análise, o esquadrão Caelestite é vitorioso. Mas o prêmio não é um Cloudwhale.</color>",
  ui_story_5032_50320101_14_dialog_content = "<color=#e8d9bb>Em vez disso, o prêmio é Kyllo, o companheiro animal maravilhoso de Fia, que ela enviou para procurar as águas próximas por Cloudwhale.</color>",
  ui_story_5032_50320101_15_dialog_content = "<color=#e8d9bb>Decepcionado, o grupo se prepara para se despedir de Jeno e continuar sua busca por Cloudwhale.</color>",
  ui_story_5032_50320101_16_dialog_content = "<color=#e8d9bb>Mas quando eles procuram por Jeno, eles o encontram desmaiado na cabine do Emerald.</color>",
  ui_story_5032_50320101_17_dialog_content = "<color=#e8d9bb>Assim que eles conseguem acordá-lo, o navio treme violentamente.</color>",
  ui_story_5032_50320101_18_dialog_content = "<color=#e8d9bb>Jeno guia a equipe enquanto eles correm para a câmara central da Esmeralda.</color>",
  ui_story_5032_50320101_19_dialog_content = "<color=#e8d9bb>Mas no caminho, guardas com o selo da família Elvis bloqueiam sua passagem.</color>",
  ui_story_5032_50320101_20_dialog_content = "<color=#e8d9bb>Depois de superar vários obstáculos, o grupo do Caelestite chega à câmara central e finalmente encontra Elvis lá.</color>",
  ui_story_5032_50320101_21_dialog_content = "<color=#e8d9bb>E ele está usando algum dispositivo em sua equipe para absorver energia do núcleo de energia.</color>",
  ui_story_5032_50320101_22_dialog_content = "<color=#e8d9bb>Tal ação desperta a enorme máquina que guarda o núcleo, que começa a atacar o grupo.</color>",
  ui_story_5032_50320101_23_dialog_content = "<color=#e8d9bb>O poderoso Guardião leva a equipe Colossus à beira da derrota. Até Carleen está imobilizada pela armadilha de Elvis.</color>",
  ui_story_5032_50320101_24_dialog_content = "<color=#e8d9bb>Mas em um momento decisivo, um novo poder desperta dentro de Carleen, afastando o Guardião.</color>",
  ui_story_5032_50320101_25_dialog_content = "<color=#e8d9bb>O grupo derrota o Guardian, mas Elvis escapa - apenas para ser pego por Matthieu, um juiz de Lumopolis.</color>",
  ui_story_5032_50320101_26_dialog_content = "<color=#e8d9bb>Mas parece que tudo isso... está longe de terminar.</color>",
  ui_story_5032_50320101_27_dialog_content = "<color=#e8d9bb>O ar ruge na chuva fria e o céu se inflama com o vento selvagem. Uma tempestade que destruirá Harbour City está chegando!</color>",
  ui_story_5032_50320101_28_dialog_content = "Rápido rápido! A vista daqui é incrível!",
  ui_story_5032_50320101_29_dialog_content = "E-Elvis! Você está correndo muito rápido!",
  ui_story_5032_50320101_30_dialog_content = "Uau...",
  ui_story_5032_50320101_31_dialog_content = "Que tal isso? Você não consegue ver esse tipo de vista ficando em casa.",
  ui_story_5032_50320101_32_dialog_content = "Não se preocupe com esses bandidos encrenqueiros. Eu posso lidar com eles e muito mais.",
  ui_story_5032_50320101_33_dialog_content = "Esta praia, este oceano — um dia tudo pertencerá a você e a mim.",
  ui_story_5032_50320101_34_dialog_content = "Sim!",
  ui_story_5032_50320101_35_dialog_content = "Às vezes eu sonho em fazer isso. Sair do meu quarto e pintar o mundo lá fora.",
  ui_story_5032_50320101_36_dialog_content = "Talvez... Talvez eu devesse pintar esse nosso momento.",
  ui_story_5032_50320101_37_dialog_content = "Sério? Você me pintaria?",
  ui_story_5032_50320101_38_dialog_content = "Sim, mas sou lento e também não sou muito bom nisso.",
  ui_story_5032_50320101_39_dialog_content = "Está bem. Seus desenhos são os melhores para mim!",
  ui_story_5032_50320101_40_dialog_content = "Então... por que não nos encontramos amanhã cedo no porto?",
  ui_story_5032_50320101_41_dialog_content = "Podemos colher alguns frutos do mar da praia. Então você pode me pintar, e eu vou fazer uma sopa de frutos do mar para você!",
  ui_story_5032_50320101_42_dialog_content = "Uau, a sopa de frutos do mar de Elvis!",
  ui_story_5032_50320101_43_dialog_content = "Incrível! É um acordo, então!",
  ui_story_5032_50320101_44_dialog_content = "Negócio!",
  ui_story_5032_50320101_45_dialog_content = "Nós tinhamos um acordo...",
  ui_story_5032_50320101_46_dialog_content = "Tínhamos combinado de nos encontrar...",
  ui_story_5032_50320101_47_dialog_content = "Então, como você pôde sair sem dizer adeus?",
  ui_story_5032_50320101_48_dialog_content = "Por que você me traiu? Por que você destruiu minha casa? Por que você quebrou meu juramento à Verdadeira Ordem?",
  ui_story_5032_50320101_49_dialog_content = "E por que você parece... tão dolorosa?",
  ui_story_5032_50320101_50_dialog_content = "Chefe.",
  ui_story_5032_50320101_51_dialog_content = "Chefe!",
  ui_story_5032_50320101_52_dialog_content = "Chefe!!",
  ui_story_5032_50320101_53_dialog_content = "O quê?",
  ui_story_5032_50320101_54_dialog_content = "O que você estava olhando? Você estava a quilômetros de distância.",
  ui_story_5032_50320101_55_dialog_content = "Nada. Eu estava pensando em como consertar a Esmeralda.",
  ui_story_5032_50320101_56_dialog_content = "Oh sério? Eu pensei que você tinha dado essa tarefa para Ciel e eu.",
  ui_story_5032_50320101_57_dialog_content = "...",
  ui_story_5032_50320101_58_dialog_content = "Ei, chefe.",
  ui_story_5032_50320101_59_dialog_content = "Eu realmente não sei o que aconteceu entre você e Laird Elvis.",
  ui_story_5032_50320101_60_dialog_content = "Mas ouvi o Caelestite dizer que Elvis pediu para vê-lo muitas vezes depois de ser detido.",
  ui_story_5032_50320101_61_dialog_content = "Hunf.",
  ui_story_5032_50320101_62_dialog_content = "Não tenho nada a dizer a alguém que quase destruiu a Esmeralda.",
  ui_story_5032_50320101_63_dialog_content = "Oh, é assim?",
  ui_story_5032_50320101_64_dialog_content = "Mas eu meio que me sinto mal por ele. Ouvi dizer que a Síndrome de Modali está piorando.",
  ui_story_5032_50320101_65_dialog_content = "E ele está se recusando a comer...",
  ui_story_5032_50320101_66_dialog_content = "Se isso continuar... Acho que ele não vai durar muito com aquele corpo frágil dele.",
  ui_story_5032_50320101_67_dialog_content = "O que você disse?!",
  ui_story_5032_50320101_68_dialog_content = "Eh? Chefe?",
  ui_story_5032_50320101_69_dialog_content = "Agora onde você vai?",
  ui_story_5032_50320101_70_dialog_content = "Acabei de me lembrar que nossos balões acabaram.",
  ui_story_5032_50320101_71_dialog_content = "Eu vou comprar alguns.",
  ui_story_5032_50320101_72_dialog_content = "Eh? O que?",
  ui_story_5032_50320101_73_dialog_content = "Há um caixote inteiro deles bem onde você estava...",
  ui_story_5032_50320101_74_dialog_content = "Juiz Matthieu, Juiz assistente Loewe.",
  ui_story_5032_50320101_75_dialog_content = "Desculpe mantê-lo esperando.",
  ui_story_5032_50320101_76_dialog_content = "Não fazia ideia de que Elvis tinha tantas tarefas para cumprir todos os dias.",
  ui_story_5032_50320101_77_dialog_content = "E como ele está?",
  ui_story_5032_50320101_78_dialog_content = "O mesmo. Ele se recusa a comer ou mesmo beber.",
  ui_story_5032_50320101_79_dialog_content = "Sério? Devo admirar sua força de vontade.",
  ui_story_5032_50320101_80_dialog_content = "Er, posso perguntar, Alteza, por quanto tempo planeja continuar com isso?",
  ui_story_5032_50320101_81_dialog_content = "Nós, como você instruiu, fizemos o relatório ao Conselho dos Anciões. Mas isso não os satisfará por muito tempo.",
  ui_story_5032_50320101_82_dialog_content = "Devemos descobrir os verdadeiros motivos de Elvis em breve e erradicar as sementes da rebelião.",
  ui_story_5032_50320101_83_dialog_content = "Caso contrário, a bagunça em Harbour City pode acabar se tornando nosso problema a ser consertado.",
  ui_story_5032_50320101_84_dialog_content = "Lord Schwartz está furioso, e os plebeus perderam seu amado laird. Todos estão inquietos.",
  ui_story_5032_50320101_85_dialog_content = "Seria preferível voltar imediatamente para Lumopolis. E deixe Lord Schwartz enviar seus homens para investigar.",
  ui_story_5032_50320101_86_dialog_content = "Não. Primeiro, não vou desistir no meio do caminho.",
  ui_story_5032_50320101_87_dialog_content = "Em segundo lugar, eu não posso simplesmente sair assim.",
  ui_story_5032_50320101_88_dialog_content = "Se eu fizer isso, como posso ter certeza de que Lord Schwartz e os cidadãos de Harbour City terão as respostas que merecem?",
  ui_story_5032_50320101_89_dialog_content = "Tudo bem, tudo bem. Eu entendo. Esqueça o que eu disse.",
  ui_story_5032_50320101_90_dialog_content = "Mas mesmo assim, agradeço-lhe, Juiz Matthieu.",
  ui_story_5032_50320101_91_dialog_content = "Essa é nova.",
  ui_story_5032_50320101_92_dialog_content = "Huh? O que é isso? Posso dizer coisas úteis de vez em quando, certo?",
  ui_story_5032_50320101_93_dialog_content = "Claro.",
  ui_story_5032_50320101_94_dialog_content = "Espere até que eu termine de escrever meu relatório, e eu vou te ensinar por que eu sou o juiz e você é meu assistente!",
  ui_story_5032_50320101_95_dialog_content = "Então, deixarei a tarefa de guardar Elvis em suas mãos capazes.",
  ui_story_5032_50320101_96_dialog_content = "Como você manda.",
  ui_story_5032_50320101_97_dialog_content = "Carleen, estamos de volta.",
  ui_story_5032_50320101_98_dialog_content = "Como você está se sentindo? Ainda dói?",
  ui_story_5032_50320101_99_dialog_content = "Bem vindo de volta. Minhas feridas e minha Lumina se recuperaram mais rápido do que eu esperava.",
  ui_story_5032_50320101_100_dialog_content = "Já estou bem o suficiente para lidar com qualquer luta comum. Não se preocupe comigo.",
  ui_story_5032_50320101_101_dialog_content = "Que tal aquelas pessoas protestando contra a detenção de Elvis? Eles foram embora?",
  ui_story_5032_50320101_102_dialog_content = "Tem certeza de que vai funcionar?",
  ui_story_5032_50320101_103_dialog_content = "A maioria dos manifestantes estava disposta a sair silenciosamente assim que souberam que a princesa Carleen de Lumopolis estava liderando a investigação.",
  ui_story_5032_50320101_104_dialog_content = "Mas há alguns resistentes que não ouviriam.",
  ui_story_5032_50320101_105_dialog_content = "Seus ferimentos pareciam sérios depois da batalha, Carleen. Você me deu um susto.",
  ui_story_5032_50320101_106_dialog_content = "Por favor, não se esforce tanto no futuro.",
  ui_story_5032_50320101_107_dialog_content = "Eu sei. Desculpe por preocupar vocês, Vice, e PlayerName.",
  ui_story_5032_50320101_108_dialog_content = "Ah, e nos deparamos com um guarda no caminho de volta que nos contou sobre avistamentos de Eclipsitos espalhados na praia.",
  ui_story_5032_50320101_109_dialog_content = "Eclipses de novo? Houve relatos de aparições recentemente.",
  ui_story_5032_50320101_110_dialog_content = "Mas nossas investigações de acompanhamento não deram em nada.",
  ui_story_5032_50320101_111_dialog_content = "Talvez Patou saiba de alguma coisa. Ele é o especialista nas defesas da cidade.",
  ui_story_5032_50320101_112_dialog_content = "Hum. Patou e o resto dos guardas de Elvis foram trancados ao lado, mas não estão cooperando.",
  ui_story_5032_50320101_113_dialog_content = "Elvis tem alertado para uma crise iminente. Você acha que isso teve algo a ver com os Eclipsites?",
  ui_story_5032_50320101_114_dialog_content = "Possivelmente. Mas do jeito que as coisas estão, seus números não são altos o suficiente para representar uma ameaça.",
  ui_story_5032_50320101_115_dialog_content = "E ele se recusa a dizer qual será a crise. Tudo o que ele faz é exigir ver Jeno.",
  ui_story_5032_50320101_116_dialog_content = "Seu amigo de infância? Bem, isso é tocante...",
  ui_story_5032_50320101_117_dialog_content = "PlayerName, você e Vice poderiam visitar Elvis mais uma vez? Veja se você pode encontrar alguma pista em tudo o que ele diz.",
  ui_story_5032_50320101_118_dialog_content = "E fale com Jeno também. Se ele estivesse disposto a falar com Elvis... Bem, talvez pudéssemos aprender algo mais.",
  ui_story_5032_50320101_119_dialog_content = "É claro. Deixe conosco.",
  ui_story_5032_50320201_1_dialog_content = "Rainbow, você quer tentar reiniciar o sistema?",
  ui_story_5032_50320201_2_dialog_content = "Rogério. Vou dar outra chance.",
  ui_story_5032_50320201_3_dialog_content = "<color=#e8d9bb>... Reinicialização do sistema. Iniciando o autoteste.</color>",
  ui_story_5032_50320201_4_dialog_content = "<color=#e8d9bb>Anomalias detectadas.</color>",
  ui_story_5032_50320201_5_dialog_content = "<color=#e8d9bb>Erro no sistema do motor.</color>",
  ui_story_5032_50320201_6_dialog_content = "<color=#e8d9bb>Erro no sistema de transmissão.</color>",
  ui_story_5032_50320201_7_dialog_content = "Nada de bom. Ainda não inicia.",
  ui_story_5032_50320201_8_dialog_content = "Desculpe...",
  ui_story_5032_50320201_9_dialog_content = "Pare de se desculpar!",
  ui_story_5032_50320201_10_dialog_content = "Eu sei que você está tentando o seu melhor. Você tem me ajudado a consertar o sistema do motor há séculos e não consigo me lembrar da última vez que você fez uma pausa.",
  ui_story_5032_50320201_11_dialog_content = "Está bem.",
  ui_story_5032_50320201_12_dialog_content = "Você me ajudou a atualizar o Styx. Então agora eu preciso ajudá-lo a colocar sua Esmeralda em funcionamento novamente.",
  ui_story_5032_50320201_13_dialog_content = "Porque é para isso que servem os amigos, certo?",
  ui_story_5032_50320201_14_dialog_content = "Sim! E você é um grande amigo, Ciel.",
  ui_story_5032_50320201_15_dialog_content = "Estou muito grato por tê-lo aqui me ajudando a consertar a Esmeralda.",
  ui_story_5032_50320201_16_dialog_content = "Ei, você está muito perto e não consigo ler os dados.",
  ui_story_5032_50320201_17_dialog_content = "Espere. Olhando para estes registros que acabei de extrair... alguma maquinaria foi removida desta nave?",
  ui_story_5032_50320201_18_dialog_content = "Poderia ser. Lembro-me do velho engenheiro me dizendo que o navio tem uma história longa e complexa.",
  ui_story_5032_50320201_19_dialog_content = "Infelizmente, ele não está mais conosco. Se ele fosse—",
  ui_story_5032_50320201_20_dialog_content = "*Soluçando* Se ele ainda estivesse aqui—",
  ui_story_5032_50320201_21_dialog_content = "O que aconteceu? Aconteceu alguma coisa ruim com ele?",
  ui_story_5032_50320201_22_dialog_content = "Não. Ele disse que finalmente encontrou um sucessor. E então saímos quando atracamos sem um adeus.",
  ui_story_5032_50320201_23_dialog_content = "Ouvi dizer que ele é casado, tem filhos e dirige uma churrascaria.",
  ui_story_5032_50320201_24_dialog_content = "Mas eu ainda não tinha aprendido muito com ele. Então eu tive que estudar tudo sozinho. Felizmente eu gosto.",
  ui_story_5032_50320201_25_dialog_content = "E felizmente, o núcleo não requer muita manutenção e não teve problemas desde que assumi.",
  ui_story_5032_50320201_26_dialog_content = "Isso é realmente incrivelmente confiável. Isso me faz pensar para que o navio foi usado originalmente ...",
  ui_story_5032_50320201_27_dialog_content = "E com o Guardian, isso só aumenta o mistério.",
  ui_story_5032_50320201_28_dialog_content = "Na verdade, uma vez perguntei ao meu antecessor o que era aquele Guardião.",
  ui_story_5032_50320201_29_dialog_content = "Mas ele apenas me ignorou, dizendo que provavelmente era apenas uma decoração que parece legal.",
  ui_story_5032_50320201_30_dialog_content = "Ah. Parece que ele era um estranho.",
  ui_story_5032_50320201_31_dialog_content = "Eu sei direito? Mas o Emerald continua funcionando, mesmo que não tenha os melhores engenheiros. É um ótimo navio!",
  ui_story_5032_50320201_32_dialog_content = "... Graa!",
  ui_story_5032_50320201_33_dialog_content = "Espere. Ouviu algo ao longe?",
  ui_story_5032_50320201_34_dialog_content = "Eh? Merylt, você realmente escreveu PlayerName uma letra?",
  ui_story_5032_50320201_35_dialog_content = "Deixe-me ajudá-lo! Eu posso dar a ele para você.",
  ui_story_5032_50320201_36_dialog_content = "Você sabe, no caso de você ser muito tímido para entregá-lo.",
  ui_story_5032_50320201_37_dialog_content = "Mas... acho que devo dar a ele pessoalmente.",
  ui_story_5032_50320201_38_dialog_content = "Não não! Você deve me deixar fazer isso, Merylt!",
  ui_story_5032_50320201_39_dialog_content = "Subli definitivamente vai abri-lo e lê-lo! Sua curiosidade a proíbe de fazer o contrário.",
  ui_story_5032_50320201_40_dialog_content = "Ela pode até adicionar algumas coisas a ele.",
  ui_story_5032_50320201_41_dialog_content = "Eh? Ela não iria, iria?",
  ui_story_5032_50320201_42_dialog_content = "Sinto muito, Merylt, mas Frimet me conhece muito bem.",
  ui_story_5032_50320201_43_dialog_content = "Ah, devolva-me a carta!",
  ui_story_5032_50320201_44_dialog_content = "Bica, pegue para mim.",
  ui_story_5032_50320201_45_dialog_content = "Ei?",
  ui_story_5032_50320201_46_dialog_content = "Pare aí mesmo!",
  ui_story_5032_50320201_47_dialog_content = "Aqui está sua carta.",
  ui_story_5032_50320201_48_dialog_content = "O-obrigado, senhorita Fia.",
  ui_story_5032_50320201_49_dialog_content = "Que bando de crianças barulhentas.",
  ui_story_5032_50320201_50_dialog_content = "Você não pode ser mais maduro? Como eu.",
  ui_story_5032_50320201_51_dialog_content = "Ah, você é maduro? Eu não tinha notado.",
  ui_story_5032_50320201_52_dialog_content = "E se estamos falando de força, até mesmo Merylt provavelmente poderia vencê-lo.",
  ui_story_5032_50320201_53_dialog_content = "O que você disse!? Quer descobrir o quão forte eu sou?",
  ui_story_5032_50320201_54_dialog_content = "Subli, Frimet, parem de provocar a Srta. Fia. Ela é uma convidada do circo, lembra?",
  ui_story_5032_50320201_55_dialog_content = "Bem bem.",
  ui_story_5032_50320201_56_dialog_content = "Hmph. Ei, por que vocês três não estão em terra como o resto da tripulação?",
  ui_story_5032_50320201_57_dialog_content = "Eu mesmo posso cuidar das bestas maravilhosas.",
  ui_story_5032_50320201_58_dialog_content = "Afinal, sou um membro temporário do circo, e cuidar de animais é meio que minha área de especialização.",
  ui_story_5032_50320201_59_dialog_content = "Como poderíamos?",
  ui_story_5032_50320201_60_dialog_content = "As pessoas na cidade pensam que fomos nós, pessoas do circo, que machucamos seu amado Laird Elvis.",
  ui_story_5032_50320201_61_dialog_content = "Eles vão nos dar o ombro frio na melhor das hipóteses e podem até tentar começar uma briga.",
  ui_story_5032_50320201_62_dialog_content = "Além disso, preferimos estar no Emerald de qualquer maneira.",
  ui_story_5032_50320201_63_dialog_content = "Afinal, esta é a nossa casa, sabe?",
  ui_story_5032_50320201_64_dialog_content = "Sim...",
  ui_story_5032_50320201_65_dialog_content = "Acho que consigo entender como você se sente.",
  ui_story_5032_50320201_66_dialog_content = "Meu trabalho como extrozoologista envolve perambular por todos os cantos do continente – mas, às vezes, ainda sinto falta do ensopado de carne da minha mãe.",
  ui_story_5032_50320201_67_dialog_content = "E por falar em feras maravilhosas, ainda não alcancei o objetivo que me trouxe a Harbor City.",
  ui_story_5032_50320201_68_dialog_content = "O que foi?",
  ui_story_5032_50320201_69_dialog_content = "Vamos, conte-nos. Nós talvez possamos ajudar.",
  ui_story_5032_50320201_70_dialog_content = "Bem, acho que não faz sentido ficar em segredo agora.",
  ui_story_5032_50320201_71_dialog_content = "Tá bom.",
  ui_story_5032_50320201_72_dialog_content = "Na verdade, estou em busca de uma fera exótica e maravilhosa. o <color=#FFB400>Baleia-nuvem</color>!",
  ui_story_5032_50320201_73_dialog_content = "O que é isso, algum tipo de baleia?",
  ui_story_5032_50320201_74_dialog_content = "S-Sim, acho que sim.",
  ui_story_5032_50320201_75_dialog_content = "Quer dizer, não é que eu não saiba. É que meu péssimo mestre não explicou direito.",
  ui_story_5032_50320201_76_dialog_content = "Ele me disse que o rastro de energia da Baleia Nuvem desapareceu em algum lugar no oceano perto daqui, então me enviou para investigar.",
  ui_story_5032_50320201_77_dialog_content = "Tudo o que sei é que seu poderoso Lumina pode fazer os Eclipsites se encolherem de medo e dissipar até mesmo o mais espesso Darkflow.",
  ui_story_5032_50320201_78_dialog_content = "Baleias? Eu nunca vi um, mas ouvi pessoas mais velhas do circo falarem sobre eles.",
  ui_story_5032_50320201_79_dialog_content = "Eles são todos enormes e passam a maior parte do tempo no fundo do oceano.",
  ui_story_5032_50320201_80_dialog_content = "Eles parecem que ficarão facilmente encalhados se chegarem a águas rasas.",
  ui_story_5032_50320201_81_dialog_content = "Sim, e os peixes não têm medo de navios? Eu não esperaria que alguém nadasse perto daqui.",
  ui_story_5032_50320201_82_dialog_content = "Argh! Aquele homem me enviou em uma caça ao ganso selvagem?",
  ui_story_5032_50320201_83_dialog_content = "Então eu estou tendo uma crise!",
  ui_story_5032_50320201_84_dialog_content = "Ah!",
  ui_story_5032_50320201_85_dialog_content = "Ops, desculpe por gritar assim de repente. Eu assustei você?",
  ui_story_5032_50320201_86_dialog_content = "Está tudo bem. Larguei todas as minhas coisas, só isso.",
  ui_story_5032_50320201_87_dialog_content = "Não se mova, eu vou buscá-los para você.",
  ui_story_5032_50320201_88_dialog_content = "Rá!",
  ui_story_5032_50320201_89_dialog_content = "Ha!!",
  ui_story_5032_50320201_90_dialog_content = "Isso é tudo? E o que é isso? Algum tipo de lanche gostoso?",
  ui_story_5032_50320201_91_dialog_content = "Isso mesmo, assim como todos aqueles doces saborosos que você pegou da última vez! E vai ajudá-lo a ficar mais alto.",
  ui_story_5032_50320201_92_dialog_content = "Subli, não tente fazer Fia comer a comida de peixe.",
  ui_story_5032_50320201_93_dialog_content = "Na verdade, essa é a comida de peixe que eu mesma fiz.",
  ui_story_5032_50320201_94_dialog_content = "Mas se você gostou daquele doce que comemos da última vez... Posso fazer alguns para você!",
  ui_story_5032_50320201_95_dialog_content = "O que, eu? Não, estou muito velho para coisas como doces. Eu só estava curioso!",
  ui_story_5032_50320201_96_dialog_content = "Ei, Merylt, você mantém peixes? Deixe-me ajudá-lo a identificar quais são as raças!",
  ui_story_5032_50320201_97_dialog_content = "É aquele pequeno, ali.",
  ui_story_5032_50320201_98_dialog_content = "Hum. Apenas este pequeno sujeito cinza. Não sei dizer de que raça é.",
  ui_story_5032_50320201_99_dialog_content = "Eep!",
  ui_story_5032_50320201_100_dialog_content = "Pode realmente comer tudo isso em uma refeição? Isso é incrível!",
  ui_story_5032_50320201_101_dialog_content = "Nosso mestre de cerimônias encontrou esse carinha na praia...",
  ui_story_5032_50320201_102_dialog_content = "Ele disse que parecia ferido e trouxe de volta para mim para cuidar dele.",
  ui_story_5032_50320201_103_dialog_content = "Ah, e ele disse que já estava nessa garrafa quando o encontrou.",
  ui_story_5032_50320201_104_dialog_content = "Encomendei um aquário adequado, mas ainda não está pronto. Então nosso pequeno está preso lá por enquanto.",
  ui_story_5032_50320201_105_dialog_content = "Nunca pensei que aquele feroz mestre de cerimônias fosse tão gentil com os animais.",
  ui_story_5032_50320201_106_dialog_content = "Sim... Ele até deu um nome: <color=#FFB400>Geedo</color>.",
  ui_story_5032_50320201_107_dialog_content = "Ei, Fia... Esta pode ser a Baleia Nuvem que você está procurando?",
  ui_story_5032_50320201_108_dialog_content = "Eep!",
  ui_story_5032_50320201_109_dialog_content = "Geedo é muito pequeno para ser um Cloudwhale.",
  ui_story_5032_50320201_110_dialog_content = "O mestre de cerimônias Jeno me disse que até uma baleia bebê seria grande demais para este navio.",
  ui_story_5032_50320201_111_dialog_content = "E as baleias não fazem \"eep eep\". Eles vão \"coaxar coaxar\".",
  ui_story_5032_50320201_112_dialog_content = "Sério? Não é \"hoot hoot\".",
  ui_story_5032_50320201_113_dialog_content = "Totalmente errado. É \"woo woo\".",
  ui_story_5032_50320201_114_dialog_content = "Não é \"chirp chirp\"?",
  ui_story_5032_50320201_115_dialog_content = "Graagh—",
  ui_story_5032_50320201_116_dialog_content = "Você está todo errado! Não é assim que as baleias soam. É totalmente...",
  ui_story_5032_50320201_117_dialog_content = "Graagh—",
  ui_story_5032_50320201_118_dialog_content = "Eclipses! Como Eclipsites entrou a bordo!?",
  ui_story_5032_50320202_1_dialog_content = "Ha—!",
  ui_story_5032_50320202_2_dialog_content = "Ei!",
  ui_story_5032_50320202_3_dialog_content = "Há mais deles!",
  ui_story_5032_50320202_4_dialog_content = "Graagh...",
  ui_story_5032_50320202_5_dialog_content = "Cuidado, Fia!",
  ui_story_5032_50320202_6_dialog_content = "Eclipsitos péssimos! Pegue isso!",
  ui_story_5032_50320202_7_dialog_content = "<color=#e8d9bb>Bate, bate!</color>",
  ui_story_5032_50320202_8_dialog_content = "Graagh—",
  ui_story_5032_50320202_9_dialog_content = "Uau, eu nunca esperei que você fosse uma lutadora tão boa, Fia.",
  ui_story_5032_50320202_10_dialog_content = "Heehee. Esses Eclipsites fracos não são páreo para mim.",
  ui_story_5032_50320202_11_dialog_content = "Eles eram obviamente muito fracos.",
  ui_story_5032_50320202_12_dialog_content = "Rapazes! Você está bem?",
  ui_story_5032_50320202_13_dialog_content = "Huff, huff... C-Ciel, você não pode simplesmente entrar assim.",
  ui_story_5032_50320202_14_dialog_content = "É muito perigoso agora que você não tem Styx com você.",
  ui_story_5032_50320202_15_dialog_content = "Eu sinto Muito. Mas eu sabia que você estava bem atrás de mim, Rainbow.",
  ui_story_5032_50320202_16_dialog_content = "Bem, isso é verdade.",
  ui_story_5032_50320202_17_dialog_content = "Mas ainda é muito perigoso. Não faça isso de novo.",
  ui_story_5032_50320202_18_dialog_content = "OK, eu entendo.",
  ui_story_5032_50320202_19_dialog_content = "Tudo bem, ninguém está ferido. Isso é o importante.",
  ui_story_5032_50320202_20_dialog_content = "Mas de onde vieram esses Eclipses?",
  ui_story_5032_50320202_21_dialog_content = "Sei lá.",
  ui_story_5032_50320202_22_dialog_content = "Normalmente, poderíamos verificar os registros do sistema da Esmeralda e descobrir.",
  ui_story_5032_50320202_23_dialog_content = "Mas o sistema ainda está inoperante, então temo que teremos que fazer uma busca local por local.",
  ui_story_5032_50320202_24_dialog_content = "Acho que é a nossa única opção.",
  ui_story_5032_50320202_25_dialog_content = "Mas um grupo de seis é grande demais para carregar no navio.",
  ui_story_5032_50320202_26_dialog_content = "E um grupo muito pequeno pode ser perigoso se mais Eclipsitas aparecerem.",
  ui_story_5032_50320202_27_dialog_content = "Então vamos nos dividir em duas equipes.",
  ui_story_5032_50320202_28_dialog_content = "Merylt, você e suas irmãs são fortes lutadoras. Vocês três podem ser uma equipe.",
  ui_story_5032_50320202_29_dialog_content = "Entendido!",
  ui_story_5032_50320202_30_dialog_content = "Não estamos muito familiarizados com as coisas dentro do navio, então devemos subir para verificar o convés e seus arredores.",
  ui_story_5032_50320202_31_dialog_content = "Ok, vamos deixar isso para você.",
  ui_story_5032_50320202_32_dialog_content = "Então seguirei Rainbow e Ciel para verificar o interior da nave.",
  ui_story_5032_50320202_33_dialog_content = "OK. Mas não ande por aí e toque em coisas aleatórias só porque você está curioso.",
  ui_story_5032_50320202_34_dialog_content = "Ainda pode haver Eclipses por aí.",
  ui_story_5032_50320202_35_dialog_content = "Ok, eu não vou.",
  ui_story_5032_50320301_1_dialog_content = "Elvis ainda não fala.",
  ui_story_5032_50320301_2_dialog_content = "Ele continua resmungando sobre querer ver Jeno. Então acho que precisamos falar com Jeno.",
  ui_story_5032_50320301_3_dialog_content = "Mas da última vez que tentei, ele se trancou em sua cabine e se recusou a sair.",
  ui_story_5032_50320301_4_dialog_content = "O que aconteceu com Elvis o afetou muito. Parece que eles eram amigos íntimos no passado.",
  ui_story_5032_50320301_5_dialog_content = "Sim. Então, se conseguirmos convencê-lo a ajudar, talvez ele consiga fazer Elvis falar.",
  ui_story_5032_50320301_6_dialog_content = "...",
  ui_story_5032_50320301_7_dialog_content = "Ei, aquele cara andando por aí parecendo perdido... poderia ser Jeno?",
  ui_story_5032_50320301_8_dialog_content = "Ei! Jeno!",
  ui_story_5032_50320301_9_dialog_content = "Ah, são vocês.",
  ui_story_5032_50320301_10_dialog_content = "É você, Jeno.",
  ui_story_5032_50320301_11_dialog_content = "Eu vim te ver mais cedo, mas... você não quis sair.",
  ui_story_5032_50320301_12_dialog_content = "Desculpe. Eu não estava de bom humor.",
  ui_story_5032_50320301_13_dialog_content = "Está bem. Mas onde você vai? Você parece perdido.",
  ui_story_5032_50320301_14_dialog_content = "Falar a verdade...",
  ui_story_5032_50320301_15_dialog_content = "Quero falar com Elvis.",
  ui_story_5032_50320301_16_dialog_content = "É aqui que o estão mantendo?",
  ui_story_5032_50320301_17_dialog_content = "Não é o que eu esperava.",
  ui_story_5032_50320301_18_dialog_content = "\"Ele era nobre e um laird. Temos que tratá-lo com dignidade, pelo menos até que seja considerado culpado.\"",
  ui_story_5032_50320301_19_dialog_content = "Foi o que Carleen disse. Então deixamos ele ficar aqui.",
  ui_story_5032_50320301_20_dialog_content = "Ele é guardado por Matthieu e Loewe da Sala de Justiça e alguns guardas.",
  ui_story_5032_50320301_21_dialog_content = "Juiz Matthieu, este é o homem que Elvis pediu para ver.",
  ui_story_5032_50320301_22_dialog_content = "Tsk, este é o plebeu? Ele tem falado e falado sobre você. Jeno isso, Jeno aquilo. Estou farto de ouvir isso.",
  ui_story_5032_50320301_23_dialog_content = "...",
  ui_story_5032_50320301_24_dialog_content = "Vou avisá-lo agora, sem truques. Se você tentar qualquer coisa, atacaremos sem aviso prévio.",
  ui_story_5032_50320301_25_dialog_content = "Hunf.",
  ui_story_5032_50320301_26_dialog_content = "<color=#e8d9bb>Clique</color>",
  ui_story_5032_50320301_27_dialog_content = "Jeno? É você, Jeno!?",
  ui_story_5032_50320301_28_dialog_content = "Você finalmente veio me ver.",
  ui_story_5032_50320301_29_dialog_content = "Hmm...",
  ui_story_5032_50320301_30_dialog_content = "Não entenda mal. Só estou aqui para ver o que acontece com traidores traiçoeiros.",
  ui_story_5032_50320301_31_dialog_content = "Eu não esperava encontrar você em uma acomodação tão confortável.",
  ui_story_5032_50320301_32_dialog_content = "Parece injusto quando você pensa em todo o dano que fez à minha Esmeralda.",
  ui_story_5032_50320301_33_dialog_content = "Você sabe o quanto todo mundo tem que trabalhar para repará-lo?",
  ui_story_5032_50320301_34_dialog_content = "E você se senta aqui, descansando em seu quarto limpo e confortável.",
  ui_story_5032_50320301_35_dialog_content = "Jeno, eu realmente sinto muito.",
  ui_story_5032_50320301_36_dialog_content = "Por favor, acredite em mim, e se eu tivesse outra escolha, eu não teria te machucado.",
  ui_story_5032_50320301_37_dialog_content = "Mas você fez. Não foi?",
  ui_story_5032_50320301_38_dialog_content = "Fatos são fatos e não podemos mudá-los. Então, qual é o ponto de pedir desculpas?",
  ui_story_5032_50320301_39_dialog_content = "Ouvi dizer que você se recusou a comer e beber e insistiu em me ver.",
  ui_story_5032_50320301_40_dialog_content = "O que você espera? Que eu vou ouvir suas desculpas tediosas e perdoá-lo por tudo que você fez?",
  ui_story_5032_50320301_41_dialog_content = "Dizer-me pessoalmente o quanto você se arrepende de tudo isso aliviará um pouco sua consciência?",
  ui_story_5032_50320301_42_dialog_content = "Jeno... Eu sei o quanto te devo.",
  ui_story_5032_50320301_43_dialog_content = "Mas há algumas coisas que só posso dizer a você.",
  ui_story_5032_50320301_44_dialog_content = "Coisas que serão significativas apenas para você.",
  ui_story_5032_50320301_45_dialog_content = "Não espero que nada do que você diga seja significativo.",
  ui_story_5032_50320301_46_dialog_content = "Olhe para si mesmo, Elvis. Você é patético.",
  ui_story_5032_50320301_47_dialog_content = "Sim. Eu sei o quão longe eu caí.",
  ui_story_5032_50320301_48_dialog_content = "Eu devo parecer como eu fiz <color=#FFB400>aquela vez eu machuquei minha perna</color>, lutando contra esses bandidos.",
  ui_story_5032_50320301_49_dialog_content = "Lembro-me de como você zombou de mim.",
  ui_story_5032_50320301_50_dialog_content = "Eu não vim aqui para relembrar.",
  ui_story_5032_50320301_51_dialog_content = "Eu sinto Muito. Achei que uma vez você disse que era uma pessoa nostálgica... Achei que gostaria de se lembrar dos velhos tempos.",
  ui_story_5032_50320301_52_dialog_content = "Afinal, todo mundo tem pequenos segredos escondidos em suas memórias.",
  ui_story_5032_50320301_53_dialog_content = "Não estou com humor para lembrar do passado. E eu nem me lembro que você machucou a perna.",
  ui_story_5032_50320301_54_dialog_content = "Não, você faz. Tenho certeza que sim.",
  ui_story_5032_50320301_55_dialog_content = "Assim como você sabe o significado dos segredos.",
  ui_story_5032_50320301_56_dialog_content = "Baboseira!",
  ui_story_5032_50320301_57_dialog_content = "Isso não tem sentido. Se isso é tudo que você tem a dizer, economize seu fôlego. Eu não estou interessado.",
  ui_story_5032_50320301_58_dialog_content = "Jeno!",
  ui_story_5032_50320301_59_dialog_content = "Jeno acabou de sair assim?",
  ui_story_5032_50320301_60_dialog_content = "Ele parecia furioso...",
  ui_story_5032_50320301_61_dialog_content = "Não conheço a história entre vocês dois, mas talvez devesse tentar um pedido de desculpas mais sincero.",
  ui_story_5032_50320301_62_dialog_content = "De qualquer forma, você quer comer alguma coisa, agora que deixamos você ver Jeno?",
  ui_story_5032_50320301_63_dialog_content = "Hum. Obrigada pelo conselho, PlayerName.",
  ui_story_5032_50320301_64_dialog_content = "Elvis! Você está bem?",
  ui_story_5032_50320301_65_dialog_content = "Não se preocupe. É só minha perna. E eles não vão intimidá-lo assim novamente.",
  ui_story_5032_50320301_66_dialog_content = "Me desculpe... É tudo minha culpa.",
  ui_story_5032_50320301_67_dialog_content = "Eu disse para você não se preocupar com isso. Então esta é a base secreta que você encontrou?",
  ui_story_5032_50320301_68_dialog_content = "Sim. Não há quase ninguém aqui e é perfeito para pintar.",
  ui_story_5032_50320301_69_dialog_content = "Vamos entrar então! Pode ser um lugar legal para esconder coisas também. Talvez eu mantenha meu diário aqui.",
  ui_story_5032_50320301_70_dialog_content = "Eh? Eu não sabia que você tinha um diário.",
  ui_story_5032_50320301_71_dialog_content = "Sim, mas talvez eu comece um.",
  ui_story_5032_50320301_72_dialog_content = "Afinal, uma base secreta é perfeita para guardar segredos.",
  ui_story_5032_50320301_73_dialog_content = "<color=#e8d9bb>Os arredores de Harbour City</color>",
  ui_story_5032_50320301_74_dialog_content = "O que você deixou aqui que você quer tanto que eu encontre?",
  ui_story_5032_50320301_75_dialog_content = "Certamente não pode ser aquele diário estúpido...",
  ui_story_5032_50320301_76_dialog_content = "Graagh—!",
  ui_story_5032_50320301_77_dialog_content = "Eu não posso acreditar que há Eclipses aqui.",
  ui_story_5032_50320301_78_dialog_content = "Aaargh!",
  ui_story_5032_50320301_79_dialog_content = "Saia do caminho!",
  ui_story_5032_50320302_1_dialog_content = "Graagh—",
  ui_story_5032_50320302_2_dialog_content = "Acho que foi o último.",
  ui_story_5032_50320302_3_dialog_content = "A árvore que Eclipsite atingiu foi a mesma em que Elvis descansou quando machucou a perna.",
  ui_story_5032_50320302_4_dialog_content = "Ficou tão alto.",
  ui_story_5032_50320302_5_dialog_content = "Realmente existe uma carta. Que clichê.",
  ui_story_5032_50320302_6_dialog_content = "E eu deveria apenas ler?",
  ui_story_5032_50320302_7_dialog_content = "As tramas secretas devem ser um pouco mais criativas do que isso.",
  ui_story_5032_50320302_8_dialog_content = "Eu deveria desmontar esse seu plano ridículo...",
  ui_story_5032_50320302_9_dialog_content = "Não, talvez eu devesse ler. Pode proporcionar boas risadas.",
  ui_story_5032_50320302_10_dialog_content = "Já que eu já decidi não te perdoar, o que uma carta vai fazer para mudar isso?",
  ui_story_5032_50320302_11_dialog_content = "Mesmo agora, Jeno, você ainda quer saber que desculpas patéticas ele tem, não é?",
  ui_story_5032_50320302_12_dialog_content = "Você é tão risível quanto ele.",
  ui_story_5032_50320302_13_dialog_content = "Muito bem. Vou ver o que mais você tem a dizer por si mesmo.",
  ui_story_5032_50320302_14_dialog_content = "Ao meu querido amigo Jeno",
  ui_story_5032_50320302_15_dialog_content = "Quando você ler isso, talvez eu tenha libertado o povo de Harbour City da maldição que eles sofrem.",
  ui_story_5032_50320302_16_dialog_content = "Ou, se meu plano falhou, posso ter me tornado um prisioneiro.",
  ui_story_5032_50320302_17_dialog_content = "Mas seja qual for o caso, preciso urgentemente de sua ajuda.",
  ui_story_5032_50320302_18_dialog_content = "Eu imploro, leia esta carta até o fim.",
  ui_story_5032_50320302_19_dialog_content = "Você provavelmente já sabe que meu alvo era o núcleo de energia da Esmeralda.",
  ui_story_5032_50320302_20_dialog_content = "Eu me perguntei várias vezes se deveria revelar meus planos para você. Afinal, houve um tempo em que não tínhamos segredos um para o outro.",
  ui_story_5032_50320302_21_dialog_content = "Mas depois de tantos anos separados, podemos ter nos tornado pessoas muito diferentes.",
  ui_story_5032_50320302_22_dialog_content = "E anos de jogos políticos me fizeram desconfiar de confiar nos outros.",
  ui_story_5032_50320302_23_dialog_content = "Mesmo quando nos encontramos mais uma vez, eu ainda não conseguia confiar totalmente em você.",
  ui_story_5032_50320302_24_dialog_content = "Foi então que eu vi em seus olhos – a Esmeralda é mais do que um mero navio para você.",
  ui_story_5032_50320302_25_dialog_content = "Tornou-se uma casa. Uma casa para você, sua família e seus amigos.",
  ui_story_5032_50320302_26_dialog_content = "E você se tornou um membro da Verdadeira Ordem.",
  ui_story_5032_50320302_27_dialog_content = "Não posso dizer a verdade ou arcar com as consequências caso outras forças aprendam sobre o núcleo de energia.",
  ui_story_5032_50320302_28_dialog_content = "É a última esperança para Harbour City e aquelas pobres almas amaldiçoadas que vivem aqui.",
  ui_story_5032_50320302_29_dialog_content = "o <color=#FFB400>Pedra do Vento</color>O selo de 's está enfraquecendo. Se isso continuar, Harbour City está fadada à destruição.",
  ui_story_5032_50320302_30_dialog_content = "Preciso de sua ajuda e prometo explicar tudo pessoalmente. Mas devo completar o ritual assim que puder.",
  ui_story_5032_50320302_31_dialog_content = "Espero que você dê uma mãozinha a este lugar, sua antiga casa. E eu, seu ex-amigo.",
  ui_story_5032_50320302_32_dialog_content = "Era isso que você queria dizer?",
  ui_story_5032_50320302_33_dialog_content = "Você acha que pode me enganar de novo com uma mera carta?",
  ui_story_5032_50320302_34_dialog_content = "Você acha que eu vou te perdoar agora?",
  ui_story_5032_50320302_35_dialog_content = "<color=#e8d9bb>Tzzst—</color>",
  ui_story_5032_50320302_36_dialog_content = "Seu tolo, Elvis.",
  ui_story_5032_50320401_1_dialog_content = "Carleen, estamos de volta.",
  ui_story_5032_50320401_2_dialog_content = "Bem vindo de volta. Como foi?",
  ui_story_5032_50320401_3_dialog_content = "E onde está Jeno? Achei que ele estaria com você.",
  ui_story_5032_50320401_4_dialog_content = "Ele lutou com Elvis e depois foi embora. Não conseguimos impedi-lo.",
  ui_story_5032_50320401_5_dialog_content = "Imaginado tanto. Ele deve ter muita coisa na cabeça agora...",
  ui_story_5032_50320401_6_dialog_content = "Depois de tudo o que aconteceu, ele provavelmente precisa de algum tempo sozinho para pensar sobre as coisas.",
  ui_story_5032_50320401_7_dialog_content = "Devemos dar-lhe esse espaço.",
  ui_story_5032_50320401_8_dialog_content = "Ainda acho que Elvis está escondendo algo importante de nós.",
  ui_story_5032_50320401_9_dialog_content = "Mas não temos ideia do que está acontecendo dentro de sua cabeça.",
  ui_story_5032_50320401_10_dialog_content = "Sim...",
  ui_story_5032_50320401_11_dialog_content = "Carleen, você tem alguma ideia?",
  ui_story_5032_50320401_12_dialog_content = "A coisa mais importante agora é descobrir o que Elvis estava fazendo e por que os Eclipsites começaram a aparecer.",
  ui_story_5032_50320401_13_dialog_content = "Aqui está um palpite. O aumento de Eclipsites pode estar ligado ao selo que Elvis mencionou.",
  ui_story_5032_50320401_14_dialog_content = "Bem, já que ele não vai nos dizer nada, teremos que encontrar outra maneira de chegar ao fundo disso.",
  ui_story_5032_50320401_15_dialog_content = "Mas por onde começamos?",
  ui_story_5032_50320401_16_dialog_content = "Lembro-me de algo que Elvis disse uma vez—",
  ui_story_5032_50320401_17_dialog_content = "Você também encontrará as informações de que precisa, depois de ler todos os livros deste mundo.",
  ui_story_5032_50320401_18_dialog_content = "então o que devemos fazer? Ler todos os livros do Astra?",
  ui_story_5032_50320401_19_dialog_content = "Não. Apenas todos os livros que Elvis já leu.",
  ui_story_5032_50320401_20_dialog_content = "Lembro que havia uma pequena biblioteca em sua mansão. Devemos ser capazes de encontrar algumas pistas lá.",
  ui_story_5032_50320401_21_dialog_content = "Eu vou e ajudo. Um par extra de olhos vai acelerar as coisas.",
  ui_story_5032_50320401_22_dialog_content = "Sim eu também.",
  ui_story_5032_50320401_23_dialog_content = "<color=#e8d9bb>A biblioteca, a mansão de Elvis</color>",
  ui_story_5032_50320401_24_dialog_content = "Você... Você chama isso de uma pequena biblioteca!?",
  ui_story_5032_50320401_25_dialog_content = "Quero dizer, o quarto não é muito grande...",
  ui_story_5032_50320401_26_dialog_content = "Mas está cheio de estantes. E as estantes estão cheias de livros.",
  ui_story_5032_50320401_27_dialog_content = "Levaremos um ano para ler tudo isso. Não, dois anos, no mínimo!",
  ui_story_5032_50320401_28_dialog_content = "E veja, os livros estão todos caindo aos pedaços. Elvis deve tê-los lido várias vezes.",
  ui_story_5032_50320401_29_dialog_content = "O que ele esperava aprender com isso?",
  ui_story_5032_50320401_30_option_content = "Talvez ele estivesse estudando história?",
  ui_story_5032_50320401_31_dialog_content = "Elvis queria curar a Síndrome de Modali, então ele provavelmente estava procurando por pistas sobre a Linhagem Heroica.",
  ui_story_5032_50320401_32_dialog_content = "A Heroic Bloodline tem raízes profundas na história de Harbour City.",
  ui_story_5032_50320401_33_dialog_content = "Se eu quisesse aprender sobre a Síndrome de Modali, começaria com a história de Harbour City.",
  ui_story_5032_50320401_34_dialog_content = "Isso é verdade. É uma história cheia de mistérios não resolvidos.",
  ui_story_5032_50320401_35_dialog_content = "Talvez um desses mistérios tenha algo a ver com a Síndrome de Modali?",
  ui_story_5032_50320401_36_option_content = "Talvez ele estivesse pesquisando a Síndrome de Modali?",
  ui_story_5032_50320401_37_dialog_content = "Ele se importava mais com isso do que com qualquer outra coisa, não é?",
  ui_story_5032_50320401_38_dialog_content = "A doença que ele, assim como quem sabe quantos cidadãos de Harbour City, sofre.",
  ui_story_5032_50320401_39_dialog_content = "Mas os estudiosos vêm tentando descobrir o que causa isso há séculos e ainda não conseguiram.",
  ui_story_5032_50320401_40_dialog_content = "Para onde Elvis começaria a procurar?",
  ui_story_5032_50320401_41_dialog_content = "Bem, é uma doença local. Portanto, a melhor abordagem pode ser olhar para a história local.",
  ui_story_5032_50320401_42_dialog_content = "Então vamos começar com os livros de história.",
  ui_story_5032_50320401_43_dialog_content = "OK. Vou juntar todos os livros de história, e vocês podem começar a lê-los!",
  ui_story_5032_50320401_44_dialog_content = "Deixe com a gente!",
  ui_story_5032_50320401_45_dialog_content = "As Crônicas de Astra, A Enciclopédia da História, A História Secreta de Lumopolis...",
  ui_story_5032_50320401_46_dialog_content = "Huh? E por que há uma cópia de The Legendary Heroes of Harbor City na prateleira de história?",
  ui_story_5032_50320401_47_dialog_content = "Este não é mais um livro de mitologia? Seja o que for, eu vou trazê-lo.",
  ui_story_5032_50320401_48_dialog_content = "Vice, Carleen, aqui estão os livros.",
  ui_story_5032_50320401_49_dialog_content = "Ok, coloque-os aqui e vamos começar a ler.",
  ui_story_5032_50320401_50_dialog_content = "Obrigada, PlayerName.",
  ui_story_5032_50320401_51_dialog_content = "Sem problemas. Acho que tem mais livros de história por lá. Eu vou verificar.",
  ui_story_5032_50320401_52_dialog_content = "<color=#e8d9bb>Algum tempo depois</color>",
  ui_story_5032_50320401_53_dialog_content = "Ufa. Certo, esses são todos os livros com a palavra \"história\" no título e qualquer coisa que pareça... você sabe, histórico.",
  ui_story_5032_50320401_54_dialog_content = "Como vão as coisas? Encontrou alguma coisa ainda?",
  ui_story_5032_50320401_55_dialog_content = "Há algo estranho nesses livros. Aqueles sobre Harbour City estão todos de acordo em sua história inicial.",
  ui_story_5032_50320401_56_dialog_content = "Mas assim que lemos os bits mais recentes, todos eles divergem.",
  ui_story_5032_50320401_57_dialog_content = "E nem parece história. É mais como histórias inventadas.",
  ui_story_5032_50320401_58_dialog_content = "Sim. Como este, As Crônicas de Astra, diz o seguinte:",
  ui_story_5032_50320401_59_dialog_content = "\"Houve uma vez uma batalha sangrenta entre os antigos heróis e os Eclipsitas perto de Harbour City.\"",
  ui_story_5032_50320401_60_dialog_content = "\"Os espíritos odiosos dos Eclipsitas tornaram-se uma maldição que atormentou os descendentes dos heróis.\"",
  ui_story_5032_50320401_61_dialog_content = "Não é essa a lenda que ouvimos inicialmente?",
  ui_story_5032_50320401_62_dialog_content = "Mas é apenas uma lenda, certo? Se as maldições realmente existissem, o mundo inteiro cairia no caos...",
  ui_story_5032_50320401_63_dialog_content = "Esse pelo menos soa meio crível. Este, The Legendary Heroes of Harbor City, é ainda mais estranho.",
  ui_story_5032_50320401_64_dialog_content = "\"Harbour City é protegida pelos heróis antigos e, portanto, não é molestada pelos Eclipsites.\"",
  ui_story_5032_50320401_65_dialog_content = "\"Embora os Eclipsitas possam se aproximar da cidade, eles logo são eliminados silenciosamente pelos heróis.\"",
  ui_story_5032_50320401_66_dialog_content = "Isso é bizarro!",
  ui_story_5032_50320401_67_dialog_content = "Não é?",
  ui_story_5032_50320401_68_dialog_content = "Eh? Este livro diz...",
  ui_story_5032_50320401_69_dialog_content = "Vice, o que você tem?",
  ui_story_5032_50320401_70_dialog_content = "É A História Secreta de Lumopolis. Diz que os moradores de Harbour City uma vez escavaram um local de ruínas antigas.",
  ui_story_5032_50320401_71_dialog_content = "E em ruínas, eles encontraram uma pedra estranha. E se a pedra fosse infundida com Lumina, poderia <color=#FFB400>repelir eclipsitos próximos</color>.",
  ui_story_5032_50320401_72_dialog_content = "Isso soa familiar. Seria como uma versão em miniatura da barreira de Lumopolis.",
  ui_story_5032_50320401_73_dialog_content = "Não interrompa, PlayerName. Eu não terminei.",
  ui_story_5032_50320401_74_dialog_content = "Oh, desculpe. O que aconteceu depois?",
  ui_story_5032_50320401_75_dialog_content = "Aqui está o que diz—",
  ui_story_5032_50320401_76_dialog_content = "\"Mas como a pedra exigia <color=#FFB400>muito Lumina</color> para funcionar, nenhuma fonte poderia mantê-lo funcionando constantemente.\"",
  ui_story_5032_50320401_77_dialog_content = "\"E assim passou a ser considerado sem valor e mais tarde foi perdido.\"",
  ui_story_5032_50320401_78_dialog_content = "Parece uma lenda sem sentido. Continue olhando.",
  ui_story_5032_50320401_79_dialog_content = "Embora... O poder que repele Eclipsites? Isso me lembra algo que li em um livro em Lumopolis.",
  ui_story_5032_50320401_80_dialog_content = "Em algum momento no passado, uma horda de Eclipsitas se reuniu na área de Harbour City. Os moradores lutaram e sofreram com eles por anos.",
  ui_story_5032_50320401_81_dialog_content = "Então, um dia, os Eclipsites de repente desapareceram e a cidade ficou livre para prosperar.",
  ui_story_5032_50320401_82_dialog_content = "Então, o que os fez desaparecer?",
  ui_story_5032_50320401_83_dialog_content = "Nenhuma idéia. Acho que é apenas um daqueles mistérios não resolvidos de Harbour City.",
  ui_story_5032_50320401_84_dialog_content = "Ai, meu pescoço. Estou lendo há tanto tempo que ficou duro.",
  ui_story_5032_50320401_85_dialog_content = "Dar um tempo. Vou ler o resto para você.",
  ui_story_5032_50320401_86_dialog_content = "Ah, obrigado, PlayerName.",
  ui_story_5032_50320401_87_dialog_content = "Vou tirar uma soneca contra este livro cas—woah!!",
  ui_story_5032_50320401_88_dialog_content = "O que há de errado? Você esbarrou em algo?",
  ui_story_5032_50320401_89_dialog_content = "N-não. Eu acidentalmente empurrei um desses livros.",
  ui_story_5032_50320401_90_dialog_content = "É um terremoto?",
  ui_story_5032_50320401_91_dialog_content = "Não.",
  ui_story_5032_50320401_92_dialog_content = "Olha, é aquela parede ali. Está a mover-se!",
  ui_story_5032_50320401_93_dialog_content = "E olhe, há algo atrás da parede. Seu...",
  ui_story_5032_50320401_94_dialog_content = "Uma mesa cheia de documentos manuscritos?",
  ui_story_5032_50320401_95_dialog_content = "Se Elvis os escondeu com tanto cuidado, devem ser importantes.",
  ui_story_5032_50320401_96_dialog_content = "E nunca teríamos encontrado a sala secreta se não fosse pela boa sorte de Vice.",
  ui_story_5032_50320401_97_dialog_content = "Vamos ver o que dizem esses documentos.",
  ui_story_5032_50320401_98_dialog_content = "As páginas de cima estão amareladas. Devem ser mais velhos.",
  ui_story_5032_50320401_99_dialog_content = "Venho por este meio começar a minha pesquisa sobre o Windstone. Não só para mim, mas para o futuro dos cidadãos de Harbour City.",
  ui_story_5032_50320401_100_dialog_content = "É a caligrafia de Elvis. Ele realmente estava fazendo uma pesquisa secreta. Mas o que é o Windstone?",
  ui_story_5032_50320401_101_dialog_content = "Não sei. Mas se ele estiver estudando, deve haver mais informações mais tarde!",
  ui_story_5032_50320401_102_dialog_content = "Minha pesquisa descobriu que o Windstone contém um dispositivo que pode armazenar energia.",
  ui_story_5032_50320401_103_dialog_content = "Sua reserva de energia e os fornecimentos intermitentes de Lumina dos Aurorianos conseguiram mantê-lo operando até hoje.",
  ui_story_5032_50320401_104_dialog_content = "Mas está consumindo mais energia do que pode ser fornecida, e sua reserva de energia está quase esgotada.",
  ui_story_5032_50320401_105_dialog_content = "Eu posso sentir o poder do Windstone enfraquecendo, e estamos começando a ver Eclipsitos aparecerem perto de Harbour City.",
  ui_story_5032_50320401_106_dialog_content = "Se isso continuar, não demorará muito para que a cidade seja novamente atormentada por Eclipsitas.",
  ui_story_5032_50320401_107_dialog_content = "O tempo está passando. Devo pensar em algo.",
  ui_story_5032_50320401_108_dialog_content = "Então parece que o Windstone é algum tipo de aparelho com poderes especiais.",
  ui_story_5032_50320401_109_dialog_content = "Então, poderia ser por isso que Harbour City estava a salvo dos Eclipsites por tanto tempo?",
  ui_story_5032_50320401_110_dialog_content = "O que está descrito aqui certamente combina com a situação real de Harbour City.",
  ui_story_5032_50320401_111_dialog_content = "No passado, nenhum Eclipsite jamais pôs os pés em Harbour City. Mas recentemente, tem havido muitos relatos de Eclipsitas atacando Aurorianos.",
  ui_story_5032_50320401_112_dialog_content = "Se o enfraquecimento do chamado Windstone é a causa, esse fenômeno não é um bom presságio.",
  ui_story_5032_50320401_113_dialog_content = "Vamos continuar lendo. Os artigos abaixo parecem mais recentes, então a redação deve ser mais recente.",
  ui_story_5032_50320401_114_dialog_content = "Folheei todos os livros de história que pude encontrar, procurando a origem do Windstone.",
  ui_story_5032_50320401_115_dialog_content = "Meus ancestrais desenterraram Windstone nas ruínas e descobriram que ela tem grande poder, suficiente para selar os Eclipsitas.",
  ui_story_5032_50320401_116_dialog_content = "Para proteger a pátria, eles fizeram um pacto de sangue com o Windstone e forneceram o Lumina necessário para operar.",
  ui_story_5032_50320401_117_dialog_content = "E assim, o poder de Windstone colocou os Eclipsites que assediavam Harbour City em um sono profundo.",
  ui_story_5032_50320401_118_dialog_content = "Mas se o Windstone parar de funcionar, os Eclipsites vão acordar e saquear Harbour City novamente.",
  ui_story_5032_50320401_119_dialog_content = "O pacto de selo e sangue... Isso soa como o poder mencionado naquele livro.",
  ui_story_5032_50320401_120_dialog_content = "Não é um boato sem fundamento?",
  ui_story_5032_50320401_121_dialog_content = "E supostamente, o Windstone precisava de um Lumina maciço para funcionar, então eles desistiram.",
  ui_story_5032_50320401_122_dialog_content = "Vamos em frente.",
  ui_story_5032_50320401_123_dialog_content = "A pesquisa finalmente progrediu.",
  ui_story_5032_50320401_124_dialog_content = "Windstone é capaz de identificar os contratantes e seus parentes de sangue, bem como absorver automaticamente Lumina de tais aurorianos.",
  ui_story_5032_50320401_125_dialog_content = "Agora que a pedra está quase exausta, ela começa a absorver Lumina sem restrições.",
  ui_story_5032_50320401_126_dialog_content = "Mas mesmo que pudesse tirar tudo daqueles Aurorianos, ainda não teria Lumina suficiente.",
  ui_story_5032_50320401_127_dialog_content = "Quando o suprimento finalmente acabar, todos os Aurorianos nascidos dessa linhagem morrerão pela perda de Lumina.",
  ui_story_5032_50320401_128_dialog_content = "Ah... não me diga...",
  ui_story_5032_50320401_129_dialog_content = "Essa é provavelmente a raiz da Síndrome de Modali.",
  ui_story_5032_50320401_130_dialog_content = "Elvis... e seu clã estão usando seus Lumina e até mesmo vidas para alimentar o Windstone.",
  ui_story_5032_50320401_131_dialog_content = "Mas por que? Não há maneira melhor?",
  ui_story_5032_50320401_132_dialog_content = "Elvis nunca relatou a Lumopolis como o laird de Harbour City.",
  ui_story_5032_50320401_133_dialog_content = "Por que ele faria isso?",
  ui_story_5032_50320401_134_dialog_content = "O Windstone está ficando ainda mais fraco. Pior ainda, Lumopolis lançou uma investigação secreta de Harbour City.",
  ui_story_5032_50320401_135_dialog_content = "Windstone é provavelmente apenas um brinquedo interessante para os nobres Lumo.",
  ui_story_5032_50320401_136_dialog_content = "O mesmo vale para os cientistas da Illumina. Uma vez conhecida a presença de Windstone, certamente enviarão pessoas para aproveitá-la.",
  ui_story_5032_50320401_137_dialog_content = "Para Harbour City, a pedra é a base de sua existência, a coisa crítica que impede que as pessoas sejam deslocadas.",
  ui_story_5032_50320401_138_dialog_content = "Devo mantê-lo em um lugar absolutamente seguro e insuspeito para que pessoas de fora não saibam disso.",
  ui_story_5032_50320401_139_dialog_content = "A boa notícia é que há um avanço no estudo.",
  ui_story_5032_50320401_140_dialog_content = "Depois de inúmeras falhas, finalmente encontrei uma maneira de a pedra ser alimentada por outra fonte.",
  ui_story_5032_50320401_141_dialog_content = "Tudo o que resta agora é ir ao terreno selado para reiniciá-lo.",
  ui_story_5032_50320401_142_dialog_content = "Essa é a última passagem, escrita às pressas.",
  ui_story_5032_50320401_143_dialog_content = "Em algum lugar absolutamente seguro... Essa estranha pedra no cetro de Elvis pode ser a Windstone real?",
  ui_story_5032_50320401_144_dialog_content = "Lumopolis não é confiável para você, Elvis?",
  ui_story_5032_50320401_145_dialog_content = "Carleen...",
  ui_story_5032_50320401_146_dialog_content = "Explique a Elvis quando tiver oportunidade.",
  ui_story_5032_50320401_147_dialog_content = "Vice e eu podemos provar que você é uma pessoa confiável!",
  ui_story_5032_50320401_148_dialog_content = "Tudo bem... Obrigado.",
  ui_story_5032_50320401_149_dialog_content = "O manuscrito terminou com Elvis dizendo que encontrou uma maneira de o Windstone usar outra fonte de energia.",
  ui_story_5032_50320401_150_dialog_content = "Windstone, Lumina, energia massiva...",
  ui_story_5032_50320401_151_dialog_content = "Eu entendi. Ele queria que o núcleo de energia do navio de circo alimentasse a pedra.",
  ui_story_5032_50320401_152_dialog_content = "Por isso buscou o núcleo mesmo ao custo de romper com os amigos...",
  ui_story_5032_50320401_153_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5032_50320401_154_dialog_content = "Rápido, ali!",
  ui_story_5032_50320401_155_dialog_content = "O que está acontecendo? Por que todo o barulho?",
  ui_story_5032_50320401_156_dialog_content = "Pare esse homem! Ele saiu da prisão!",
  ui_story_5032_50320401_157_dialog_content = "Uma fuga da prisão?!",
  ui_story_5032_50320401_158_dialog_content = "Não me diga que é Elvis?!",
  ui_story_5032_50320401_159_dialog_content = "Vamos, vamos verificar!",
  ui_story_5032_50320501_1_dialog_content = "Por favor, mantenha seus olhos no suspeito.",
  ui_story_5032_50320501_2_dialog_content = "Eu tenho que sair por meia hora.",
  ui_story_5032_50320501_3_dialog_content = "Vai tomar banho de novo?",
  ui_story_5032_50320501_4_dialog_content = "Harbour City está tão úmido e abafado agora.",
  ui_story_5032_50320501_5_dialog_content = "Você ficará coberto de suor pegajoso depois de tomar banho, de qualquer maneira.",
  ui_story_5032_50320501_6_dialog_content = "A quarta vez? Para hoje?",
  ui_story_5032_50320501_7_dialog_content = "Eu não me importo que você pegue um e adicione-o à minha contagem.",
  ui_story_5032_50320501_8_dialog_content = "Sou juiz assistente.",
  ui_story_5032_50320501_9_dialog_content = "Não não. Tecnicamente, você é um juiz assistente bastante fedido.",
  ui_story_5032_50320501_10_dialog_content = "!!",
  ui_story_5032_50320501_11_dialog_content = "Huh? Você está perturbado?",
  ui_story_5032_50320501_12_dialog_content = "Deixa para lá. Vou tomar um banho, quer você goste ou não.",
  ui_story_5032_50320501_13_dialog_content = "Mantenha os olhos grudados no laird.",
  ui_story_5032_50320501_14_dialog_content = "No entanto, isso pode ser discutível. Ele ainda tem problemas em ficar de pé sem seu cetro.",
  ui_story_5032_50320501_15_dialog_content = "Quem sabe se ele conseguiria chegar ao tribunal...",
  ui_story_5032_50320501_16_dialog_content = "...",
  ui_story_5032_50320501_17_dialog_content = "Jeno vai pegar a carta que deixei para ele?",
  ui_story_5032_50320501_18_dialog_content = "Ou não, ou talvez ainda não me perdoe depois de lê-lo.",
  ui_story_5032_50320501_19_dialog_content = "Eu sei que continuo traindo sua confiança, então não devo ter nenhuma esperança.",
  ui_story_5032_50320501_20_dialog_content = "Sinto muito, Jeno... Mas você é o único que pode ajudar as pessoas de Harbour City e a mim.",
  ui_story_5032_50320501_21_dialog_content = "<color=#e8d9bb>Clic.</color>",
  ui_story_5032_50320501_22_dialog_content = "Você terminou de resmungar?",
  ui_story_5032_50320501_23_dialog_content = "Se sim, venha comigo.",
  ui_story_5032_50320501_24_dialog_content = "Jeno!",
  ui_story_5032_50320501_25_dialog_content = "Não fique muito animado lá.",
  ui_story_5032_50320501_26_dialog_content = "Você tem que me contar tudo, mais o que planeja fazer a seguir.",
  ui_story_5032_50320501_27_dialog_content = "Ou eu mesmo te jogo de volta aqui.",
  ui_story_5032_50320501_28_dialog_content = "...",
  ui_story_5032_50320501_29_dialog_content = "Por que os guardas não atacam ou dão alarmes?",
  ui_story_5032_50320501_30_dialog_content = "Eles nem estão olhando para nós, como se nada estivesse acontecendo.",
  ui_story_5032_50320501_31_dialog_content = "Tal é o poder do Deck de Origem. Isso os faz alucinar.",
  ui_story_5032_50320501_32_dialog_content = "Mas os guardas são muito complacentes, e isso me deu a oportunidade.",
  ui_story_5032_50320501_33_dialog_content = "Só o juiz de Lumopolis me fez trabalhar um pouco.",
  ui_story_5032_50320501_34_dialog_content = "Acho que eles não esperavam que ninguém te libertasse.",
  ui_story_5032_50320501_35_dialog_content = "Haha, pena que eles estavam errados.",
  ui_story_5032_50320501_36_dialog_content = "Alucinação, você disse. Então, que outras coisas interessantes você pode fazer com o poder \"Origem\"?",
  ui_story_5032_50320501_37_dialog_content = "Pare de me dar manteiga. Ainda quero uma explicação sua.",
  ui_story_5032_50320501_38_dialog_content = "Eu nem tenho certeza se vou te perdoar ainda.",
  ui_story_5032_50320501_39_dialog_content = "Mas pelo que Lady Victoria disse...",
  ui_story_5032_50320501_40_dialog_content = "O Origin Deck é multiuso quando se trata de <color=#FFB400>conversão de energia</color>.",
  ui_story_5032_50320501_41_dialog_content = "Eu ainda tenho que dominar um monte de usos. É realmente uma boa ferramenta para o mago.",
  ui_story_5032_50320501_42_dialog_content = "Mas os guardas vão sair dessa logo e perceber que você se foi.",
  ui_story_5032_50320501_43_dialog_content = "Muito interessante. Eu realmente gostaria de ver uma performance em algum momento.",
  ui_story_5032_50320501_44_dialog_content = "Tenho certeza que terei uma chance no futuro.",
  ui_story_5032_50320501_45_dialog_content = "Tenha certeza, eu decidi ser limpo para você.",
  ui_story_5032_50320501_46_dialog_content = "Só saber que não preciso esconder nada quando falo com você a partir de agora está me deixando muito feliz.",
  ui_story_5032_50320501_47_dialog_content = "Você deveria saber que ainda é o laird e que temos uma grande bagunça para limpar.",
  ui_story_5032_50320501_48_dialog_content = "Então pare de tentar resolver problemas pela força como quando você era criança.",
  ui_story_5032_50320501_49_dialog_content = "É claro. Eu já te disse que te contaria tudo!",
  ui_story_5032_50320501_50_dialog_content = "Ei! Acorda, Loewe!",
  ui_story_5032_50320501_51_dialog_content = "Humph, ele não está se levantando.",
  ui_story_5032_50320501_52_dialog_content = "Malvado Elvis... Aquele palhaço do Jeno deve ter feito isso!",
  ui_story_5032_50320501_53_dialog_content = "Me envergonhando assim... Não vai escapar mesmo se você for o laird!",
  ui_story_5032_50320501_54_dialog_content = "Vou pegá-lo e depois rasgá-lo em pedaços.",
  ui_story_5032_50320501_55_dialog_content = "Então limpe meus sapatos com aquela cara chata dele!",
  ui_story_5032_50320501_56_dialog_content = "Todos os guardas, peguem Loewe e venham comigo caçar o fugitivo!",
  ui_story_5032_50320501_57_dialog_content = "Sim, senhor!",
  ui_story_5032_50320501_58_dialog_content = "Juiz Matthieu!",
  ui_story_5032_50320501_59_dialog_content = "O que houve?",
  ui_story_5032_50320501_60_dialog_content = "O que está acontecendo, você pergunta?",
  ui_story_5032_50320501_61_dialog_content = "Não sentenciando um criminoso, mas tratando-o como um convidado de honra.",
  ui_story_5032_50320501_62_dialog_content = "Existe algo pior do que deixá-lo escapar?",
  ui_story_5032_50320501_63_dialog_content = "Você está dizendo...",
  ui_story_5032_50320501_64_dialog_content = "Sim, Elvis escapou.",
  ui_story_5032_50320501_65_dialog_content = "E é muito provável que Jeno tenha ajudado!",
  ui_story_5032_50320501_66_dialog_content = "Lembrei-lhe, Alteza, de transferir o criminoso para Lumopolis o mais rápido possível.",
  ui_story_5032_50320501_67_dialog_content = "Com licença, mas temos um fugitivo para pegar, então, por favor, fique fora do meu caminho!",
  ui_story_5032_50320501_68_dialog_content = "O juiz Matthieu parece lívido.",
  ui_story_5032_50320501_69_dialog_content = "Isso é compreensível. Ele também assumiu muitas responsabilidades por apoiar minha investigação de Elvis.",
  ui_story_5032_50320501_70_dialog_content = "Devemos agir agora e pegar Elvis.",
  ui_story_5032_50320501_71_dialog_content = "Pelas pistas que temos, Elvis deve estar tentando reiniciar o Windstone.",
  ui_story_5032_50320501_72_dialog_content = "Sim, já que foi por isso que ele foi atrás do núcleo de energia antes de ser frustrado.",
  ui_story_5032_50320501_73_dialog_content = "Agora que ele está livre, ele deve estar indo para o terreno selado.",
  ui_story_5032_50320501_74_dialog_content = "Isso não é definitivo, ele pode estar se escondendo porque descobriu que descobrimos seu plano.",
  ui_story_5032_50320501_75_dialog_content = "Independentemente disso, temos que ir lá também.",
  ui_story_5032_50320501_76_dialog_content = "Você está pronta para isso, Carleen?",
  ui_story_5032_50320501_77_dialog_content = "Estou bem, não se preocupe.",
  ui_story_5032_50320501_78_dialog_content = "Sem mencionar que temos coisas para dizer a ele pessoalmente.",
  ui_story_5032_50320502_1_dialog_content = "Cuidado!",
  ui_story_5032_50320502_2_dialog_content = "Graaah!",
  ui_story_5032_50320502_3_dialog_content = "Temos mais Eclipses do que antes.",
  ui_story_5032_50320502_4_dialog_content = "Mesmo que não estejamos muito longe de Harbour City.",
  ui_story_5032_50320502_5_dialog_content = "Esses Eclipsites... Será que a Pedra do Vento está enfraquecendo?",
  ui_story_5032_50320502_6_dialog_content = "Foco! Estamos quase no <color=#FFB400>solo selado</color> marcado nas notas de Elvis!",
  ui_story_5032_50320502_7_dialog_content = "Sim!",
  ui_story_5032_50320502_8_dialog_content = "Todos os mistérios serão resolvidos lá.",
  ui_story_5032_50320502_9_dialog_content = "É aqui?",
  ui_story_5032_50320502_10_dialog_content = "Sim. Os ancestrais começaram a Windstone aqui para selar os Eclipsites.",
  ui_story_5032_50320502_11_dialog_content = "Estou confiante em reiniciar a pedra através do dispositivo aqui.",
  ui_story_5032_50320502_12_dialog_content = "Mas não serei perturbado durante o processo, por isso preciso da sua ajuda.",
  ui_story_5032_50320502_13_dialog_content = "Entendido.",
  ui_story_5032_50320502_14_dialog_content = "Eu acredito que você está fazendo isso para o bem das pessoas em Harbour City, por enquanto.",
  ui_story_5032_50320502_15_dialog_content = "<size=30>Pelo menos se encaixa no que eu sempre pensei de você em minha mente.</size>",
  ui_story_5032_50320502_16_dialog_content = "O que é isso, Jeno?",
  ui_story_5032_50320502_17_dialog_content = "Nada. Se o que você diz é verdade, eu vou ajudar por você e por Harbour City.",
  ui_story_5032_50320502_18_dialog_content = "Não tenho nada a esconder de você agora, então confie em mim, Jeno.",
  ui_story_5032_50320502_19_dialog_content = "Além disso, obrigado, Jeno.",
  ui_story_5032_50320502_20_dialog_content = "Elvis! Jeno!",
  ui_story_5032_50320502_21_dialog_content = "Aí está você, Alteza.",
  ui_story_5032_50320502_22_dialog_content = "Afinal, você veio aqui, Elvis.",
  ui_story_5032_50320502_23_dialog_content = "Eu vejo Vice e PlayerName vieram também, todos os rostos familiares e tranquilizadores.",
  ui_story_5032_50320502_24_dialog_content = "Você não deveria estar se movendo em sua condição, Elvis.",
  ui_story_5032_50320502_25_dialog_content = "Eu sei disso, Srta. Vice. Agradeço sua preocupação com um criminoso como eu.",
  ui_story_5032_50320502_26_dialog_content = "Mas tenho algo que devo fazer.",
  ui_story_5032_50320502_27_dialog_content = "Já que está aqui, acho que leu minhas anotações na biblioteca.",
  ui_story_5032_50320502_28_dialog_content = "De uma vez só.",
  ui_story_5032_50320502_29_dialog_content = "Sabemos sua intenção de usar o núcleo de energia da Esmeralda para alimentar a Pedra do Vento.",
  ui_story_5032_50320502_30_dialog_content = "Também sabemos o propósito da pedra, especificamente o quão importante ela é para Harbour City.",
  ui_story_5032_50320502_31_dialog_content = "Mas sua boa intenção não pode cobrir sua culpa.",
  ui_story_5032_50320502_32_dialog_content = "Eu sabia que não poderia manter isso em segredo de você.",
  ui_story_5032_50320502_33_dialog_content = "No entanto, como você já descobriu meu plano, não tenho mais nada a esconder.",
  ui_story_5032_50320502_34_dialog_content = "Você tem razão. Eu sou um criminoso.",
  ui_story_5032_50320502_35_dialog_content = "Mas não tenho muita escolha quando se trata de proteger as pessoas de Harbour City, a fundação da cidade e a Windstone.",
  ui_story_5032_50320502_36_dialog_content = "Se não fosse o poder da linhagem diminuindo e a Pedra do Vento funcionando com fumaça...",
  ui_story_5032_50320502_37_dialog_content = "Talvez eu pudesse encontrar outra maneira melhor.",
  ui_story_5032_50320502_38_dialog_content = "Mas estou ficando sem tempo com meu próprio corpo, assim como com Eclipsites.",
  ui_story_5032_50320502_39_dialog_content = "Não posso arriscar se vou encontrar a solução ideal ou morrer primeiro da Síndrome de Modali.",
  ui_story_5032_50320502_40_dialog_content = "A única coisa que sei é trocar meus momentos finais pelo futuro de Harbour City.",
  ui_story_5032_50320502_41_dialog_content = "Você e o Celestita são a maior variável do meu plano, Alteza.",
  ui_story_5032_50320502_42_dialog_content = "Eu esperava atrasá-lo antes de vir aqui para recarregar a pedra.",
  ui_story_5032_50320502_43_dialog_content = "Mas nem mesmo o <color=#FFB400>Lumothread</color> especificamente adaptado para você pode pará-lo.",
  ui_story_5032_50320502_44_dialog_content = "...",
  ui_story_5032_50320502_45_dialog_content = "Com licença, mas você ainda está usando esse vestido?",
  ui_story_5032_50320502_46_dialog_content = "Ele ainda deve estar absorvendo seu Lumina.",
  ui_story_5032_50320502_47_dialog_content = "Sim, provavelmente atingiu o limite da última vez.",
  ui_story_5032_50320502_48_dialog_content = "PlayerName podia sentir a Lumina dentro do vestido se dissipando parcialmente a cada dia antes de absorver mais de mim.",
  ui_story_5032_50320502_49_dialog_content = "Na verdade, trato essa absorção fraca como um meio de exercer controle sobre Lumina agora.",
  ui_story_5032_50320502_50_dialog_content = "Então o Lumothread agora é apenas uma parte do treinamento para controlar Lumina para você...?",
  ui_story_5032_50320502_51_dialog_content = "Que incrível...",
  ui_story_5032_50320502_52_dialog_content = "Sei que não tenho o direito de fazer nenhum pedido por causa do que fiz, Alteza.",
  ui_story_5032_50320502_53_dialog_content = "Mas eu ainda te imploro...",
  ui_story_5032_50320502_54_dialog_content = "Permita-me recarregar o Windstone antes de me levar.",
  ui_story_5032_50320502_55_dialog_content = "Acredito que você e o Salão da Justiça me darão um julgamento justo.",
  ui_story_5032_50320502_56_dialog_content = "Mas tenho uma missão que eu, Elvis Modali, devo cumprir.",
  ui_story_5032_50320502_57_dialog_content = "E esse é meu pedido final como laird de Harbour City.",
  ui_story_5032_50320502_58_dialog_content = "Entendi.",
  ui_story_5032_50320502_59_dialog_content = "Considerando seu histórico de administrar Harbour City e proteger seu povo...",
  ui_story_5032_50320502_60_dialog_content = "Eu o ajudarei até que Windstone funcione novamente e a cidade esteja segura novamente.",
  ui_story_5032_50320502_61_dialog_content = "Estou muito grato, Alteza.",
  ui_story_5032_50320502_62_dialog_content = "Posso ser um fugitivo, mas permita-me agradecer-lhe como o laird de Harbour City.",
  ui_story_5032_50320502_63_dialog_content = "Vamos dispensar as formalidades. Por favor, recarregue a pedra o mais rápido possível.",
  ui_story_5032_50320502_64_dialog_content = "Fique tranquilo, estou trabalhando para despertar o solo selado.",
  ui_story_5032_50320502_65_dialog_content = "Estou feliz por não estar errado sobre você. Quando te conheci, pude sentir que você é diferente dos outros nobres.",
  ui_story_5032_50320502_66_dialog_content = "Perdoe-me por não confiar completamente em ninguém novo de Lumopolis.",
  ui_story_5032_50320502_67_dialog_content = "Porque tenho certeza que muitos no Conselho dos Anciões cobiçam o poder que protege Harbour City.",
  ui_story_5032_50320502_68_dialog_content = "Ah, se eu tivesse confiado mais em você desde o início e não suspeitasse que você fosse egoísta como aqueles nobres...",
  ui_story_5032_50320502_69_dialog_content = "Talvez tudo tivesse acabado melhor, então.",
  ui_story_5032_50320502_70_dialog_content = "Mas ainda há uma chance.",
  ui_story_5032_50320502_71_dialog_content = "Eu entendo como você se sente sobre o que o Conselho Ancião pode pensar em relação ao núcleo de energia ou Windstone.",
  ui_story_5032_50320502_72_dialog_content = "Eu, no entanto, nunca vou tentar minar o que a fundação de Harbour City.",
  ui_story_5032_50320502_73_dialog_content = "Os Eclipsitas são o inimigo comum, afinal, e você receberá um julgamento justo por seus erros.",
  ui_story_5032_50320502_74_dialog_content = "Mas, por enquanto, posso prometer que nenhum eclipse chegará perto de você.",
  ui_story_5032_50320502_75_dialog_content = "Obrigado, Alteza.",
  ui_story_5032_50320502_76_dialog_content = "Vamos começar, então.",
  ui_story_5032_50320502_77_dialog_content = "Vire uma nova página na história de Harbour City.",
  ui_story_5032_50320601_1_dialog_content = "O reinício de Windstone, agora começa.",
  ui_story_5032_50320601_2_dialog_content = "Reiniciando...",
  ui_story_5032_50320601_3_dialog_content = "Genes aurorianos apropriados detectados... Iniciando a extração de Lumina.",
  ui_story_5032_50320601_4_dialog_content = "Sim, este é o local. Siga o que está no livro... Tosse... E redirecione o fluxo de energia.",
  ui_story_5032_50320601_5_dialog_content = "Apenas... use o dispositivo no solo selado.",
  ui_story_5032_50320601_6_dialog_content = "Solicitação de redirecionamento detectada. Redirecionar a fonte de energia.",
  ui_story_5032_50320601_7_dialog_content = "Conectando...",
  ui_story_5032_50320601_8_dialog_content = "1%... 7%... 19%...",
  ui_story_5032_50320601_9_dialog_content = "Só esperamos o processo terminar agora?",
  ui_story_5032_50320601_10_dialog_content = "Isso mesmo.",
  ui_story_5032_50320601_11_dialog_content = "Se a reinicialização for bem-sucedida, o Windstone adotará a <color=#FFB400>energia absorvida</color> do núcleo como a nova fonte.",
  ui_story_5032_50320601_12_dialog_content = "Então, aqueles cronicamente perturbados por <color=#FFB400>Síndrome de Modali</color> será finalmente livre... *Tossindo*",
  ui_story_5032_50320601_13_dialog_content = "Sim... Isso deve melhorar sua condição também, certo?",
  ui_story_5032_50320601_14_dialog_content = "Haha, provavelmente.",
  ui_story_5032_50320601_15_dialog_content = "Não faço ideia do quanto estarei melhor, mas definitivamente melhor do que estou agora.",
  ui_story_5032_50320601_16_dialog_content = "Depois da confusão que causei, não posso mais liderar Harbour City.",
  ui_story_5032_50320601_17_dialog_content = "É verdade que sua ação violou seriamente suas obrigações como laird, mas foi basicamente para o bem do povo.",
  ui_story_5032_50320601_18_dialog_content = "Vou explicar ao Lorde da Cidade para que você tenha um julgamento justo.",
  ui_story_5032_50320601_19_dialog_content = "Heh, você é realmente diferente, Sua Alteza. Permita-me expressar minha gratidão novamente.",
  ui_story_5032_50320601_20_dialog_content = "Se não tens para onde ir, Elvis... podes considerar vir a bordo do Emerald.",
  ui_story_5032_50320601_21_dialog_content = "Oh? Mas eu não sou um artista de circo, Jeno.",
  ui_story_5032_50320601_22_dialog_content = "É legal. Você pode aprender.",
  ui_story_5032_50320601_23_dialog_content = "Só precisamos de um domador alternativo, de qualquer maneira.",
  ui_story_5032_50320601_24_dialog_content = "Isso significa que terei que trabalhar muito duro, então.",
  ui_story_5032_50320601_25_dialog_content = "(Elvis parece muito mais relaxado. Acho que eles fizeram as pazes.)",
  ui_story_5032_50320601_26_dialog_content = "<color=#e8d9bb>Zumbido!</color>",
  ui_story_5032_50320601_27_dialog_content = "Por que Windstone está fazendo tanto barulho?",
  ui_story_5032_50320601_28_dialog_content = "O que houve?",
  ui_story_5032_50320601_29_dialog_content = "Aviso. Erro de redirecionamento de energia.",
  ui_story_5032_50320601_30_dialog_content = "Código de erro 102. Energia incompatível com <color=#FFB400>Pedra do Vento</color>.",
  ui_story_5032_50320601_31_dialog_content = "Impossível! Minha pesquisa mostrou que a energia do núcleo energético é a mais compatível com a pedra!",
  ui_story_5032_50320601_32_dialog_content = "Não entre em pânico, Elvis!",
  ui_story_5032_50320601_33_dialog_content = "Verifique a pedra e veja se há algo que possamos fazer.",
  ui_story_5032_50320601_34_dialog_content = "Eu vou... O que é isso?!",
  ui_story_5032_50320601_35_dialog_content = "O que houve?",
  ui_story_5032_50320601_36_dialog_content = "A taxa de saída do núcleo de energia está flutuando... e ficando cada vez mais intensa!",
  ui_story_5032_50320601_37_dialog_content = "Isso só acontece quando a energia não é suficientemente pura!",
  ui_story_5032_50320601_38_dialog_content = "Aviso. Erro crítico no redirecionamento de energia.",
  ui_story_5032_50320601_39_dialog_content = "Código de erro 600. O influxo de energia excede <color=#FFB400>Pedra do Vento</color> capacidade.",
  ui_story_5032_50320601_40_dialog_content = "Interrompa a entrada de energia imediatamente para evitar repercussões graves.",
  ui_story_5032_50320601_41_dialog_content = "Desligue, Elvis, ou vai explodir!",
  ui_story_5032_50320601_42_dialog_content = "Estou tentando...",
  ui_story_5032_50320601_43_dialog_content = "Eca!!!",
  ui_story_5032_50320601_44_dialog_content = "Vício, proteger PlayerName!",
  ui_story_5032_50320601_45_dialog_content = "Fique atrás de nós, PlayerName!",
  ui_story_5032_50320601_46_dialog_content = "Elvis!",
  ui_story_5032_50320601_47_dialog_content = "Não chegue perto... A energia... está começando a vazar!",
  ui_story_5032_50320601_48_dialog_content = "Eu não posso pará-lo!",
  ui_story_5032_50320601_49_dialog_content = "Não importa o cetro, apenas largue-o!",
  ui_story_5032_50320601_50_dialog_content = "<color=#e8d9bb>BUM!</color>",
  ui_story_5032_50320601_51_dialog_content = "Uh!",
  ui_story_5032_50320601_52_dialog_content = "*Tosse*",
  ui_story_5032_50320601_53_dialog_content = "Você está bem, Jeno?!",
  ui_story_5032_50320601_54_dialog_content = "*Tosse*... Estou bem, ainda vivo.",
  ui_story_5032_50320601_55_dialog_content = "Se eu fosse mais lento, você estaria morto.",
  ui_story_5032_50320601_56_dialog_content = "O Windstone... está fora de controle...!",
  ui_story_5032_50320601_57_dialog_content = "A Pedra do Vento! O Windstone está bom?!",
  ui_story_5032_50320601_58_dialog_content = "Elvis!",
  ui_story_5032_50320601_59_dialog_content = "Aqui está... Felizmente, não está danificado, mas toda a sua energia foi perdida.",
  ui_story_5032_50320601_60_dialog_content = "Talvez ainda possa ser reiniciado!",
  ui_story_5032_50320601_61_dialog_content = "Reiniciado?",
  ui_story_5032_50320601_62_dialog_content = "Olha, Elvis, o terreno selado foi arruinado irreconhecível pela explosão.",
  ui_story_5032_50320601_63_dialog_content = "Os dispositivos antigos estão destruídos. Como vamos recomeçar?",
  ui_story_5032_50320601_64_dialog_content = "Eu... Dê-me mais tempo e eu darei um jeito!",
  ui_story_5032_50320601_65_dialog_content = "Ajuda ajuda! Eclipses!",
  ui_story_5032_50320601_66_dialog_content = "Eclipses?!",
  ui_story_5032_50320601_67_dialog_content = "O som parece vir da cidade.",
  ui_story_5032_50320601_68_dialog_content = "*Tosse*... Oh não, Eclipsites deve ter quebrado o selo porque o Windstone perdeu toda a energia!",
  ui_story_5032_50320601_69_dialog_content = "<color=#e8d9bb>Enquanto isso, em Harbour City</color>",
  ui_story_5032_50320601_70_dialog_content = "Por que tantos Eclipsitas estão saindo do oceano?!",
  ui_story_5032_50320601_71_dialog_content = "Rápido, vá para a costa! Monte defesas e evacue as pessoas!",
  ui_story_5032_50320601_72_dialog_content = "Sim, senhor!",
  ui_story_5032_50320601_73_dialog_content = "Eclipsitos aparecem ao longo da costa?",
  ui_story_5032_50320601_74_dialog_content = "E o som de uma explosão vindo do chão selado agora mesmo... Laird Elvis falhou?",
  ui_story_5032_50320601_75_dialog_content = "Tenho de proteger o laird. Com todos os soldados para lutar contra Eclipsites, agora é a hora.",
  ui_story_5032_50320601_76_dialog_content = "Sigam-me, todos!",
  ui_story_5032_50320601_77_dialog_content = "Sim!!!",
  ui_story_5032_50320601_78_dialog_content = "Laird Elvis!",
  ui_story_5032_50320601_79_dialog_content = "Patou? O que você está fazendo aqui?",
  ui_story_5032_50320601_80_dialog_content = "Arf, arf...",
  ui_story_5032_50320601_81_dialog_content = "Você com certeza não facilitou para mim encontrar, Elvis e Patou.",
  ui_story_5032_50320601_82_dialog_content = "Seu rosto está se contorcendo.",
  ui_story_5032_50320601_83_dialog_content = "Nem mesmo tentando esconder?",
  ui_story_5032_50320601_84_dialog_content = "Agora não é hora para o seu sarcasmo!",
  ui_story_5032_50320601_85_dialog_content = "Você não vê que é urgente agora? Não atrapalhe!",
  ui_story_5032_50320601_86_dialog_content = "Jeno está certo. Harbour City está em perigo.",
  ui_story_5032_50320601_87_dialog_content = "Espere... Por que está aqui, Alteza?",
  ui_story_5032_50320601_88_dialog_content = "Eu vou chegar a isso mais tarde. Temos questões muito mais importantes em mãos.",
  ui_story_5032_50320601_89_dialog_content = "*Tosse*... Como está Harbour City, Patou?",
  ui_story_5032_50320601_90_dialog_content = "Inúmeros eclipses estão saindo do mar, senhor. O Windstone é provavelmente ineficaz agora.",
  ui_story_5032_50320601_91_dialog_content = "Eu estava com medo daquilo...",
  ui_story_5032_50320601_92_dialog_content = "Vice, PlayerName, vamos voltar para a cidade.",
  ui_story_5032_50320601_93_dialog_content = "Há tantos cidadãos desarmados. Não podemos ficar de braços cruzados!",
  ui_story_5032_50320601_94_dialog_content = "Sim, entendi!",
  ui_story_5032_50320601_95_dialog_content = "Claro!",
  ui_story_5032_50320601_96_dialog_content = "Mas espere... E o fugitivo da prisão?",
  ui_story_5032_50320601_97_dialog_content = "Jeno, por favor... Vá com Sua Alteza.",
  ui_story_5032_50320601_98_dialog_content = "E por favor... proteja o povo de Harbour City.",
  ui_story_5032_50320601_99_dialog_content = "Não, eu vou ficar aqui com você.",
  ui_story_5032_50320601_100_dialog_content = "Você não percebe que está em suas últimas pernas?",
  ui_story_5032_50320601_101_dialog_content = "Não se preocupe, Jeno, ainda posso ir.",
  ui_story_5032_50320601_102_dialog_content = "*Tosse* Eu... tenho que voltar. Deve haver pistas sobre como reiniciar o Windstone nos arquivos.",
  ui_story_5032_50320601_103_dialog_content = "Se eu puder reiniciá-lo, os Eclipsites irão embora.",
  ui_story_5032_50320601_104_dialog_content = "É melhor você encontrar algo para se livrar dos Eclipsites.",
  ui_story_5032_50320601_105_dialog_content = "Não vou deixar um fugitivo se movimentar livremente. Loewe e eu estaremos de olho em você!",
  ui_story_5032_50320601_106_dialog_content = "Hehe, obrigado pelo pensamento.",
  ui_story_5032_50320601_107_dialog_content = "Elvis...",
  ui_story_5032_50320601_108_dialog_content = "Está tudo bem, Jeno. Ficarei bem com Patou e outros ao redor.",
  ui_story_5032_50320601_109_dialog_content = "Por favor, cuide das pessoas em Harbour City por mim.",
  ui_story_5032_50320601_110_dialog_content = "...",
  ui_story_5032_50320601_111_dialog_content = "Você com certeza sabe como me jogar as batatas quentes.",
  ui_story_5032_50320601_112_dialog_content = "Me desculpe... Eu compenso quando isso acabar.",
  ui_story_5032_50320601_113_dialog_content = "Desde que esteja ao meu alcance.",
  ui_story_5032_50320601_114_dialog_content = "Tudo bem, eu espero por você.",
  ui_story_5032_50320601_115_dialog_content = "Tá bom.",
  ui_story_5032_50320601_116_dialog_content = "Hum... Por que estamos recebendo tantos Eclipsites?",
  ui_story_5032_50320601_117_dialog_content = "Olhe para lá!",
  ui_story_5032_50320601_118_dialog_content = "Eles estão crescendo em número!",
  ui_story_5032_50320601_119_dialog_content = "Como isso é possível...",
  ui_story_5032_50320601_120_dialog_content = "O mar está cheio de Eclipses!",
  ui_story_5032_50320601_121_dialog_content = "Pare de pensar e comece a lutar!",
  ui_story_5032_50320601_122_dialog_content = "É possível lutar contra todos eles?",
  ui_story_5032_50320601_123_dialog_content = "Não temos escolha a não ser lutar.",
  ui_story_5032_50320601_124_dialog_content = "Devemos manter nossa posição e proteger o povo de Harbour City.",
  ui_story_5032_50320601_125_dialog_content = "Não vou recuar até que os civis sejam evacuados!",
  ui_story_5032_50320601_126_dialog_content = "... Elvis está certo. Você é diferente dos outros nobres.",
  ui_story_5032_50320601_127_dialog_content = "Deixa-me ajudar. Afinal, esta já foi nossa casa.",
  ui_story_5032_50320602_1_dialog_content = "Ui... Poh! Isso é salgado!",
  ui_story_5032_50320602_2_dialog_content = "Tenho que tomar cuidado não apenas com os Eclipsites, mas também com o mar revolto ...",
  ui_story_5032_50320602_3_dialog_content = "Eu me pergunto se Fia e outros ficarão bem no <color=#FFB400>Esmeralda</color>.",
  ui_story_5032_50320602_4_dialog_content = "Deve ficar tudo bem com Rainbow e Ciel lá, eu acho.",
  ui_story_5032_50320602_5_dialog_content = "Na verdade não... A Esmeralda é como uma ilha solitária com todos esses Eclipsitos na água.",
  ui_story_5032_50320602_6_dialog_content = "As pessoas em terra ainda podem recuar, mas a Esmeralda não tem para onde ir.",
  ui_story_5032_50320602_7_dialog_content = "Devemos ir ajudá-los!",
  ui_story_5032_50320602_8_dialog_content = "Mas e aqui...?",
  ui_story_5032_50320602_9_dialog_content = "Eu tenho esse. Com a ajuda de Jeno, vai ficar tudo bem!",
  ui_story_5032_50320602_10_dialog_content = "Vá ajudar a Fia!",
  ui_story_5032_50320602_11_dialog_content = "OK, entendi!",
  ui_story_5032_50320602_12_dialog_content = "Tem certeza que os dois podem lidar com isso?",
  ui_story_5032_50320602_13_dialog_content = "De uma vez só.",
  ui_story_5032_50320602_14_dialog_content = "Como amigo deles, sei como eles são durões, melhor do que ninguém.",
  ui_story_5032_50320602_15_dialog_content = "Confie em mim. Eles vão trazer sua tripulação para a segurança.",
  ui_story_5032_50320602_16_dialog_content = "Já que você colocou assim...",
  ui_story_5032_50320602_17_dialog_content = "Ahhh!!!",
  ui_story_5032_50320602_18_dialog_content = "Tsc...",
  ui_story_5032_50320602_19_dialog_content = "Por que existem tantos Eclipses? Tem sido interminável.",
  ui_story_5032_50320602_20_dialog_content = "Eles ficaram presos no fundo do mar por tanto tempo. Eles certamente correriam desenfreados agora que o selo estava quebrado.",
  ui_story_5032_50320602_21_dialog_content = "Você pode imaginar quanta energia o Windstone precisava para manter um selo tão poderoso.",
  ui_story_5032_50320602_22_dialog_content = "Agora não é hora para especulações. Temos uma luta em nossas mãos!",
  ui_story_5032_50320602_23_dialog_content = "Claro.",
  ui_story_5032_50320602_24_dialog_content = "Ah...",
  ui_story_5032_50320602_25_dialog_content = "Sua Alteza!",
  ui_story_5032_50320602_26_dialog_content = "Há muitos Eclipsitos, e o litoral é muito longo para que possamos estabelecer uma linha de defesa eficaz!",
  ui_story_5032_50320602_27_dialog_content = "Estamos em menor número, mas ainda podemos ter uma chance se concentrarmos nossas forças na cidade.",
  ui_story_5032_50320602_28_dialog_content = "Não posso fazer. Ainda não evacuamos todos!",
  ui_story_5032_50320602_29_dialog_content = "Bem, parece que não há escolha... Chame os guardas para proteger os portões e os civis. Abandonaremos o resto das áreas de defesa costeira em ordem!",
  ui_story_5032_50320602_30_dialog_content = "Independentemente disso, espere até que todas as pessoas sejam evacuadas.",
  ui_story_5032_50320602_31_dialog_content = "Como desejar!",
  ui_story_5032_50320701_1_dialog_content = "Graagh!",
  ui_story_5032_50320701_2_dialog_content = "Ahhh, eles com certeza quebraram essa janela também!",
  ui_story_5032_50320701_3_dialog_content = "Água e vidro quebrado estão por toda parte. Isso não pode ficar pior...",
  ui_story_5032_50320701_4_dialog_content = "Não posso me dar ao luxo de contratar faxineiros, nem posso limpar tudo sozinho!",
  ui_story_5032_50320701_5_dialog_content = "Grrr!",
  ui_story_5032_50320701_6_dialog_content = "A-Acalme-se, Rainbow. Eu te ajudo com a bagunça mais tarde.",
  ui_story_5032_50320701_7_dialog_content = "Há mais e mais Eclipsites, então vamos ter cuidado.",
  ui_story_5032_50320701_8_dialog_content = "Ciel, Fia, por favor, fechem a janela como fizeram antes.",
  ui_story_5032_50320701_9_dialog_content = "Eu vou me livrar desses vermes!",
  ui_story_5032_50320701_10_dialog_content = "Grrrr!",
  ui_story_5032_50320701_11_dialog_content = "R-Rainbow!",
  ui_story_5032_50320701_12_dialog_content = "... Ela entrou de cabeça na batalha, como de costume.",
  ui_story_5032_50320701_13_dialog_content = "Os eclipses são a única coisa em sua mente quando os vê.",
  ui_story_5032_50320701_14_dialog_content = "Rainbow vai ficar bem?",
  ui_story_5032_50320701_15_dialog_content = "Ela já derrotou muitos deles e está ferida.",
  ui_story_5032_50320701_16_dialog_content = "Mesmo que tudo isso seja auto-infligido em sua excitação...",
  ui_story_5032_50320701_17_dialog_content = "Estou meio preocupado também.",
  ui_story_5032_50320701_18_dialog_content = "Hmm, eu culpo por não operar o Styx corretamente antes.",
  ui_story_5032_50320701_19_dialog_content = "Ou eu não estaria de pé tão impotente...",
  ui_story_5032_50320701_20_dialog_content = "Eu também.",
  ui_story_5032_50320701_21_dialog_content = "Se ao menos eu não tivesse jogado Kyllo no mar.",
  ui_story_5032_50320701_22_dialog_content = "Com Kyllo por perto, esses Eclipsites seriam escolhas fáceis!",
  ui_story_5032_50320701_23_dialog_content = "Infelizmente. Pelo menos esta deve ser a última janela, e podemos bloquear os Eclipsites em breve.",
  ui_story_5032_50320701_24_dialog_content = "Tudo bem, estou embarcando deste lado para cima. Dá-me uma mão, Fia...",
  ui_story_5032_50320701_25_dialog_content = "Grrr!",
  ui_story_5032_50320701_26_dialog_content = "Eca! A-Outro Eclipse!",
  ui_story_5032_50320701_27_dialog_content = "Afaste-se, Fia!",
  ui_story_5032_50320701_28_dialog_content = "Gahh!",
  ui_story_5032_50320701_29_dialog_content = "<size=45>Aaaah!</size>",
  ui_story_5032_50320701_30_dialog_content = "Fia!",
  ui_story_5032_50320701_31_dialog_content = "Oh não, o Eclipsite está muito perto dela para eu usar o Aqua Blaster!",
  ui_story_5032_50320701_32_dialog_content = "Nesse caso...",
  ui_story_5032_50320701_33_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5032_50320701_34_dialog_content = "Grrr!",
  ui_story_5032_50320701_35_dialog_content = "Uh!",
  ui_story_5032_50320701_36_dialog_content = "Rainbow! Fia! Vocês estão bem?",
  ui_story_5032_50320701_37_dialog_content = "Hã...",
  ui_story_5032_50320701_38_dialog_content = "Estou bem. Minha cabeça só dói um pouco.",
  ui_story_5032_50320701_39_dialog_content = "Onde está o Rainbow? Acho que a vi vindo em minha direção.",
  ui_story_5032_50320701_40_dialog_content = "...",
  ui_story_5032_50320701_41_dialog_content = "Oh não, Rainbow desmaiou!",
  ui_story_5032_50320701_42_dialog_content = "Ela tem as costas sangrentas!",
  ui_story_5032_50320701_43_dialog_content = "Ela foi atingida pelo Eclipse?",
  ui_story_5032_50320701_44_dialog_content = "Ela... Ela se machucou tentando me salvar...",
  ui_story_5032_50320701_45_dialog_content = "C-Ce, não temos nada para parar o sangramento. O-o que fazer...",
  ui_story_5032_50320701_46_dialog_content = "eu não pude ajudar PlayerName e meus amigos quando lutaram contra o grande robô.",
  ui_story_5032_50320701_47_dialog_content = "Agora não posso ajudar Rainbow e Ciel, e até machuquei Rainbow...",
  ui_story_5032_50320701_48_dialog_content = "<anim type=Shake>Boo-hoo... eu... eu...</anim>",
  ui_story_5032_50320701_49_dialog_content = "Grrr!",
  ui_story_5032_50320701_50_dialog_content = "Não, agora não é hora de chorar!",
  ui_story_5032_50320701_51_dialog_content = "Eu devo proteger Rainbow!",
  ui_story_5032_50320701_52_dialog_content = "Fiquem longe, seus Eclipsitas estúpidos!",
  ui_story_5032_50320701_53_dialog_content = "<color=#e8d9bb>Bam, bam, bam!</color>",
  ui_story_5032_50320701_54_dialog_content = "Graagh!",
  ui_story_5032_50320701_55_dialog_content = "Uau! Funcionou!",
  ui_story_5032_50320701_56_dialog_content = "Eu sabia que não funcionou da última vez porque o robô era muito duro...",
  ui_story_5032_50320701_57_dialog_content = "Gah! Gah!",
  ui_story_5032_50320701_58_dialog_content = "Cuidado, Fia, lá vêm eles de novo!",
  ui_story_5032_50320701_59_dialog_content = "Ahhhh... Por que tantos Eclipses?!",
  ui_story_5032_50320701_60_dialog_content = "Eles estão migrando pelo mar ou algo assim de repente?",
  ui_story_5032_50320701_61_dialog_content = "Faltam três tiros, com um pente sobressalente...",
  ui_story_5032_50320701_62_dialog_content = "*soluços* Isso não é suficiente!",
  ui_story_5032_50320701_63_dialog_content = "Grrr!",
  ui_story_5032_50320701_64_dialog_content = "<color=#e8d9bb>Bam, bam, bam!</color>",
  ui_story_5032_50320701_65_dialog_content = "Se Kyllo estivesse aqui...",
  ui_story_5032_50320701_66_dialog_content = "Kyllo!",
  ui_story_5032_50320701_67_dialog_content = "Lo, lo, lo!",
  ui_story_5032_50320701_68_dialog_content = "Ahhh!",
  ui_story_5032_50320701_69_dialog_content = "Kyllo? V-você está aqui?!",
  ui_story_5032_50320701_70_dialog_content = "Que tipo de besta maravilhosa é essa?",
  ui_story_5032_50320701_71_dialog_content = "É meu amigo. Seu nome é Kylo!",
  ui_story_5032_50320701_72_dialog_content = "A-Incrível! Está dominando os Eclipsites.",
  ui_story_5032_50320701_73_dialog_content = "Hehe, claro!",
  ui_story_5032_50320701_74_dialog_content = "Kyllo é um exótico evoluído!",
  ui_story_5032_50320701_75_dialog_content = "Isso é um pedaço de bolo para ele!",
  ui_story_5032_50320701_76_dialog_content = "Grrr!",
  ui_story_5032_50320701_77_dialog_content = "Cuidado, Kylo. Eclipses estão vindo atrás de você!",
  ui_story_5032_50320701_78_dialog_content = "Ei, ei!",
  ui_story_5032_50320701_79_dialog_content = "O que? Você não pode se virar?",
  ui_story_5032_50320701_80_dialog_content = "É muito grande para manobrar no espaço apertado?",
  ui_story_5032_50320701_81_dialog_content = "Gah—",
  ui_story_5032_50320701_82_dialog_content = "Ah, eu tenho que recarregar!",
  ui_story_5032_50320701_83_dialog_content = "<color=#e8d9bb>Clam—</color>",
  ui_story_5032_50320701_84_dialog_content = "Ops, deixei cair todas as balas!",
  ui_story_5032_50320701_85_dialog_content = "Ah não, Kylo!",
  ui_story_5032_50320701_86_dialog_content = "Ei!",
  ui_story_5032_50320701_87_dialog_content = "Torrente Rápida!",
  ui_story_5032_50320701_88_dialog_content = "Grrr!",
  ui_story_5032_50320701_89_dialog_content = "Huh? E-Isso soa como...",
  ui_story_5032_50320701_90_dialog_content = "Estão todos bem?",
  ui_story_5032_50320701_91_dialog_content = "Desculpe, chegamos tarde. Muitos Eclipses no caminho.",
  ui_story_5032_50320701_92_dialog_content = "É vice e PlayerName!",
  ui_story_5032_50320701_93_dialog_content = "Humph, acho que somos apenas um pano de fundo para Fia.",
  ui_story_5032_50320701_94_dialog_content = "Sim, sim, eu me sinto muito triste!",
  ui_story_5032_50320701_95_dialog_content = "Os trigêmeos! Por que você saiu do convés?",
  ui_story_5032_50320701_96_dialog_content = "Encontramos o Caelestite e o Vice lá em cima!",
  ui_story_5032_50320701_97_dialog_content = "Eles disseram que é muito perigoso lá fora. Algum tipo de selo foi quebrado.",
  ui_story_5032_50320701_98_dialog_content = "E todos os Eclipsitas dormindo no fundo do mar acordaram!",
  ui_story_5032_50320701_99_dialog_content = "Então bloqueamos o acesso do convés e viemos contar...",
  ui_story_5032_50320701_100_dialog_content = "Eh? Espere, aquela Rainbow está deitada ali?",
  ui_story_5032_50320701_101_dialog_content = "Eu-É!",
  ui_story_5032_50320701_102_dialog_content = "O que aconteceu com ela?",
  ui_story_5032_50320701_103_dialog_content = "E-Ela me protegeu...",
  ui_story_5032_50320701_104_dialog_content = "Sinto muito.",
  ui_story_5032_50320701_105_dialog_content = "Gah! Gah!",
  ui_story_5032_50320701_106_dialog_content = "... Nós vamos pegar isso mais tarde.",
  ui_story_5032_50320701_107_dialog_content = "Tenho que eliminar esses Eclipses primeiro!",
  ui_story_5032_50320701_X107_dialog_content = "<color=#e8d9bb>Mais tarde...</color>",
  ui_story_5032_50320701_108_dialog_content = "S-Então eles realmente saíram do fundo do oceano?",
  ui_story_5032_50320701_109_dialog_content = "Sim. Testemunhamos Elvis falhando em sua tentativa e a onda de Eclipsites invadindo a costa.",
  ui_story_5032_50320701_110_dialog_content = "Isso não colocaria Harbour City em grande perigo?",
  ui_story_5032_50320701_111_dialog_content = "Carleen e Jeno estão liderando as forças que defendem a costa.",
  ui_story_5032_50320701_112_dialog_content = "E Elvis está tentando encontrar outra maneira de reiniciar o selo.",
  ui_story_5032_50320701_113_dialog_content = "A única coisa que podemos fazer é garantir que todos estejam seguros e ganhar tempo para Elvis.",
  ui_story_5032_50320701_114_dialog_content = "Obrigado por arriscarem suas vidas para vir aqui por nós.",
  ui_story_5032_50320701_115_dialog_content = "Fui muito imprudente e coloquei Ciel e Fia em perigo.",
  ui_story_5032_50320701_116_dialog_content = "Se não chegar a tempo...",
  ui_story_5032_50320701_117_dialog_content = "Está bem. Você faria o mesmo por nós se estivéssemos em sua posição.",
  ui_story_5032_50320701_118_dialog_content = "E Fia estaria em apuros se não fosse você.",
  ui_story_5032_50320701_119_dialog_content = "Obrigado, Rainbow.",
  ui_story_5032_50320701_120_dialog_content = "Eu deveria estar agradecendo a você e Kyllo por nos salvar!",
  ui_story_5032_50320701_121_dialog_content = "Ei!",
  ui_story_5032_50320701_122_dialog_content = "Oh, por que Kyllo está aqui?",
  ui_story_5032_50320701_123_dialog_content = "Você não deixou voltar para o mar, Fia?",
  ui_story_5032_50320701_124_dialog_content = "Lo, lo, lo.",
  ui_story_5032_50320701_125_dialog_content = "Hum, Kyllo diz que se espremeu pela janela que Eclipsites quebrou.",
  ui_story_5032_50320701_126_dialog_content = "Ele ficou nas águas próximas antes de de repente ter uma sensação estranha ao se aproximar da Esmeralda.",
  ui_story_5032_50320701_127_dialog_content = "Uma sensação estranha? O que é isso?",
  ui_story_5032_50320701_128_dialog_content = "Lo, lo.",
  ui_story_5032_50320701_129_dialog_content = "Você sentiu que eu estava em perigo e seguiu meu Lumina?",
  ui_story_5032_50320701_130_dialog_content = "Ei!",
  ui_story_5032_50320701_131_dialog_content = "Sentiu que Fia estava em perigo?",
  ui_story_5032_50320701_132_dialog_content = "Essa é uma habilidade especial para Kyllo?",
  ui_story_5032_50320701_133_dialog_content = "Provavelmente é porque Kyllo e Fia têm um vínculo profundo.",
  ui_story_5032_50320701_134_dialog_content = "Portanto, há uma ligação psíquica entre eles.",
  ui_story_5032_50320701_135_dialog_content = "Ei!",
  ui_story_5032_50320701_136_dialog_content = "Entendi.",
  ui_story_5032_50320701_137_dialog_content = "Já que você voltou, Kyllo, isso significa que você sabe onde está a Baleia Nuvem?",
  ui_story_5032_50320701_138_dialog_content = "Lo, lo...",
  ui_story_5032_50320701_139_dialog_content = "Uh... O que é isso?",
  ui_story_5032_50320701_140_dialog_content = "Você andou vagando porque não conseguiu encontrar nenhuma pista?",
  ui_story_5032_50320701_141_dialog_content = "Você não queria me ver porque eu gritaria com você... Ei, eu não sou tão má!",
  ui_story_5032_50320701_142_dialog_content = "Ei!",
  ui_story_5032_50320701_143_dialog_content = "Você parece muito má agora, Fia.",
  ui_story_5032_50320701_144_dialog_content = "Kyllo realmente gosta de você, então você deveria ser mais gentil com isso.",
  ui_story_5032_50320701_145_dialog_content = "Sim, e Kyllo mereceu seus sinceros agradecimentos por salvar todo mundo também.",
  ui_story_5032_50320701_146_dialog_content = "Ei, ei!",
  ui_story_5032_50320701_147_dialog_content = "WH-O que você está acenando para?",
  ui_story_5032_50320701_148_dialog_content = "Eu não fui legal com você?",
  ui_story_5032_50320701_149_dialog_content = "Ei...",
  ui_story_5032_50320701_150_dialog_content = "... Ok, ok, entendi. J-Apenas pare de chorar!",
  ui_story_5032_50320701_151_dialog_content = "Ei, ei!",
  ui_story_5032_50320701_152_dialog_content = "Y-Você quer agora? Sem pressa...",
  ui_story_5032_50320701_153_dialog_content = "Bem, ok, obrigado... Ahem.",
  ui_story_5032_50320701_154_dialog_content = "Lo?",
  ui_story_5032_50320701_155_dialog_content = "Obrigada!",
  ui_story_5032_50320701_156_dialog_content = "<size=45>Obrigado por nos salvar!</size>",
  ui_story_5032_50320701_157_dialog_content = "Ei!",
  ui_story_5032_50320701_158_dialog_content = "E... vou tentar não ser mais malvado com você, ok?",
  ui_story_5032_50320701_159_dialog_content = "Ei, ei!",
  ui_story_5032_50320701_160_dialog_content = "D-Não abuse da sorte!",
  ui_story_5032_50320701_161_dialog_content = "Lo, lo, lo!",
  ui_story_5032_50320701_162_dialog_content = "Ok, ok, entendi!",
  ui_story_5032_50320701_163_dialog_content = "Cinco sacos de biscoitos de animais, só para você!",
  ui_story_5032_50320701_164_dialog_content = "Ei!",
  ui_story_5032_50320701_165_dialog_content = "Por que isso parece um déjà vu?",
  ui_story_5032_50320701_166_dialog_content = "O que há com todas essas feras maravilhosas? Eles realmente sabem pechinchar.",
  ui_story_5032_50320701_167_dialog_content = "Oh, animal maravilhoso!",
  ui_story_5032_50320701_168_dialog_content = "Merylt, Firmet! Bica e outros continuam na sala!",
  ui_story_5032_50320701_169_dialog_content = "Oh não, os Eclipsites vão assustá-los!",
  ui_story_5032_50320701_170_dialog_content = "Não se levante ainda, Rainbow!",
  ui_story_5032_50320701_171_dialog_content = "Estou bem. Merylt usou um kit médico em mim. Eu me sinto melhor agora!",
  ui_story_5032_50320701_172_dialog_content = "Tenho que salvar os animais agora!",
  ui_story_5032_50320701_173_dialog_content = "Gah—",
  ui_story_5032_50320701_174_dialog_content = "... Eles com certeza escolheram o momento perfeito, não é?",
  ui_story_5032_50320701_175_dialog_content = "L-Deixe com a gente, Rainbow.",
  ui_story_5032_50320701_176_dialog_content = "Merylt, Subli, estão prontos?",
  ui_story_5032_50320701_177_dialog_content = "Sim! Vamos fazer isso!",
  ui_story_5032_50320702_1_dialog_content = "Acabou, Bica, você vai ficar bem.",
  ui_story_5032_50320702_2_dialog_content = "Eu eliminei todos aqueles caras maus!",
  ui_story_5032_50320702_3_dialog_content = "Oi oi...",
  ui_story_5032_50320702_4_dialog_content = "A pobrezinha ainda está tremendo.",
  ui_story_5032_50320702_5_dialog_content = "Por que sinto que o Eclipsite não é o que assusta a Bica...",
  ui_story_5032_50320702_6_dialog_content = "Tem um Glooey aqui, Rainbow!",
  ui_story_5032_50320702_7_dialog_content = "Glória!",
  ui_story_5032_50320702_8_dialog_content = "E mais dois aqui!",
  ui_story_5032_50320702_9_dialog_content = "Glória... Glória!",
  ui_story_5032_50320702_10_dialog_content = "Bom, os Glooeys estão bem também.",
  ui_story_5032_50320702_11_dialog_content = "Então isso só deixa...",
  ui_story_5032_50320702_12_dialog_content = "Eh? O que há de errado, Merylt?",
  ui_story_5032_50320702_13_dialog_content = "G-Geedo está desaparecido, Rainbow!",
  ui_story_5032_50320702_14_dialog_content = "Nossa?",
  ui_story_5032_50320702_15_dialog_content = "Ele era guardado em uma garrafa, então não podia se mover, certo?",
  ui_story_5032_50320702_16_dialog_content = "Sim... S-Então os Eclipsites devem ter...",
  ui_story_5032_50320702_17_dialog_content = "Não se preocupe. Ciel, Fia e eu procuraremos adiante.",
  ui_story_5032_50320702_18_dialog_content = "Você pode continuar procurando os outros animais que fugiram.",
  ui_story_5032_50320702_19_dialog_content = "O-Ok.",
  ui_story_5032_50320702_20_dialog_content = "Mantenha o ânimo, Merylt. Ainda temos muitos animais desaparecidos para encontrar!",
  ui_story_5032_50320702_21_dialog_content = "Miniphant, gato de três caudas, saltitante...",
  ui_story_5032_50320702_22_dialog_content = "Vamos dar uma olhada nesses quartos destruídos. Precisamos examinar cuidadosamente os armazéns!",
  ui_story_5032_50320702_23_dialog_content = "Gatos de três caudas gostam de se esconder em cantos escuros quando estão assustados.",
  ui_story_5032_50320702_24_dialog_content = "Entendido.",
  ui_story_5032_50320702_25_dialog_content = "A Esmeralda abrigava tantos animais maravilhosos, eu vejo.",
  ui_story_5032_50320702_26_dialog_content = "Não admira que Fia não quisesse ir embora.",
  ui_story_5032_50320702_27_dialog_content = "De fato... Oh, Merylt.",
  ui_story_5032_50320702_28_dialog_content = "Que tipo de animal maravilhoso é Geedo? Podemos ajudá-lo a encontrá-lo.",
  ui_story_5032_50320702_29_dialog_content = "Hum...",
  ui_story_5032_50320702_30_dialog_content = "É... ah...",
  ui_story_5032_50320702_31_dialog_content = "Uma criatura aquática parecida com um peixe que o Ringmaster Jeno trouxe de volta, mas não temos ideia de seu nome exato.",
  ui_story_5032_50320702_32_dialog_content = "Então, acabamos de chamá-lo de Geedo.",
  ui_story_5032_50320702_33_dialog_content = "<size=30>Uau, Merylt conseguiu terminar uma conversa completa com PlayerName!</size>",
  ui_story_5032_50320702_34_dialog_content = "<size=30>Isso é progresso!</size>",
  ui_story_5032_50320702_35_dialog_content = "<size=30>Provavelmente porque Merylt está realmente preocupada com Geedo.</size>",
  ui_story_5032_50320702_36_dialog_content = "<size=30>Vamos deixar Merylt e o Caelestite para a tarefa!</size>",
  ui_story_5032_50320702_37_dialog_content = "(... Por que Frimet e Subli estão sorrindo para mim?)",
  ui_story_5032_50320702_38_dialog_content = "Então devemos...",
  ui_story_5032_50320702_39_dialog_content = "Argh!",
  ui_story_5032_50320702_40_dialog_content = "Grrr!",
  ui_story_5032_50320702_41_dialog_content = "Rainbow!",
  ui_story_5032_50320702_42_dialog_content = "Rainbow!",
  ui_story_5032_50320702_43_dialog_content = "Está vindo de onde o Rainbow está!",
  ui_story_5032_50320702_44_dialog_content = "Ah, Merylt e suas irmãs estão indo nessa direção!",
  ui_story_5032_50320702_45_dialog_content = "Vamos também, PlayerName!",
  ui_story_5032_50320702_46_dialog_content = "Claro!",
  ui_story_5032_50320702_47_dialog_content = "Fia, Ciel, tudo bem?",
  ui_story_5032_50320702_48_dialog_content = "Fia, onde está Rainbow?",
  ui_story_5032_50320702_49_dialog_content = "Hum... Estou aqui.",
  ui_story_5032_50320702_50_dialog_content = "... Huh? Q-Que olho grande!",
  ui_story_5032_50320702_51_dialog_content = "O que é essa coisa?",
  ui_story_5032_50320702_52_dialog_content = "Bem, eu estou supondo que é Geedo.",
  ui_story_5032_50320702_53_dialog_content = "Eh? Nossa?",
  ui_story_5032_50320702_54_dialog_content = "Esse cara é muito maior. Como poderia ser Geedo?",
  ui_story_5032_50320702_55_dialog_content = "É assim... Eu vi um Eclipsite segurando uma garrafa e olhando para Geedo através dela nesta sala.",
  ui_story_5032_50320702_56_dialog_content = "Eu vim para bater nele, mas esse covarde apenas jogou e quebrou a garrafa por medo.",
  ui_story_5032_50320702_57_dialog_content = "Então um flash saiu de Geedo, e foi isso que eu vi quando pude ver novamente...",
  ui_story_5032_50320702_58_dialog_content = "H-como pode ser?",
  ui_story_5032_50320702_59_dialog_content = "Argh...",
  ui_story_5032_50320702_60_dialog_content = "Ei, pare de se mexer! Você está me lotando!",
  ui_story_5032_50320702_61_dialog_content = "...",
  ui_story_5032_50320702_62_dialog_content = "Huh? Parou! Este Eclipse entendeu o que Rainbow disse?",
  ui_story_5032_50320702_63_dialog_content = "E-Parece que está desmaiado?",
  ui_story_5032_50320702_64_dialog_content = "Hum, eu me pergunto por que este Eclipse parecia estar em agonia.",
  ui_story_5032_50320702_65_dialog_content = "Ele segurou a cabeça e gemeu, tornando o pequeno espaço ainda mais apertado.",
  ui_story_5032_50320702_66_dialog_content = "Mas estou um pouco amarrado no momento, também. Caso contrário, eu ficaria feliz em colocá-lo fora de sua miséria imediatamente.",
  ui_story_5032_50320702_67_dialog_content = "Er... Estou feliz por você estar segura, Rainbow.",
  ui_story_5032_50320702_68_dialog_content = "De qualquer forma, precisamos descobrir uma maneira de tirá-la daqui e rápido.",
  ui_story_5032_50320702_69_dialog_content = "Isso mesmo. As costas de Rainbow ainda estão feridas...",
  ui_story_5032_50320702_70_dialog_content = "*Solucionando* Por favor, se apresse! Está ficando cada vez mais apertado aqui!",
  ui_story_5032_50320702_71_dialog_content = "C-Você não pode tentar se comunicar com Geedo, Fia?",
  ui_story_5032_50320702_72_dialog_content = "Hã?",
  ui_story_5032_50320702_73_dialog_content = "Oh sim! Você pode dizer ao Geedo para parar de crescer, não pode Fia?",
  ui_story_5032_50320702_74_dialog_content = "Apresse-se, antes que Rainbow seja achatada em uma panqueca!",
  ui_story_5032_50320702_75_dialog_content = "Não, espere, há um Eclipse lá também... Então, talvez um sanduíche Rainbow-and-Eclipsite, em vez de uma panqueca?",
  ui_story_5032_50320702_76_dialog_content = "Argh... Isso não soa nada apetitoso.",
  ui_story_5032_50320702_77_dialog_content = "Ok, vou dar uma chance!",
  ui_story_5032_50320702_78_dialog_content = "Um... H-Olá, Geedo.",
  ui_story_5032_50320702_79_dialog_content = "Você poderia talvez, uh... Voltar ao seu tamanho original?",
  ui_story_5032_50320702_80_dialog_content = "Eep! Eep!",
  ui_story_5032_50320702_81_dialog_content = "N-Não?",
  ui_story_5032_50320702_82_dialog_content = "Mas por que?!",
  ui_story_5032_50320702_83_dialog_content = "Eep-eep-eep!",
  ui_story_5032_50320702_84_dialog_content = "Entendo... Então você quer se esticar um pouco porque manter constantemente sua forma menor é desconfortável?",
  ui_story_5032_50320702_85_dialog_content = "Mas você não sabe que se você não parar de crescer, você vai machucar a pessoa que te salvou?",
  ui_story_5032_50320702_86_dialog_content = "Eep?",
  ui_story_5032_50320702_87_dialog_content = "Isso mesmo! Rainbow aqui não pode mudar o tamanho do corpo dela como você pode!",
  ui_story_5032_50320702_88_dialog_content = "... Eep-eep.",
  ui_story_5032_50320702_89_dialog_content = "Ah! Então você está disposto a cooperar?",
  ui_story_5032_50320702_90_dialog_content = "Rapazes! Vá encontrar uma garrafa vazia e encha-a com um pouco de água!",
  ui_story_5032_50320702_91_dialog_content = "Mais ou menos como aquele usado para segurar Geedo antes!",
  ui_story_5032_50320702_92_dialog_content = "Sim!",
  ui_story_5032_50320702_93_dialog_content = "Ainda bem que não separamos e jogamos fora o lixo do festival, né?",
  ui_story_5032_50320702_94_dialog_content = "Isso é só porque você está relaxando, Subli! O mestre de cerimônias encarregou VOCÊ de cuidar do lixo três dias atrás!",
  ui_story_5032_50320702_95_dialog_content = "Heehe! Tudo funcionou no final!",
  ui_story_5032_50320702_96_dialog_content = "Isso serve, Fia?",
  ui_story_5032_50320702_97_dialog_content = "Eep! Eep!",
  ui_story_5032_50320702_98_dialog_content = "Geedo diz que sim! O que faremos a seguir?",
  ui_story_5032_50320702_99_dialog_content = "Eep.",
  ui_story_5032_50320702_100_dialog_content = "Apontar a garrafa para você?",
  ui_story_5032_50320702_101_dialog_content = "Assim?",
  ui_story_5032_50320702_102_dialog_content = "Eep!",
  ui_story_5032_50320702_103_dialog_content = "Ahh!",
  ui_story_5032_50320702_104_dialog_content = "Geedo realmente cabe na garrafa!",
  ui_story_5032_50320702_105_dialog_content = "Th-Isso é incrível!",
  ui_story_5032_50320702_106_dialog_content = "Ufa... estou salvo!",
  ui_story_5032_50320702_107_dialog_content = "Obrigado, Fia. Voce é meu herói!",
  ui_story_5032_50320702_108_dialog_content = "Graagh!",
  ui_story_5032_50320702_109_dialog_content = "Opa! Quase me esqueci de você...",
  ui_story_5032_50320702_110_dialog_content = "Graagh?",
  ui_story_5032_50320702_111_dialog_content = "Passamos por momentos difíceis juntos, meu amigo... Mas parece que é aqui que nossa amizade acaba.",
  ui_story_5032_50320702_112_dialog_content = "Agora morra!",
  ui_story_5032_50320702_113_dialog_content = "Graagh!",
  ui_story_5032_50320702_114_dialog_content = "Esse cara teve sua mordida de volta assim que Geedo voltou para a garrafa, hein?",
  ui_story_5032_50320702_115_dialog_content = "Espere... Agora que você mencionou...",
  ui_story_5032_50320702_116_dialog_content = "<size=45>Oh! PlayerName, todos, ouçam!</size>",
  ui_story_5032_50320702_117_dialog_content = "Ahhhh! D-Não comece a gritar assim! Estamos bem aqui!",
  ui_story_5032_50320702_118_dialog_content = "De repente me lembrei de algo que meu mestre disse sobre o Cloudwhale...",
  ui_story_5032_50320702_119_dialog_content = "\"Seu poder faz Eclipsites se encolher de medo, e que seu Lumina pode dissipar até mesmo o Darkflow mais espesso!\"",
  ui_story_5032_50320702_120_dialog_content = "Será que Geedo...",
  ui_story_5032_50320702_121_dialog_content = "É o Cloudwhale que estivemos procurando por todo esse tempo?",
  ui_story_5032_50320702_122_dialog_content = "É possível! O Lumina de Geedo tornou-se muito mais difícil de detectar depois que encolheu para seu tamanho atual.",
  ui_story_5032_50320702_123_dialog_content = "Esta pode ser a razão pela qual seu mestre perdeu o rastro do Cloudwhale e pensou que estava em perigo, Fia!",
  ui_story_5032_50320702_124_dialog_content = "Se Geedo realmente é o Cloudwhale...",
  ui_story_5032_50320702_125_dialog_content = "Então, de acordo com meu mestre, pode ser capaz de nos salvar!",
  ui_story_5032_50320702_126_dialog_content = "O poder de Geedo foi capaz de desacelerar os movimentos do Eclipsite mais cedo, tornando-o um alvo fácil!",
  ui_story_5032_50320702_127_dialog_content = "Isso significa que pode ser capaz de fazer o mesmo com outros Eclipsites!",
  ui_story_5032_50320702_128_dialog_content = "Se pudermos levar Geedo para algum lugar grande o suficiente para ele voltar ao seu tamanho normal... Seu poder pode suprimir os Eclipsites em uma área ainda maior!",
  ui_story_5032_50320702_129_dialog_content = "Geedo veio do oceano, certo? E se levarmos de volta para lá?",
  ui_story_5032_50320702_130_dialog_content = "Você tem razão, PlayerName! Ver? Até você pode ter boas ideias de vez em quando!",
  ui_story_5032_50320702_131_dialog_content = "Mas já selamos todas as janelas aqui embaixo...",
  ui_story_5032_50320702_132_dialog_content = "Para reabri-los, teremos que esperar até que os sistemas de motor do Emerald sejam reparados.",
  ui_story_5032_50320702_133_dialog_content = "E de acordo com Subli, o baralho ainda está cheio de Eclipsites. Forçar nosso caminho através deles seria extremamente perigoso.",
  ui_story_5032_50320702_134_dialog_content = "Você pode pedir confirmação ao Geedo, Fia? Precisamos saber se é realmente o Cloudwhale e tem esse tipo de poder.",
  ui_story_5032_50320702_135_dialog_content = "Eu... eu não tenho como confirmar isso. Desculpe...",
  ui_story_5032_50320702_136_dialog_content = "M-Mas minha intuição me diz que Geedo é realmente o Cloudwhale!",
  ui_story_5032_50320702_137_dialog_content = "É por isso... É por isso que acho que ainda devemos tentar!",
  ui_story_5032_50320702_138_dialog_content = "Hum... O que você acha, PlayerName?",
  ui_story_5032_50320702_139_dialog_content = "Eu...",
  ui_story_5032_50320702_140_dialog_content = "Concordo. Vamos tentar.",
  ui_story_5032_50320702_141_dialog_content = "Mesmo que Fia possa ser imatura... E teimosa... E até pouco confiável às vezes...",
  ui_story_5032_50320702_142_dialog_content = "E-Ei! Esta é a sua maneira de se vingar de mim, PlayerName?!",
  ui_story_5032_50320702_143_dialog_content = "Apesar de tudo isso, Fia e eu passamos por muitas situações perigosas juntas, e tenho total confiança em sua habilidade e experiência como extrozoóloga.",
  ui_story_5032_50320702_144_dialog_content = "É por isso que estou disposto a confiar na intuição dela desta vez.",
  ui_story_5032_50320702_145_dialog_content = "Ir para o convés seria uma sentença de morte... Mas se Geedo é realmente a Baleia Nuvem, então podemos virar a maré a nosso favor!",
  ui_story_5032_50320702_146_dialog_content = "PlayerName...",
  ui_story_5032_50320702_147_dialog_content = "Nós iremos,PlayerName, se você confia no julgamento de Fia, então eu também.",
  ui_story_5032_50320702_148_dialog_content = "Eu vou até o convés com vocês dois.",
  ui_story_5032_50320702_149_dialog_content = "Vice!",
  ui_story_5032_50320702_150_dialog_content = "Vocês fazem alguns argumentos convincentes, sabe?",
  ui_story_5032_50320702_151_dialog_content = "Em vez de colocar todas as nossas esperanças nos outros... É melhor entrarmos no jogo e aumentar as chances de sucesso de todos!",
  ui_story_5032_50320702_152_dialog_content = "Além disso, ficar sentado aqui não vai impedir que a Esmeralda seja destruída tão cedo.",
  ui_story_5032_50320702_153_dialog_content = "Rainbow... Obrigado! Obrigado a todos por acreditarem em mim!",
  ui_story_5032_50320702_154_dialog_content = "Haha, não é preciso muito para você se emocionar, não é Fia?",
  ui_story_5032_50320702_155_dialog_content = "Tudo bem, isso é o suficiente... Vamos começar a planejar nosso próximo passo!",
  ui_story_5032_50320702_156_dialog_content = "Tenho certeza que haverá mais Eclipses no convés do que podemos imaginar...",
  ui_story_5032_50320801_1_dialog_content = "Princesa Carlão! Um Eclipsite de alto nível apareceu perto de nossa terceira posição defensiva do lado esquerdo! Eles estão pedindo reforços!",
  ui_story_5032_50320801_2_dialog_content = "Envie o quinto esquadrão de guerrilheiros para ajudá-los.",
  ui_story_5032_50320801_3_dialog_content = "Os Eclipsites parecem estar diminuindo em número a partir da sétima posição defensiva do lado esquerdo e além.",
  ui_story_5032_50320801_4_dialog_content = "Diga-lhes que enviem batedores para avaliar a situação e atribua quaisquer reforços que possam dispensar aos pontos defensivos centrais.",
  ui_story_5032_50320801_5_dialog_content = "Entendido!",
  ui_story_5032_50320801_6_dialog_content = "Como está sendo a evacuação da cidade?",
  ui_story_5032_50320801_7_dialog_content = "O primeiro grupo de civis foi escoltado com segurança para o abrigo, Princesa Carleen.",
  ui_story_5032_50320801_8_dialog_content = "Ainda estamos no processo de evacuar o resto das pessoas.",
  ui_story_5032_50320801_9_dialog_content = "Também inspecionamos o abrigo e tudo parece estar em ordem.",
  ui_story_5032_50320801_10_dialog_content = "OK. Eu vejo.",
  ui_story_5032_50320801_11_dialog_content = "Continue segurando a linha! Acabamos de receber comunicações de Lumopolis dizendo que os reforços chegarão em breve!",
  ui_story_5032_50320801_12_dialog_content = "Entendido!",
  ui_story_5032_50320801_13_dialog_content = "Devo dizer que estou honestamente surpreso com a facilidade com que a evacuação está ocorrendo. O primeiro grupo de refugiados chegou ao abrigo em tão pouco tempo...",
  ui_story_5032_50320801_14_dialog_content = "Nesse ritmo, o número de baixas deve ser muito menor do que eu previa.",
  ui_story_5032_50320801_15_dialog_content = "De fato. E temos que agradecer a Laird Elvis por isso.",
  ui_story_5032_50320801_16_dialog_content = "O laird realiza exercícios regulares de evacuação, para que as pessoas saibam exatamente como reagir durante uma emergência.",
  ui_story_5032_50320801_17_dialog_content = "Nunca pensei que veria o dia em que as brocas fossem finalmente colocadas em uso.",
  ui_story_5032_50320801_18_dialog_content = "Exercícios de evacuação?",
  ui_story_5032_50320801_19_dialog_content = "Sim sua Majestade. Laird Elvis se prepara para o perigo mesmo em tempos de paz e presta atenção especial à manutenção desses sistemas e instalações.",
  ui_story_5032_50320801_20_dialog_content = "Mesmo que os abrigos não sejam usados há anos, fazemos manutenção neles pelo menos uma vez por ano com as instruções de Laird Elvis.",
  ui_story_5032_50320801_21_dialog_content = "<size=30>Isso também faz parte do seu plano, Elvis?</size>",
  ui_story_5032_50320801_22_dialog_content = "Eu imploro seu perdão, seu...",
  ui_story_5032_50320801_23_dialog_content = "L-Cuidado, Princesa Carleen! Um Eclipsite está cobrando bem em você!",
  ui_story_5032_50320801_24_dialog_content = "Aaarrgh!",
  ui_story_5032_50320801_25_dialog_content = "Ahhhh!",
  ui_story_5032_50320801_26_dialog_content = "Todos fiquem tranquilos! Não entrar em pânico!",
  ui_story_5032_50320801_27_dialog_content = "M... Minhas desculpas, Alteza!",
  ui_story_5032_50320801_28_dialog_content = "Você foi colocado em perigo porque não conseguimos detê-lo...",
  ui_story_5032_50320801_29_dialog_content = "Estou bem. Agora volte para suas postagens.",
  ui_story_5032_50320801_30_dialog_content = "Não permita que formalidades como essa o distraiam no campo de batalha.",
  ui_story_5032_50320801_31_dialog_content = "Entendido!",
  ui_story_5032_50320801_32_dialog_content = "Ah! H-Socorro! Reforços!",
  ui_story_5032_50320801_33_dialog_content = "Alguns Eclipsitas romperam nossa linha defensiva e estão entrando na cidade!",
  ui_story_5032_50320801_34_dialog_content = "Aaargh!",
  ui_story_5032_50320801_35_dialog_content = "Isso é ruim. Não temos soldados de sobra...",
  ui_story_5032_50320801_36_dialog_content = "Vem comigo!",
  ui_story_5032_50320801_37_dialog_content = "S-Sim, Alteza!",
  ui_story_5032_50320801_38_dialog_content = "Gelescer!",
  ui_story_5032_50320801_39_dialog_content = "Graagh!",
  ui_story_5032_50320801_40_dialog_content = "*Tosse*...",
  ui_story_5032_50320801_41_dialog_content = "Princesa Carlão! Você se machucou?!",
  ui_story_5032_50320801_42_dialog_content = "Não, eu estou bem. É só que... O Darkflow no ar ficou tão denso que até meus sentidos estão começando a ser afetados.",
  ui_story_5032_50320801_43_dialog_content = "Dado o estado de nossas forças, uma batalha prolongada é altamente desfavorável.",
  ui_story_5032_50320801_44_dialog_content = "Graagh!",
  ui_story_5032_50320801_45_dialog_content = "Mais Eclipses surgiram!",
  ui_story_5032_50320801_46_dialog_content = "Nossas tropas da linha de frente estão começando a diminuir, também...",
  ui_story_5032_50320801_47_dialog_content = "D-Não desista! Ainda há civis atrás de nós!",
  ui_story_5032_50320801_48_dialog_content = "W-Nós não podemos permitir que eles ultrapassem esta linha defensiva!",
  ui_story_5032_50320801_49_dialog_content = "Sim!",
  ui_story_5032_50320801_50_dialog_content = "Aaarrgh!",
  ui_story_5032_50320801_51_dialog_content = "O-o que é isso?!",
  ui_story_5032_50320801_52_dialog_content = "Um Eclipse de alto nível! Outro Eclipsite de alto nível apareceu!",
  ui_story_5032_50320801_53_dialog_content = "Não quebre a formação, pessoal! Focar em-!",
  ui_story_5032_50320801_54_dialog_content = "Argh!",
  ui_story_5032_50320801_55_dialog_content = "C-Capitão!",
  ui_story_5032_50320801_56_dialog_content = "Este Eclipse...",
  ui_story_5032_50320801_57_dialog_content = "Sem uso. Soldados normais não têm chance contra isso.",
  ui_story_5032_50320801_58_dialog_content = "Afaste-se por enquanto e vá lidar com os outros Eclipsites! Não deixe um único entrar na cidade até que a evacuação esteja completa!",
  ui_story_5032_50320801_59_dialog_content = "Deixe este Eclipse para mim!",
  ui_story_5032_50320801_60_dialog_content = "Senhora Carlen!",
  ui_story_5032_50320801_61_dialog_content = "Aahhhhhh!",
  ui_story_5032_50320802_1_dialog_content = "Argh!",
  ui_story_5032_50320802_2_dialog_content = "Meu corpo ainda não se recuperou totalmente. Minha força não aguenta...",
  ui_story_5032_50320802_3_dialog_content = "Sem mencionar que o Darkflow é tão denso que até meu corpo parece pesado.",
  ui_story_5032_50320802_4_dialog_content = "Aaarrgh!",
  ui_story_5032_50320802_5_dialog_content = "Mesmo que eu não consiga impedir que o Darkflow invada a cidade... não posso permitir que este Eclipsite passe por aqui!",
  ui_story_5032_50320802_6_dialog_content = "Eu não tenho escolha. Eu sei que prometi ao Vice...",
  ui_story_5032_50320802_7_dialog_content = "Você deveria ter calma por um tempo, Carleen. Não apresse sua recuperação.",
  ui_story_5032_50320802_8_dialog_content = "Desmaiar da drenagem do seu Lumina pode acontecer se você ainda não estiver aclimatado.",
  ui_story_5032_50320802_9_dialog_content = "Então não se force com seus novos poderes até que você se recupere, ok?",
  ui_story_5032_50320802_10_dialog_content = "Isso soa como algo Carleen faria.",
  ui_story_5032_50320802_11_dialog_content = "Ok, entendi.",
  ui_story_5032_50320802_12_dialog_content = "Eu vou cuidar de mim. Tenha certeza.",
  ui_story_5032_50320802_13_dialog_content = "Eu sinto Muito, Vice.",
  ui_story_5032_50320802_14_dialog_content = "Mas se eu recuar agora, mais pessoas só vão se machucar.",
  ui_story_5032_50320802_15_dialog_content = "*Inspira* Concentre-se e respire fundo...",
  ui_story_5032_50320802_16_dialog_content = "Aaarrgh!",
  ui_story_5032_50320802_17_dialog_content = "Brilho Esplêndido!",
  ui_story_5032_50320802_18_dialog_content = "Aahhhhhh!",
  ui_story_5032_50320802_19_dialog_content = "Funcionou!",
  ui_story_5032_50320802_20_dialog_content = "Argh!",
  ui_story_5032_50320802_21_dialog_content = "Eu deveria saber que meu novo poder não seria tão fácil de controlar...",
  ui_story_5032_50320802_22_dialog_content = "Ainda é difícil para mim forçá-lo?",
  ui_story_5032_50320802_23_dialog_content = "Aaarrgh!",
  ui_story_5032_50320802_24_dialog_content = "Não pode esquivar completamente este!",
  ui_story_5032_50320802_25_dialog_content = "Mas ainda posso lutar com apenas uma perna machucada!",
  ui_story_5032_50320802_26_dialog_content = "<color=#e8d9bb>Clam...</color>",
  ui_story_5032_50320802_27_dialog_content = "Ufa... Ainda bem que cheguei a tempo, senão teria que explicar tudo isso para Schwartz e o resto daqueles nobres. Isso não seria divertido, nada...",
  ui_story_5032_50320802_28_dialog_content = "Perdoe-me, princesa Carleen! Que estilo de luta é esse?",
  ui_story_5032_50320802_29_dialog_content = "Você não está preocupado conosco? Estaríamos em apuros se algo acontecesse com você, você sabe!",
  ui_story_5032_50320802_30_dialog_content = "Hã?",
  ui_story_5032_50320802_31_dialog_content = "E-é você!",
  ui_story_5032_50320802_32_dialog_content = "Que tipo de resposta é essa?",
  ui_story_5032_50320802_33_dialog_content = "Acabei de salvar sua vida! Você pode fazer melhor do que isso!",
  ui_story_5032_50320802_34_dialog_content = "Vamos, pelo menos um \"obrigado\" seria bom.",
  ui_story_5032_50320802_35_dialog_content = "... Agradeço.",
  ui_story_5032_50320802_36_dialog_content = "Está magoada, Princesa Carleen?",
  ui_story_5032_50320802_37_dialog_content = "Estou perfeitamente bem, Sr. Loewe.",
  ui_story_5032_50320802_38_dialog_content = "Embora, se vocês dois conseguiram chegar a este lugar, isso significa...",
  ui_story_5032_50320802_39_dialog_content = "Correto, Princesa Carleen. Encontrei uma maneira de reativar o Windstone.",
  ui_story_5032_50320802_40_dialog_content = "Em nome de toda a cidade de Harbour e seu povo, permita-me estender minha mais sincera gratidão.",
  ui_story_5032_50320802_41_dialog_content = "Obrigado por defender nossos soldados, nosso povo e nossa casa.",
  ui_story_5032_50320802_42_dialog_content = "Não há necessidade de tais formalidades. Eu estava apenas cumprindo minhas obrigações.",
  ui_story_5032_50320802_43_dialog_content = "Você arriscou desinteressadamente sua vida pelo bem de Harbour City e seus cidadãos.",
  ui_story_5032_50320802_44_dialog_content = "Quando penso na minha desconfiança anterior em você, isso me enche de uma profunda sensação de vergonha.",
  ui_story_5032_50320802_45_dialog_content = "No mínimo, por favor, aceite minha mais sincera gratidão.",
  ui_story_5032_50320802_46_dialog_content = "Oi, Loewe! Pare de ficar parado já!",
  ui_story_5032_50320802_47_dialog_content = "Por que eu sou o único fazendo todo o trabalho agora?",
  ui_story_5032_50320802_48_dialog_content = "Venha aqui e me ajude a limpar o resto desses Eclipsitos imundos!",
  ui_story_5032_50320802_49_dialog_content = "Eu não era o único designado para proteger a princesinha, você sabe!",
  ui_story_5032_50320802_50_dialog_content = "...",
  ui_story_5032_50320802_51_dialog_content = "... Você não precisa gritar.",
  ui_story_5032_50320802_52_dialog_content = "Laird Elvis, a situação piorou muito além das minhas expectativas.",
  ui_story_5032_50320802_53_dialog_content = "Mandei uma mensagem para Lumopolis, mas não tenho ideia de quando os reforços chegarão.",
  ui_story_5032_50320802_54_dialog_content = "O Darkflow no ar também ficou incrivelmente denso. Nesse ritmo, a vida de todos estará em perigo.",
  ui_story_5032_50320802_55_dialog_content = "Apesar das dezenas de Eclipsites que derrotamos, o Darkflow ainda paira pesadamente no ar sobre Harbour City...",
  ui_story_5032_50320802_56_dialog_content = "Não temos muito tempo. Deixo a Windstone e o selo para você, Elvis.",
  ui_story_5032_50320802_57_dialog_content = "Eu entendo, Princesa Carleen. Você tomou as decisões certas.",
  ui_story_5032_50320802_58_dialog_content = "Mas fique tranquilo, agora que encontrei uma maneira de ativar a Pedra do Vento... Tudo acabará em breve.",
  ui_story_5032_50320802_59_dialog_content = "O que exatamente é esse método de que você fala? Há algo que eu possa fazer para ajudar?",
  ui_story_5032_50320802_60_dialog_content = "Deixe o resto comigo, Alteza.",
  ui_story_5032_50320802_61_dialog_content = "Tudo o que peço é que continue comandando nossas defesas por um bom tempo.",
  ui_story_5032_50320802_62_dialog_content = "Eu entendo. Continuarei liderando os soldados daqui e lhe darei o tempo que precisar.",
  ui_story_5032_50320802_63_dialog_content = "Agradeço sua confiança e tudo o que fez por Harbour City, Sua Alteza.",
  ui_story_5032_50320802_64_dialog_content = "Há mais uma coisa, embora possa parecer injusto, dadas as circunstâncias... Eu humildemente peço que você se lembre do seu juramento de antes.",
  ui_story_5032_50320802_65_dialog_content = "Que você manterá o meu segredo e o de Harbour City em segurança, assim que os reforços de Lumopolis chegarem.",
  ui_story_5032_50320802_66_dialog_content = "Eu lhe dei minha palavra de que manterei qualquer informação sobre a Pedra do Vento em segredo, e não tenho intenção de quebrar essa promessa.",
  ui_story_5032_50320802_67_dialog_content = "Obrigado, Alteza. Com seu caráter nobre e confiável, estou totalmente confiante de que você será um governante excepcional algum dia.",
  ui_story_5032_50320802_68_dialog_content = "Agora, posso perguntar se você sabe onde Jeno está agora?",
  ui_story_5032_50320802_69_dialog_content = "Jeno? Ele deve estar na quinta posição defensiva logo à frente.",
  ui_story_5032_50320802_70_dialog_content = "Você precisa dele para alguma coisa?",
  ui_story_5032_50320802_71_dialog_content = "De fato. Você poderia enviar tropas adicionais para fortalecer sua posição atual? Temo que precise tirá-lo da linha de frente por algum tempo.",
  ui_story_5032_50320802_72_dialog_content = "Entendi.",
  ui_story_5032_50320802_73_dialog_content = "Bem, por favor, permita-me estender minha mais sincera gratidão novamente.",
  ui_story_5032_50320802_74_dialog_content = "Além disso, gostaria de pedir desculpas por quaisquer ferimentos ou baixas que você e seus aliados possam ter sofrido.",
  ui_story_5032_50320802_75_dialog_content = "Ter conhecido você foi uma das maiores honras da minha vida, princesa Carleen. Você será conhecido para sempre como um querido amigo de Harbour City.",
  ui_story_5032_50320802_76_dialog_content = "<size=30>E agora, posso finalmente começar... a reparar os erros que cometi.</size>",
  ui_story_5032_50320802_77_dialog_content = "Por favor, dê-me licença.",
  ui_story_5032_50320802_78_dialog_content = "... Elvis.",
  ui_story_5032_50320802_79_dialog_content = "Hum? Há algo mais em sua mente, Sua Alteza?",
  ui_story_5032_50320802_80_dialog_content = "... Não, nada.",
  ui_story_5032_50320802_81_dialog_content = "Por favor, seja cuidadoso.",
  ui_story_5032_50320802_82_dialog_content = "Sua preocupação é muito apreciada, Princesa Carleen.",
  ui_story_5032_50320802_83_dialog_content = "Eu vou continuar vigilante.",
  ui_story_5032_50320901_1_dialog_content = "Tudo bem, vamos rever o plano uma última vez!",
  ui_story_5032_50320901_2_dialog_content = "Em alguns minutos, Subli destrancará a porta do convés. Quando ela o fizer, o \"Geedo Squad\" irá atacar.",
  ui_story_5032_50320901_3_dialog_content = "PlayerName e Fia estará no nosso centro, e será responsável por comandar e proteger Geedo.",
  ui_story_5032_50320901_4_dialog_content = "Kyllo, Vice, Merylt e eu vamos cercá-los e afastar qualquer atacante.",
  ui_story_5032_50320901_5_dialog_content = "Enquanto isso, Ciel, Frimet e Subli ficarão embaixo do convés para trancar a porta atrás de nós e continuar procurando outros animais.",
  ui_story_5032_50320901_6_dialog_content = "Alguma pergunta?",
  ui_story_5032_50320901_7_dialog_content = "Não!",
  ui_story_5032_50320901_8_dialog_content = "N-Sem perguntas aqui.",
  ui_story_5032_50320901_9_dialog_content = "*Gole*",
  ui_story_5032_50320901_10_dialog_content = "Que som familiar... Você está se sentindo nervosa, Fia?",
  ui_story_5032_50320901_11_dialog_content = "NNN-De jeito nenhum!!",
  ui_story_5032_50320901_12_dialog_content = "E-isso era Kyllo engolindo agora, n-eu não!",
  ui_story_5032_50320901_13_dialog_content = "Lo?",
  ui_story_5032_50320901_14_dialog_content = "Vai ficar tudo bem, Fia! Apenas finja que é como aquele jogo de carnaval e você ficará bem!",
  ui_story_5032_50320901_15_dialog_content = "Afinal, são apenas alguns Eclipsites. Nada para se preocupar para pessoas como nós!",
  ui_story_5032_50320901_16_dialog_content = "Ei, ei!",
  ui_story_5032_50320901_17_dialog_content = "É... Certo!",
  ui_story_5032_50320901_18_dialog_content = "<size=30>Exceto que Carleen e Vice foram os únicos que fizeram todas as lutas durante a competição...</size>",
  ui_story_5032_50320901_19_dialog_content = "Será que... eu realmente vou ficar bem? Estou tão nervoso...",
  ui_story_5032_50320901_20_dialog_content = "E agora, sem mais delongas... Que comece a próxima rodada do jogo!",
  ui_story_5032_50320901_21_dialog_content = "Abra a porta, Subli!",
  ui_story_5032_50320901_22_dialog_content = "Sim!",
  ui_story_5032_50320902_1_dialog_content = "Podemos realmente derrotar todos esses Eclipsites?",
  ui_story_5032_50320902_2_dialog_content = "Parece que mais e mais deles estão aparecendo na praia!",
  ui_story_5032_50320902_3_dialog_content = "Aaarrgh!",
  ui_story_5032_50320902_4_dialog_content = "Argh! Th-Há mais vindo para nós do nosso flanco!",
  ui_story_5032_50320902_5_dialog_content = "Acabou para nós, não é...?",
  ui_story_5032_50320902_6_dialog_content = "É assim que Harbour City vai cair? Eu ainda não disse a ela meu carinho...",
  ui_story_5032_50320902_7_dialog_content = "Se você tem força suficiente para lamentar e gemer assim, então você ainda deve ter alguma luta em você.",
  ui_story_5032_50320902_8_dialog_content = "Huh? Q-Quem é você?!",
  ui_story_5032_50320902_9_dialog_content = "Vá embora, criaturas vis das profundezas.",
  ui_story_5032_50320902_10_dialog_content = "Deixe a Verdade guiá-lo para sua morte predestinada!",
  ui_story_5032_50320902_11_dialog_content = "Aahhhhhh!",
  ui_story_5032_50320902_12_dialog_content = "Ei! É o apresentador do circo!",
  ui_story_5032_50320902_13_dialog_content = "É o Jeno! Ele é um dos amigos íntimos de Laird Elvis!",
  ui_story_5032_50320902_14_dialog_content = "Eu o vi lutando em uma de nossas posições defensivas mais cedo. Ele veio nos ajudar depois de ver quão poucos de nós restam?",
  ui_story_5032_50320902_15_dialog_content = "Estamos salvos!",
  ui_story_5032_50320902_16_dialog_content = "Uau, o ringmaster é insanamente forte! Ele rasgou todos aqueles Eclipsites em um piscar de olhos!",
  ui_story_5032_50320902_17_dialog_content = "Hmph... Patético.",
  ui_story_5032_50320902_18_dialog_content = "Deixando Eclipsites fracos como este assustá-lo a se render, você deveria ter vergonha de se chamar de guardas da cidade do porto.",
  ui_story_5032_50320902_19_dialog_content = "Não se esqueça de todos os rostos sorridentes dos habitantes da cidade que estão contando com você para protegê-los.",
  ui_story_5032_50320902_20_dialog_content = "Seus pais, seus filhos, seus amigos e familiares... Todos eles estão em perigo.",
  ui_story_5032_50320902_21_dialog_content = "Encontre sua coragem e se recomponha. Nunca mostre esse tipo de fraqueza na frente do inimigo.",
  ui_story_5032_50320902_22_dialog_content = "As palavras podem ser tão devastadoras quanto as armas e podem mudar o curso do seu destino, assim como o de seus companheiros de armas. Agora cale a boca e concentre-se na luta!",
  ui_story_5032_50320902_23_dialog_content = "Entendido!",
  ui_story_5032_50320902_24_dialog_content = "Para o próximo...",
  ui_story_5032_50320902_25_dialog_content = "Sr. Jeno!",
  ui_story_5032_50320902_26_dialog_content = "Hum? É você...",
  ui_story_5032_50320902_27_dialog_content = "Finalmente encontrei você, Sr. Jeno!",
  ui_story_5032_50320902_28_dialog_content = "O que você está fazendo aqui? Onde está Elvis?",
  ui_story_5032_50320902_29_dialog_content = "Estou aqui também, Jeno.",
  ui_story_5032_50320902_30_dialog_content = "Elvis! Você está bem?",
  ui_story_5032_50320902_31_dialog_content = "É muito perigoso aqui. Você precisa retornar ao posto de comando e encontrar Carleen.",
  ui_story_5032_50320902_32_dialog_content = "Ela está no comando por lá, então deve ser mais seguro ao lado dela...",
  ui_story_5032_50320902_33_dialog_content = "Eu estava no posto de comando perguntando a Sua Alteza sobre seu paradeiro Jeno. É por isso que vim te procurar.",
  ui_story_5032_50320902_34_dialog_content = "Procurando por mim? Por quê?",
  ui_story_5032_50320902_35_dialog_content = "Tem a ver com a reativação do Windstone.",
  ui_story_5032_50320902_36_dialog_content = "Encontrei uma maneira de fazer isso, mas preciso da sua ajuda.",
  ui_story_5032_50320902_37_dialog_content = "Entendido. O que voce precisa que eu faca?",
  ui_story_5032_50320902_38_dialog_content = "Devemos primeiro recuar para um local mais seguro, longe de qualquer possível interferência do Eclipsite. Vou explicar tudo no caminho.",
  ui_story_5032_50320902_39_dialog_content = "Hum...",
  ui_story_5032_50320902_40_dialog_content = "Receio que não.",
  ui_story_5032_50320902_41_dialog_content = "Jeno...",
  ui_story_5032_50320902_42_dialog_content = "Salve isso. Esta é a única coisa em que me recuso a ajudá-lo.",
  ui_story_5032_50320902_43_dialog_content = "Não sei de onde você tirou a ideia de fazer isso...",
  ui_story_5032_50320902_44_dialog_content = "Mas qualquer um que exagere seu Lumina assim provavelmente morrerá.",
  ui_story_5032_50320902_45_dialog_content = "Terei prazer em ajudá-lo a encontrar outra maneira, ou até ficar ao seu lado e lutar até meu último suspiro...",
  ui_story_5032_50320902_46_dialog_content = "Mas eu me recuso a levá-lo à sua morte assim.",
  ui_story_5032_50320902_47_dialog_content = "Não tenho dúvidas sobre a força de nossa amizade ou sua bravura, Jeno.",
  ui_story_5032_50320902_48_dialog_content = "Mas, nessas circunstâncias terríveis, temo que não haja outra opção para nós.",
  ui_story_5032_50320902_49_dialog_content = "Este plano resultará no menor número de sacrifícios possível. Como laird de Harbour City, cabe a mim livrar meu povo do perigo.",
  ui_story_5032_50320902_50_dialog_content = "Você acha que sua morte seria um \"pequeno sacrifício\"? Você foi atingido na cabeça por uma daquelas máquinas explosivas nos terrenos selados?!",
  ui_story_5032_50320902_51_dialog_content = "Você tem alguma ideia de quão perigoso seria se eu transferisse seu Lumina restante em seu estado atual?",
  ui_story_5032_50320902_52_dialog_content = "Um pequeno passo em falso e seu Lumina será completamente esgotado!",
  ui_story_5032_50320902_53_dialog_content = "Os riscos são realmente grandes, mas ainda há uma pequena chance de sucesso, certo?",
  ui_story_5032_50320902_54_dialog_content = "Por favor, Jeno.",
  ui_story_5032_50320902_55_dialog_content = "Tenho a maior confiança em sua capacidade de controlá-lo adequadamente.",
  ui_story_5032_50320902_56_dialog_content = "Afinal, você é um dos maiores mágicos e artistas.",
  ui_story_5032_50320902_57_dialog_content = "É muito perigoso. Não tenho como garantir sua segurança.",
  ui_story_5032_50320902_58_dialog_content = "Laird Elvis.",
  ui_story_5032_50320902_59_dialog_content = "Com licença por um momento, Jeno.",
  ui_story_5032_50320902_60_dialog_content = "O que é isso, Patu?",
  ui_story_5032_50320902_61_dialog_content = "Sinto muito interromper sua conversa.",
  ui_story_5032_50320902_62_dialog_content = "Mas mais um Eclipsite de alto nível apareceu. Por favor, retire-se para um local seguro por enquanto!",
  ui_story_5032_50320902_63_dialog_content = "Não há nada a temer, Patou. Enquanto Jeno estiver aqui, não serei prejudicado.",
  ui_story_5032_50320902_64_dialog_content = "Agora pegue os soldados que encontrar e vá reforçar nossas defesas.",
  ui_story_5032_50320902_65_dialog_content = "O poder de alto nível do Eclipsite pode ser bastante imprevisível. Eu me sentiria mais seguro se você estivesse na vanguarda de nossas defesas.",
  ui_story_5032_50320902_66_dialog_content = "Mas...",
  ui_story_5032_50320902_67_dialog_content = "Rápido, Patu. Nossos homens precisam de você na linha de frente.",
  ui_story_5032_50320902_68_dialog_content = "... Sim, Laird Elvis.",
  ui_story_5032_50320902_69_dialog_content = "Você vê agora, Jeno?",
  ui_story_5032_50320902_70_dialog_content = "Essa inundação interminável de Eclipsitas afogará nossas forças restantes mais cedo ou mais tarde.",
  ui_story_5032_50320902_71_dialog_content = "E isso para não falar desse Darkflow cada vez mais intenso, que ameaça sufocar qualquer um que sobreviva ao ataque.",
  ui_story_5032_50320902_72_dialog_content = "Os reforços da princesa Carleen estão quase esgotados, e nossas posições defensivas estão caindo para os Eclipsitas uma a uma.",
  ui_story_5032_50320902_73_dialog_content = "A cada segundo que passamos debatendo, outro soldado é dilacerado pelos Eclipsitas.",
  ui_story_5032_50320902_74_dialog_content = "E todo esse sofrimento... foi causado por minhas próprias mãos.",
  ui_story_5032_50320902_75_dialog_content = "Mas você não tinha ideia de que chegaria a isso! Não é sua culpa!",
  ui_story_5032_50320902_76_dialog_content = "Heheh. Um erro é um erro, e alguém deve assumir a responsabilidade por isso. Não é esta uma das primeiras lições ensinadas aos nossos mais novos?",
  ui_story_5032_50320902_77_dialog_content = "Além disso, ainda sou o laird de Harbour City. Mais do que tudo, desejo protegê-lo, e meu povo.",
  ui_story_5032_50320902_78_dialog_content = "...",
  ui_story_5032_50320902_79_dialog_content = "Você disse uma vez que queria me proteger. Lembrar?",
  ui_story_5032_50320902_80_dialog_content = "... Sim.",
  ui_story_5032_50320902_81_dialog_content = "Proteger alguém não significa simplesmente manter essa pessoa viva, Jeno... Às vezes, significa manter seu sonho vivo. Você não concordaria?",
  ui_story_5032_50320902_82_dialog_content = "Meu sonho é que as pessoas de Harbour City retornem às vidas pacíficas e felizes que uma vez conheceram.",
  ui_story_5032_50320902_83_dialog_content = "Eles podem sentir mais dor ao longo do caminho e escrever mais histórias tristes nas páginas de nossa história.",
  ui_story_5032_50320902_84_dialog_content = "Mas, no mínimo, eles terão um lugar para chamar de lar... Um lugar onde seus sorrisos possam florescer mais uma vez.",
  ui_story_5032_50320902_85_dialog_content = "Ver um sorriso em cada um de seus rostos sempre foi meu sonho.",
  ui_story_5032_50320902_86_dialog_content = "Então eu te pergunto mais uma vez, Jeno. Você vai me ajudar a manter meu sonho vivo?",
  ui_story_5032_50320902_87_dialog_content = "... Como você pode fazer isto comigo?",
  ui_story_5032_50320902_88_dialog_content = "O quê?",
  ui_story_5032_50320902_89_dialog_content = "Você está me forçando... a colocar uma faca na sua garganta e usar toda essa conversa de sonhos e justiça para justificar isso.",
  ui_story_5032_50320902_90_dialog_content = "Eu... eu sinto muito, Jeno.",
  ui_story_5032_50320902_91_dialog_content = "Por coisas que aconteceram anos atrás, no Emerald, e agora também...",
  ui_story_5032_50320902_92_dialog_content = "Sinto muito, Jeno... por tudo.",
  ui_story_5032_50320902_93_dialog_content = "Eu sei que não sou digno de ser chamado de seu amigo, muito menos o laird de Harbour City.",
  ui_story_5032_50320902_94_dialog_content = "Minha teimosia e paranóia são o que fez com que tudo chegasse a isso.",
  ui_story_5032_50320902_95_dialog_content = "Você também foi arrastado para os meus problemas e por isso... Só posso me desculpar mais uma vez.",
  ui_story_5032_50320902_96_dialog_content = "Mas se eu deixar essa oportunidade escapar por minhas mãos e permitir que os Eclipsitas entrem em minha casa...",
  ui_story_5032_50320902_97_dialog_content = "Eu nunca vou me perdoar pelo resto da minha vida inútil.",
  ui_story_5032_50320902_98_dialog_content = "Então me chame de egoísta, me chame de idiota, me chame do que quiser... Mas eu imploro... Por favor, me ajude.",
  ui_story_5032_50320902_99_dialog_content = "...",
  ui_story_5032_50320902_100_dialog_content = "*Suspiro* Desde que éramos crianças, eu nunca poderia mudar sua mente... ou recusar você, por falar nisso.",
  ui_story_5032_50320902_101_dialog_content = "Farei isso, mas assim que detectar o menor indício de perigo, estou interrompendo todo o ritual.",
  ui_story_5032_50320902_102_dialog_content = "Heheh... não tenho objeções.",
  ui_story_5032_50320902_103_dialog_content = "Agora, como devemos começar?",
  ui_story_5032_50321001_1_dialog_content = "O terreno selado já foi destruído. Para reativar o Windstone, temos apenas um último método.",
  ui_story_5032_50321001_2_dialog_content = "Ou seja, o método empregado por nossos ancestrais para ativar o Windstone em eras passadas... Uma nova aliança deve ser feita com o Windstone.",
  ui_story_5032_50321001_3_dialog_content = "Mas como vamos alimentá-lo?",
  ui_story_5032_50321001_4_dialog_content = "As reservas de energia do Windstone estão quase totalmente esgotadas, é verdade.",
  ui_story_5032_50321001_5_dialog_content = "Talvez só possa ser feito como antes: usando o Lumina dos Aurorianos para sustentá-lo constantemente...",
  ui_story_5032_50321001_6_dialog_content = "Para pensar nisso, eu realmente sou um fracasso ...",
  ui_story_5032_50321001_7_dialog_content = "Não... Você fez tudo o que podia, Elvis. Isso não é sua culpa.",
  ui_story_5032_50321001_8_dialog_content = "Mesmo assim, falar sobre isso não vai ajudar a nossa situação. Devemos manter nossas mentes no Windstone.",
  ui_story_5032_50321001_9_dialog_content = "Para ativar o Windstone, meus ancestrais criaram o solo selado.",
  ui_story_5032_50321001_10_dialog_content = "Através do solo selado, o Windstone pode estabelecer uma espécie de vínculo com os Aurorianos, permitindo que ele colete seus Lumina.",
  ui_story_5032_50321001_11_dialog_content = "*Tosse, tosse* As capacidades do terreno selado... não são totalmente diferentes do <color=#FFB400>potência</color> você comanda.",
  ui_story_5032_50321001_12_dialog_content = "Você deseja usar meus poderes para simular os efeitos do solo selado e reativar com segurança o Windstone. É isso?",
  ui_story_5032_50321001_13_dialog_content = "De fato.",
  ui_story_5032_50321001_14_dialog_content = "... Tudo bem, eu vou seguir seu plano.",
  ui_story_5032_50321001_15_dialog_content = "Mas, como eu disse antes: no segundo em que sinto o menor perigo, estou cortando a conexão entre você e o Windstone.",
  ui_story_5032_50321001_16_dialog_content = "Muito bem... Deixo o resto com você, meu amigo.",
  ui_story_5032_50321001_17_dialog_content = "Para o bem de Harbour City e seu povo, o ritual deve ter sucesso!",
  ui_story_5032_50321001_18_dialog_content = "Feche os olhos e imagine-se segurando a Windstone em suas mãos...",
  ui_story_5032_50321001_19_dialog_content = "Hum...",
  ui_story_5032_50321001_20_dialog_content = "Sim, apenas assim. Estou prestes a começar a transferência, então tente não resistir.",
  ui_story_5032_50321001_21_dialog_content = "Heheh... eu nem sonharia com isso.",
  ui_story_5032_50321001_22_dialog_content = "Estabelecendo a conexão entre seu Lumina e o Windstone...",
  ui_story_5032_50321001_23_dialog_content = "Urgh... *Tosse, tosse*",
  ui_story_5032_50321001_24_dialog_content = "Tudo bem, eu fiz o que você me pediu para fazer.",
  ui_story_5032_50321001_25_dialog_content = "Vá em frente, Elvis!",
  ui_story_5032_50321001_26_dialog_content = "Pedra-de-vento! Comece a reativação!",
  ui_story_5032_50321001_27_dialog_content = "Detecção <color=#FFB400>energia</color> entrada...",
  ui_story_5032_50321001_28_dialog_content = "Genótipo auroriano detectado... Conexão estabelecida. Iniciando a extração de Lumina...",
  ui_story_5032_50321001_29_dialog_content = "Agora tudo que eu preciso fazer... é...",
  ui_story_5032_50321001_30_dialog_content = "Aahhhhhh!",
  ui_story_5032_50321001_31_dialog_content = "Eles estão se reunindo ao nosso redor. Eles sentem a ameaça da reativação do Windstone?",
  ui_story_5032_50321001_32_dialog_content = "Deixe esses eclipses para mim.",
  ui_story_5032_50321002_1_dialog_content = "Só um pouco mais...",
  ui_story_5032_50321002_2_dialog_content = "A reativação do sistema está em andamento...",
  ui_story_5032_50321002_3_dialog_content = "*Hack* Argh...!",
  ui_story_5032_50321002_4_dialog_content = "Por que o Windstone está absorvendo cada vez mais Lumina?!",
  ui_story_5032_50321002_5_dialog_content = "Pare a reativação, Elvis! Seu corpo não pode lidar com esse tipo de tensão!",
  ui_story_5032_50321002_6_dialog_content = "Você vai morrer nesse ritmo!",
  ui_story_5032_50321002_7_dialog_content = "Não há... sem parar agora...",
  ui_story_5032_50321002_8_dialog_content = "Apenas espere! Vou cortar a conexão entre você e o Windstone!",
  ui_story_5032_50321002_9_dialog_content = "Hã?!",
  ui_story_5032_50321002_10_dialog_content = "Elvis, você está resistindo?",
  ui_story_5032_50321002_11_dialog_content = "Não... É o Windstone! Ele assumiu o link que criei, então não posso quebrá-lo!",
  ui_story_5032_50321002_12_dialog_content = "Mas como isso poderia ser? Responda-me, Elvis!",
  ui_story_5032_50321002_13_dialog_content = "Parece que não adianta mais mentir para você.",
  ui_story_5032_50321002_14_dialog_content = "A verdade é que os terrenos selados servem a duas funções.",
  ui_story_5032_50321002_15_dialog_content = "Uma é permitir que os Aurorianos usem Lumina para estabelecer uma conexão com a Pedra do Vento para que possam controlá-la.",
  ui_story_5032_50321002_16_dialog_content = "A outra é controlar a velocidade com que a Pedra do Vento extrai Lumina... para evitar que ela mate os Aurorianos que a ativam.",
  ui_story_5032_50321002_17_dialog_content = "Você escondeu de mim a função secundária dos terrenos selados...",
  ui_story_5032_50321002_18_dialog_content = "Você sabia que meus poderes só podiam simular a primeira função!",
  ui_story_5032_50321002_19_dialog_content = "Procurei alto e baixo por uma maneira de reativar a Pedra do Vento... Uma que não exigisse os terrenos selados... Mas no final...",
  ui_story_5032_50321002_20_dialog_content = "O Windstone só havia sido ativado uma vez na história escrita. O conhecimento sobre o assunto era bastante limitado.",
  ui_story_5032_50321002_21_dialog_content = "Minha única escolha... era arriscar...",
  ui_story_5032_50321002_22_dialog_content = "Mesmo que isso significasse... me sacrificar.",
  ui_story_5032_50321002_23_dialog_content = "Você sabia que ia acabar assim, não é?!",
  ui_story_5032_50321002_24_dialog_content = "Perdoe-me... Jeno...",
  ui_story_5032_50321002_25_dialog_content = "Essa foi... a única outra maneira que encontrei...",
  ui_story_5032_50321002_26_dialog_content = "Somente me sacrificando e oferecendo cada gota de Lumina em meu corpo... eu poderia garantir a reativação do Windstone! *COF cof*",
  ui_story_5032_50321002_27_dialog_content = "Como você pode me enganar assim?!",
  ui_story_5032_50321002_28_dialog_content = "Isso mesmo... Eu te enganei mais uma vez.",
  ui_story_5032_50321002_29_dialog_content = "Por que... Por que continuo fazendo isso com você?",
  ui_story_5032_50321002_30_dialog_content = "Eu nunca quis esconder nada de você... Crescer foi a coisa mais difícil que tive que fazer...",
  ui_story_5032_50321002_31_dialog_content = "Heh... Mas agora... finalmente posso expiar meus erros...",
  ui_story_5032_50321002_32_dialog_content = "Este é o meu destino... assim como o destino do Modali.",
  ui_story_5032_50321002_33_dialog_content = "Ao reativar o Windstone, toda Harbour City estará segura mais uma vez...",
  ui_story_5032_50321002_34_dialog_content = "*Tosse*",
  ui_story_5032_50321002_35_dialog_content = "Elvis...",
  ui_story_5032_50321002_36_dialog_content = "Você é algum tipo de idiota?!",
  ui_story_5032_50321002_37_dialog_content = "J-Jeno?!",
  ui_story_5032_50321002_38_dialog_content = "A responsabilidade de proteger Harbour City não é sua e somente sua.",
  ui_story_5032_50321002_39_dialog_content = "Não se esqueça que Harbour City e Emerald... também são minha casa!",
  ui_story_5032_50321002_40_dialog_content = "Você não é o único no palco, então pare de pensar que os holofotes pertencem apenas a você!",
  ui_story_5032_50321002_41_dialog_content = "Não pare! Eu não quero te arrastar para isso!",
  ui_story_5032_50321002_42_dialog_content = "Corte sua conexão!",
  ui_story_5032_50321002_43_dialog_content = "Faz anos que não nos vemos... Não é fácil nos encontrarmos hoje em dia, sabe...?",
  ui_story_5032_50321002_44_dialog_content = "Você acha que eu vou deixar você escapar de novo tão facilmente?",
  ui_story_5032_50321002_45_dialog_content = "Mesmo que eu sempre tenha sido o passivo e imaturo...",
  ui_story_5032_50321002_46_dialog_content = "Jurei que protegeria aquilo que procurava proteger.",
  ui_story_5032_50321002_47_dialog_content = "Eu não vou voltar atrás na minha palavra nunca mais.",
  ui_story_5032_50321002_48_dialog_content = "Jeno...",
  ui_story_5032_50321002_49_dialog_content = "Nova entrada de energia detectada. Estabelecendo conexão...",
  ui_story_5032_50321002_50_dialog_content = "Agora é tarde demais, Elvis. Você e eu estamos no mesmo navio afundando agora.",
  ui_story_5032_50321002_51_dialog_content = "Heh... Heheh... Que tal você fazer algo assim.",
  ui_story_5032_50321002_52_dialog_content = "Você não é mais aquele garotinho que precisa da minha proteção.",
  ui_story_5032_50321002_53_dialog_content = "Agora então... Vamos ver que tipo de truques de mágica você tem a oferecer.",
  ui_story_5032_50321002_54_dialog_content = "Ha... Para o meu ato final... vou transformar nós dois na fonte de energia desta pedra...",
  ui_story_5032_50321002_55_dialog_content = "<color=#e8d9bb>Enquanto isso, a bordo do Emerald</color>",
  ui_story_5032_50321002_56_dialog_content = "Aaarrgh!",
  ui_story_5032_50321002_57_dialog_content = "Por que há tantos Eclipsitos aqui?!",
  ui_story_5032_50321002_58_dialog_content = "Th-Há mais deles subindo o casco do navio!",
  ui_story_5032_50321002_59_dialog_content = "As águas estão repletas de Eclipsites! Eu sou muito jovem para ser comido vivo!!",
  ui_story_5032_50321002_60_dialog_content = "Ahhh!!!",
  ui_story_5032_50321002_61_dialog_content = "Fia!",
  ui_story_5032_50321002_62_dialog_content = "Rainbow!",
  ui_story_5032_50321002_63_dialog_content = "Olhar! Não há eclipsitas na proa do navio! Você precisa ir até lá e soltar Geedo!",
  ui_story_5032_50321002_64_dialog_content = "Eu vou cortar um caminho para você!",
  ui_story_5032_50321002_65_dialog_content = "Eu... eu tenho que ser forte! Pelo amor de Geedo!",
  ui_story_5032_50321002_66_dialog_content = "Graah! Rugido!",
  ui_story_5032_50321002_67_dialog_content = "Saia do meu caminho-!",
  ui_story_5032_50321002_68_dialog_content = "Chegamos à proa! Agora é só abrir a garrafa!",
  ui_story_5032_50321002_69_dialog_content = "Argh!",
  ui_story_5032_50321002_70_dialog_content = "Por que a tampa está tão apertada?!",
  ui_story_5032_50321002_71_dialog_content = "Graaaaaah!",
  ui_story_5032_50321002_72_dialog_content = "Oh não! Um deles passou!",
  ui_story_5032_50321002_73_dialog_content = "Cuidado, Fia!",
  ui_story_5032_50321002_74_dialog_content = "Uaaau!!!",
  ui_story_5032_50321002_75_dialog_content = "Graaaao!",
  ui_story_5032_50321002_76_dialog_content = "Nãooo!!!",
  ui_story_5032_50321002_77_dialog_content = "Fia! Segure-se em mim!!!",
  ui_story_5032_50321002_78_dialog_content = "Ah—!",
  ui_story_5032_50321002_79_dialog_content = "PlayerName! O que você está fazendo aqui também?!",
  ui_story_5032_50321002_80_dialog_content = "Eu escorreguei!",
  ui_story_5032_50321002_81_dialog_content = "Nãooo! Agora nunca mais vou conseguir comer o doce que guardei no meu quarto... É assim que termina para mim?!",
  ui_story_5032_50321002_82_dialog_content = "Eu nunca cheguei a usar todo o meu dinheiro suado para gastar, também!",
  ui_story_5032_50321002_83_dialog_content = "Glub, glub, glub...",
  ui_story_5032_50321002_84_dialog_content = "(Eu... eu não consigo respirar...)",
  ui_story_5032_50321002_85_dialog_content = "<color=#e8d9bb>Estrondo-!</color>",
  ui_story_5032_50321002_86_dialog_content = "Ao meu redor... O som da água batendo...",
  ui_story_5032_50321002_87_dialog_content = "Eu posso respirar de novo... Será que eu estou... morto?",
  ui_story_5032_50321002_88_dialog_content = "Não seja bobo, PlayerName! Você ainda está vivo, e eu também!",
  ui_story_5032_50321002_89_dialog_content = "Abra os olhos e veja por si mesmo! Geedo nos salvou!",
  ui_story_5032_50321002_90_dialog_content = "E-É enorme!!",
  ui_story_5032_50321002_91_dialog_content = "Eu não tinha ideia de que Geedo poderia ficar tão grande! Também... Geedo está voando?!",
  ui_story_5032_50321002_92_dialog_content = "A Baleia Nuvem é uma fera exótica e maravilhosa, afinal. Voar não está tão fora de questão!",
  ui_story_5032_50321002_93_dialog_content = "Eu tenho que admitir, porém, eu também não fazia ideia de que Geedo pudesse voar...",
  ui_story_5032_50321002_94_dialog_content = "<color=#e8d9bb>Estrondo...</color>",
  ui_story_5032_50321002_95_dialog_content = "O que foi aquele rugido maçante agora? Também... Sou eu, ou você sente algo tremendo?",
  ui_story_5032_50321002_96_dialog_content = "Uh-oh... Desça e segure firme, PlayerName!",
  ui_story_5032_50321002_97_dialog_content = "O quê?!",
  ui_story_5032_50321002_98_dialog_content = "Huh??",
  ui_story_5032_50321002_99_dialog_content = "Oooh!",
  ui_story_5032_50321002_100_dialog_content = "É... Está jorrando como uma baleia?!",
  ui_story_5032_50321002_101_dialog_content = "<color=#e8d9bb>Estrondo!</color>",
  ui_story_5032_50321002_102_dialog_content = "Que incrível jorro de água! Parece que estamos na chuva!",
  ui_story_5032_50321002_103_dialog_content = "Ah! Graaaaaah!",
  ui_story_5032_50321002_104_dialog_content = "Graah... Graaaah...",
  ui_story_5032_50321002_105_dialog_content = "A água... Parece que está afetando os Eclipsites!",
  ui_story_5032_50321002_106_dialog_content = "Fia estava certa o tempo todo?",
  ui_story_5032_50321101_1_dialog_content = "*Tosse* Os Eclipsites... Por que seus movimentos parecem tão lentos agora?",
  ui_story_5032_50321101_2_dialog_content = "O Darkflow parece estar diminuindo também...",
  ui_story_5032_50321101_3_dialog_content = "Poderia aquela enorme fera no céu ser responsável por isso?",
  ui_story_5032_50321101_4_dialog_content = "Isso é... uma Baleia Nuvem?",
  ui_story_5032_50321101_5_dialog_content = "Agora que penso nisso, aquela garotinha estava falando sobre procurar um antes... Fia, eu acredito?",
  ui_story_5032_50321101_6_dialog_content = "E todo esse tempo, eu pensei que ela era apenas uma criança ingênua perseguindo um conto de fadas...",
  ui_story_5032_50321101_7_dialog_content = "Eu nunca pensei que ela realmente iria encontrá-lo!",
  ui_story_5032_50321101_8_dialog_content = "Uma Baleia Nuvem?",
  ui_story_5032_50321101_9_dialog_content = "Sim... Um tipo incrivelmente raro de besta maravilhosa, tão rara que se tornou lenda... Mesmo eu só vi representações dela em livros.",
  ui_story_5032_50321101_10_dialog_content = "Embora seu corpo se assemelhe ao de uma baleia, também é capaz de voar e reside bem acima das nuvens.",
  ui_story_5032_50321101_11_dialog_content = "Seu poderoso Lumina é capaz de deter Eclipsites e dissipar até mesmo o Darkflow mais espesso.",
  ui_story_5032_50321101_12_dialog_content = "Fora isso, há muito pouco conhecimento sobre as Baleias Nuvens, considerando o quão raras elas são.",
  ui_story_5032_50321101_13_dialog_content = "Entendi.",
  ui_story_5032_50321101_14_dialog_content = "Você ainda gosta de ler sobre lendas e contos de fantasia... *Tosse, tosse*",
  ui_story_5032_50321101_15_dialog_content = "No mínimo, parece que não precisamos nos preocupar com a interferência dos Eclipsitos próximos por enquanto.",
  ui_story_5032_50321101_16_dialog_content = "Você está certo... Parece que Harbour City é realmente abençoada pelo divino, afinal.",
  ui_story_5032_50321101_17_dialog_content = "Não só a cidade tem um tolo como laird que está disposto a arriscar sua vida por ela... mas agora, ela tem a proteção de uma das mais raras bestas maravilhosas do mundo inteiro.",
  ui_story_5032_50321101_18_dialog_content = "Hehehe... Não é só isso...",
  ui_story_5032_50321101_19_dialog_content = "A cidade também tem um mágico lunático... Um que está disposto a acompanhar o laird da cidade em todos os seus empreendimentos tolos...",
  ui_story_5032_50321101_20_dialog_content = "Harbour City realmente tem sorte... E eu também... *Tosse, tosse*",
  ui_story_5032_50321101_21_dialog_content = "*Tosse* Urgh!",
  ui_story_5032_50321101_22_dialog_content = "Haa... Estou... no meu limite?",
  ui_story_5032_50321101_23_dialog_content = "Apenas deite aqui por enquanto. Tente não falar. Você precisa economizar sua força.",
  ui_story_5032_50321101_24_dialog_content = "Já que não precisamos mais nos preocupar com os Eclipsites, tenho mais Lumina de sobra.",
  ui_story_5032_50321101_25_dialog_content = "Você... você vai aumentar sua própria entrada de Lumina?",
  ui_story_5032_50321101_26_dialog_content = "Urgh... Sentir meu Lumina escapar assim... É horrível.",
  ui_story_5032_50321101_27_dialog_content = "É com isso que você tem lidado todo esse tempo, Elvis?",
  ui_story_5032_50321101_28_dialog_content = "Por favor... Pare com isso, Jeno! Se você continuar... Você vai morrer também!",
  ui_story_5032_50321101_29_dialog_content = "É só um pouco de Lumina... Não vou deixar você me deixar para trás novamente.",
  ui_story_5032_50321101_30_dialog_content = "Desta vez... ficarei bem na sua frente!",
  ui_story_5032_50321101_31_dialog_content = "*tosse* Jeno...",
  ui_story_5032_50321101_32_dialog_content = "Extração de energia concluída.",
  ui_story_5032_50321101_33_dialog_content = "O sistema está pronto para ser ativado.",
  ui_story_5032_50321101_34_dialog_content = "Finalmente teve o seu preenchimento, hein?",
  ui_story_5032_50321101_35_dialog_content = "Quem teria imaginado que uma pedra tão pequena poderia conter tanto Lumina?",
  ui_story_5032_50321101_36_dialog_content = "*Cof*",
  ui_story_5032_50321101_37_dialog_content = "Elvis! Você está bem?",
  ui_story_5032_50321101_38_dialog_content = "*Ofegante* Jeno... Quando tudo estiver resolvido... Por favor, dê a Pedra do Vento para Patou no meu lugar.",
  ui_story_5032_50321101_39_dialog_content = "Eu... já disse a ele... exatamente o que precisa ser feito.",
  ui_story_5032_50321101_40_dialog_content = "Elvis...",
  ui_story_5032_50321101_41_dialog_content = "Prometa-me, Jeno... Prometa-me que entregará a Pedra do Vento a Patou.",
  ui_story_5032_50321101_42_dialog_content = "Você pode dar a ele mesmo assim que o selo for reativado.",
  ui_story_5032_50321101_43_dialog_content = "Por favor, Jeno... Apenas me ajude uma última vez... Estou tão cansado...",
  ui_story_5032_50321101_44_dialog_content = "Desde o dia em que te deixei... sempre me senti... muito cansado...",
  ui_story_5032_50321101_45_dialog_content = "Por favor... Deixe-me descansar um pouco, sim?",
  ui_story_5032_50321101_46_dialog_content = "...",
  ui_story_5032_50321101_47_dialog_content = "Sim, eu sei.",
  ui_story_5032_50321101_48_dialog_content = "Obrigado, Jeno.",
  ui_story_5032_50321101_49_dialog_content = "Obrigado por tudo.",
  ui_story_5032_50321101_50_dialog_content = "Windstone... Ativar.",
  ui_story_5032_50321101_51_dialog_content = "Comando reconhecido.",
  ui_story_5032_50321101_52_dialog_content = "O que é essa luz? É tão brilhante!",
  ui_story_5032_50321101_53_dialog_content = "É na direção de onde Laird Elvis foi! Ele poderia estar em perigo?",
  ui_story_5032_50321101_54_dialog_content = "Olhar! Os Eclipsites... Eles estão recuando para o mar!",
  ui_story_5032_50321101_55_dialog_content = "Você tem razão! Até mesmo os Eclipsites de alto nível estão recuando!",
  ui_story_5032_50321101_56_dialog_content = "O Darkflow está se dissipando! me sinto viva de novo!!",
  ui_story_5032_50321101_57_dialog_content = "Deve ser o Laird Elvis! Ele deve ter encontrado uma maneira de derrotar os Eclipsites!",
  ui_story_5032_50321101_58_dialog_content = "Isso deve ser obra do Laird Elvis!",
  ui_story_5032_50321101_59_dialog_content = "Você ouviu isso, Elvis?",
  ui_story_5032_50321101_60_dialog_content = "Seu povo está clamando por você... Eles estão comemorando esta vitória em seu nome.",
  ui_story_5032_50321101_61_dialog_content = "Você fez isso. O Windstone e o selo foram reativados.",
  ui_story_5032_50321101_62_dialog_content = "Heheh... Estou muito feliz em ouvir isso.",
  ui_story_5032_50321101_63_dialog_content = "Você também disse que faria as coisas para mim antes, lembra?",
  ui_story_5032_50321101_64_dialog_content = "Assim que a poeira baixar, pretendo fazer a coleta completa... Portanto, esteja pronto para isso.",
  ui_story_5032_50321101_65_dialog_content = "Meu navio precisa desesperadamente de reparos, e você será responsável por torná-lo navegável novamente.",
  ui_story_5032_50321101_66_dialog_content = "Posso ser um mágico, mas prometo não enganá-lo sobre o custo dos reparos. Na verdade, vou pedir a Rainbow para fazer uma lista detalhada para deixar tudo perfeitamente claro. Tudo que você precisa fazer é ter sua carteira pronta.",
  ui_story_5032_50321101_67_dialog_content = "Entendo... Isso não deve ser um problema...",
  ui_story_5032_50321101_68_dialog_content = "Além disso, como não temos como continuar nosso passeio, ficaremos em Harbour City por mais algum tempo.",
  ui_story_5032_50321101_69_dialog_content = "Enquanto isso, podemos tentar construir aquele restaurante de arte de que falávamos.",
  ui_story_5032_50321101_70_dialog_content = "Quem sabe? Talvez possa servir como nosso local para apresentações futuras?",
  ui_story_5032_50321101_71_dialog_content = "Além disso, alguém do seu status não deve ter problemas para construir um restaurante aqui...",
  ui_story_5032_50321101_72_dialog_content = "Jeno...",
  ui_story_5032_50321101_73_dialog_content = "Sim? Estou aqui, Elvis.",
  ui_story_5032_50321101_74_dialog_content = "O céu sobre Harbour City... está clareando.",
  ui_story_5032_50321101_75_dialog_content = "Esta sempre foi... minha visão favorita.",
  ui_story_5032_50321101_76_dialog_content = "<size=30>Você poderia talvez... pintá-lo para mim algum dia?</size>",
  ui_story_5032_50321101_77_dialog_content = "Claro. Eu prometo.",
  ui_story_5032_50321101_78_dialog_content = "Lembra daquele quadro que você pediu da última vez? Eu terminei há muito tempo... Está pendurado no meu quarto esse tempo todo.",
  ui_story_5032_50321101_79_dialog_content = "Mas pode não ser exatamente o que você queria. Afinal, tive que confiar inteiramente na memória para pintá-lo.",
  ui_story_5032_50321101_80_dialog_content = "Você pode dar uma olhada por si mesmo mais tarde. Se você não gostar, sempre posso pintar outro.",
  ui_story_5032_50321101_81_dialog_content = "...",
  ui_story_5032_50321101_82_dialog_content = "... Elvis?",
  ui_story_5032_50321101_83_dialog_content = "...",
  ui_story_5032_50321101_84_dialog_content = "Tch... Você é outra coisa, sabia?",
  ui_story_5032_50321101_85_dialog_content = "Sempre faça promessas que não pode cumprir...",
  ui_story_5032_50321101_86_dialog_content = "Você é um mentiroso, Elvis...",
  ui_story_5032_50321101_87_dialog_content = "Um mentiroso inútil...",
  ui_story_5032_50321101_88_dialog_content = "<color=#e8d9bb>Cinco dias depois</color>",
  ui_story_5032_50321101_89_dialog_content = "*Suspira*",
  ui_story_5032_50321101_90_dialog_content = "Parece que você esqueceu suas roupas, PlayerName. Alguém veio e os deixou.",
  ui_story_5032_50321101_91_dialog_content = "Y-Você está certo, eu quase esqueci de embalá-los! Obrigado, Vice!",
  ui_story_5032_50321101_92_dialog_content = "A decisão de Carleen de ir para casa foi uma surpresa, então na minha pressa de empacotar tudo, quase perdi algumas coisas.",
  ui_story_5032_50321101_93_dialog_content = "*Suspira*",
  ui_story_5032_50321101_94_dialog_content = "Por que você não dá outra olhada ao redor e se certifica de não esquecer mais nada? Carleen ainda está se reunindo com as autoridades da cidade, então você tem tempo para uma última verificação.",
  ui_story_5032_50321101_95_dialog_content = "Claro, vou dar uma olhada.",
  ui_story_5032_50321101_96_dialog_content = "*Suspira*",
  ui_story_5032_50321101_97_dialog_content = "... O que há de errado, Fia?",
  ui_story_5032_50321101_98_dialog_content = "Tem algo em mente, Fia? Você está franzindo a testa desde que nos levantamos esta manhã.",
  ui_story_5032_50321101_99_dialog_content = "Estou pensando em como Geedo nos deixou tão de repente...",
  ui_story_5032_50321101_100_dialog_content = "Como vou explicar isso ao meu mestre?!",
  ui_story_5032_50321101_101_dialog_content = "Ei...",
  ui_story_5032_50321101_102_dialog_content = "Seu mestre deve ser capaz de sentir a presença de Geedo novamente, você não acha?",
  ui_story_5032_50321101_103_dialog_content = "Tenho certeza de que ele percebeu no momento em que você libertou Geedo da garrafa.",
  ui_story_5032_50321101_104_dialog_content = "Você não entende, Vice... Se eu não mostrar na cara dele que minha missão está completa, ele não vai pagar!",
  ui_story_5032_50321101_105_dialog_content = "Ele vai fingir que estou mentindo, e todas as recompensas que ele me prometeu por um trabalho bem feito... Ele vai jogar tudo fora!",
  ui_story_5032_50321101_106_dialog_content = "Parece-me uma relação justa e equitativa, Fia.",
  ui_story_5032_50321101_107_dialog_content = "Isso é o suficiente de você, PlayerName!",
  ui_story_5032_50321101_108_dialog_content = "O mestre de Fia soa um pouco excessivo, você não acha?",
  ui_story_5032_50321101_109_dialog_content = "O que deveríamos fazer, PlayerName? Acha que podemos levar Fia conosco e levá-la para casa em Soroz?",
  ui_story_5032_50321101_110_dialog_content = "Dessa forma, podemos agir como suas testemunhas.",
  ui_story_5032_50321101_111_dialog_content = "Parece bom para mim!",
  ui_story_5032_50321101_112_dialog_content = "H-Huh? Sério?! Isso será ótimo!",
  ui_story_5032_50321101_113_dialog_content = "Muito obrigado, Vice! Desta vez, farei o mestre pagar tudo o que me deve! Muahahaha!",
  ui_story_5032_50321101_114_dialog_content = "Vocês três parecem estar de bom humor, hein?",
  ui_story_5032_50321101_115_dialog_content = "Ah! Acabei de ouvir a voz de Subli?",
  ui_story_5032_50321101_116_dialog_content = "Ei! Aqui está.",
  ui_story_5032_50321101_117_dialog_content = "Rainbow nos disse que você estava saindo, então nós queríamos te mandar embora!",
  ui_story_5032_50321101_118_dialog_content = "...",
  ui_story_5032_50321101_119_dialog_content = "Boas viagens, pessoal!",
  ui_story_5032_50321101_120_dialog_content = "Venha ver nosso show na próxima vez que tiver uma chance! Eu vou conseguir um bom negócio para você em assentos primos!",
  ui_story_5032_50321101_121_dialog_content = "Hahaha! Podemos apenas aceitar essa oferta!",
  ui_story_5032_50321101_122_dialog_content = "Ei... não vejo Ciel em lugar nenhum. Ela não veio com você, Rainbow?",
  ui_story_5032_50321101_123_dialog_content = "Ciel recebeu uma convocação de emergência da Illumina ontem. Ela também saiu com muita pressa.",
  ui_story_5032_50321101_124_dialog_content = "Entendo... Ciel com certeza se mantém ocupada, não é? Eles até ligaram para ela de suas férias...",
  ui_story_5032_50321101_125_dialog_content = "Devíamos começar os reparos no Esmeralda hoje...",
  ui_story_5032_50321101_126_dialog_content = "Mas Merylt praticamente implorou por uma última chance de ver o Caelestite, então é por isso...",
  ui_story_5032_50321101_127_dialog_content = "Ai!",
  ui_story_5032_50321101_128_dialog_content = "F-Frimet!",
  ui_story_5032_50321101_129_dialog_content = "Hahahaha! Parece que você tem um fã obstinado, PlayerName.",
  ui_story_5032_50321101_130_dialog_content = "Exatamente!",
  ui_story_5032_50321101_131_dialog_content = "Honestamente... quero dizer, o que há de tão bom nisso PlayerName de qualquer forma?",
  ui_story_5032_50321101_132_dialog_content = "E quanto a mim? Eu também ajudei muito, sabe! E Kyllo ajudou vocês a encontrar seu gato de três caudas também!",
  ui_story_5032_50321101_133_dialog_content = "Você tem toda razão, Fia... Kyllo também merece nossa gratidão!",
  ui_story_5032_50321101_134_dialog_content = "Não é mesmo, Kylo?",
  ui_story_5032_50321101_135_dialog_content = "Ei!",
  ui_story_5032_50321101_136_dialog_content = "O-O quê?!",
  ui_story_5032_50321101_137_dialog_content = "Isso mesmo, Frimet! Eu vou te mostrar o quão forte eu sou!",
  ui_story_5032_50321101_138_dialog_content = "Oh meu... Isso é tudo o que é preciso para você ficar excitado?",
  ui_story_5032_50321101_139_dialog_content = "Hehehe, parece que a Fia também fez novos amigos.",
  ui_story_5032_50321101_140_dialog_content = "Com certeza parece assim. Estou tão feliz por eles!",
  ui_story_5032_50321101_141_dialog_content = "Frimet e suas irmãs passam a maior parte de seus dias interagindo com os membros da platéia... Elas raramente têm a oportunidade de conversar com outras pessoas fora dessa capacidade.",
  ui_story_5032_50321101_142_dialog_content = "Como resultado, eles realmente não têm amigos da idade deles.",
  ui_story_5032_50321101_143_dialog_content = "Eles são tão sortudos por terem conhecido alguém como Fia...",
  ui_story_5032_50321101_144_dialog_content = "Assim como o resto de vocês. Todos nós somos muito sortudos por termos feito amigos como você!",
  ui_story_5032_50321101_145_dialog_content = "*Soluçando* Rainbow...",
  ui_story_5032_50321101_146_dialog_content = "Somos nós que temos sorte de conhecer todos vocês, Rainbow!",
  ui_story_5032_50321101_147_dialog_content = "Heehee!",
  ui_story_5032_50321101_148_dialog_content = "Diga, algum de vocês viu Carleen por aí?",
  ui_story_5032_50321101_149_dialog_content = "Carleen ainda deve se reunir com os membros da Casa Modali. Estávamos esperando aqui por ela para terminar seu negócio.",
  ui_story_5032_50321101_150_dialog_content = "Afinal, tanta coisa aconteceu... Tenho certeza de que há muitos assuntos que exigem a atenção dela agora.",
  ui_story_5032_50321101_151_dialog_content = "<size=30>Então essa é a vida de uma princesa, hein... Que legal!</size>",
  ui_story_5032_50321101_152_dialog_content = "Hum? Você disse alguma coisa?",
  ui_story_5032_50321101_153_dialog_content = "Ehehe... Você não deveria fazer tantas perguntas para uma garota, PlayerName!",
  ui_story_5032_50321101_154_dialog_content = "Apenas cuide da sua vida, ok?!",
  ui_story_5032_50321101_155_dialog_content = "Uau!",
  ui_story_5032_50321101_156_dialog_content = "C-Cuidado, Merylt!",
  ui_story_5032_50321101_157_dialog_content = "Sério, o que você pensa que está fazendo, Subli?",
  ui_story_5032_50321101_158_dialog_content = "Ei, ela está apenas tentando ajudar sua irmã à sua maneira! Hahaha!",
  ui_story_5032_50321101_159_dialog_content = "Faça o seu melhor, Merylt!",
  ui_story_5032_50321101_160_dialog_content = "Eh? Rainbow-?",
  ui_story_5032_50321101_161_dialog_content = "SS-Desculpe por isso!",
  ui_story_5032_50321101_162_dialog_content = "Está tudo bem, Merylt. A única razão pela qual você esbarrou em mim é que Subli te empurrou agora.",
  ui_story_5032_50321101_163_dialog_content = "Não doeu nada, honestamente!",
  ui_story_5032_50321101_164_dialog_content = "...",
  ui_story_5032_50321101_165_dialog_content = "(Esta... Esta é a minha última chance!)",
  ui_story_5032_50321101_166_dialog_content = "H-Hum...",
  ui_story_5032_50321101_167_dialog_content = "Eu te escrevi uma carta, PlayerName.",
  ui_story_5032_50321101_168_dialog_content = "Huh? Uma letra?",
  ui_story_5032_50321101_169_dialog_content = "P-Por favor, não abra até depois de sair!",
  ui_story_5032_50321101_170_dialog_content = "Claro, sem problemas... Obrigado!",
  ui_story_5032_50321101_171_dialog_content = "A-Também...",
  ui_story_5032_50321101_172_dialog_content = "Existe algo mais?",
  ui_story_5032_50321101_173_dialog_content = "E-Se não for muito t-problema... Posso...",
  ui_story_5032_50321101_174_dialog_content = "<size=30>M-Posso...</size>",
  ui_story_5032_50321101_175_dialog_content = "Desculpe, o que foi isso?",
  ui_story_5032_50321101_176_dialog_content = "<size=45>Posso te visitar em Eraveil algum dia?!</size>",
  ui_story_5032_50321101_177_dialog_content = "Uau! V-você me assustou agora!",
  ui_story_5032_50321101_178_dialog_content = "Eu sinto muito! Foi estranho eu perguntar isso?",
  ui_story_5032_50321101_179_dialog_content = "Eu entendo totalmente se não estiver tudo bem! Você pode simplesmente dizer isso, e eu não vou incomodá-lo nunca mais!",
  ui_story_5032_50321101_180_dialog_content = "Me desculpe, eu sabia que perguntar a você só iria causar mais problemas...",
  ui_story_5032_50321101_181_dialog_content = "Claro!",
  ui_story_5032_50321101_182_dialog_content = "Hã?",
  ui_story_5032_50321101_183_dialog_content = "Claro, você pode vir me ver a qualquer hora! Somos amigos, não somos, Merylt?",
  ui_story_5032_50321101_184_dialog_content = "Se você quiser visitar Eraveil, a porta está sempre aberta. Você pode até trazer alguns de seus amigos, se quiser!",
  ui_story_5032_50321101_185_dialog_content = "A reconstrução está indo muito bem, então tenho certeza de que há muitos quartos para você ficar.",
  ui_story_5032_50321101_186_dialog_content = "F-Amigos...?",
  ui_story_5032_50321101_187_dialog_content = "... Th-Obrigado!",
  ui_story_5032_50321101_188_dialog_content = "Agora que você mencionou, eu provavelmente deveria parar em Umbraton no caminho de volta.",
  ui_story_5032_50321101_189_dialog_content = "Se quisermos receber algum convidado, provavelmente precisamos estocar comida. Estamos quase sem herbicida para as ervas daninhas também...",
  ui_story_5032_50321101_190_dialog_content = "Também estamos ficando sem sabão em pó e um monte de outras necessidades diárias... Hmmm...",
  ui_story_5032_50321101_191_dialog_content = "Vamos precisar de alguns suprimentos para nos ajudar a vencer o calor, também...",
  ui_story_5032_50321101_192_dialog_content = "(Frimet, Subli, eu acho...)",
  ui_story_5032_50321101_193_dialog_content = "(Acho que agora sei por que gosto tanto desse celestita.)",
  ui_story_5032_50321101_194_dialog_content = "Frimet... Ela é tão escorregadia quanto uma enguia em um balde de óleo!",
  ui_story_5032_50321101_195_dialog_content = "Bem, ela é uma artista de circo treinada, afinal...",
  ui_story_5032_50321101_196_dialog_content = "Urgh... Eu não vou pegar leve com ela da próxima vez! Eu juro!",
  ui_story_5032_50321101_197_dialog_content = "Ei!",
  ui_story_5032_50321101_198_dialog_content = "Desculpe ter deixado todos vocês esperando.",
  ui_story_5032_50321101_199_dialog_content = "Parece que perdi muita diversão.",
  ui_story_5032_50321101_200_dialog_content = "Carleen! Você voltou!",
  ui_story_5032_50321101_201_dialog_content = "Você não perdeu muito, apenas Frimet fazendo Fia de boba... Ai!",
  ui_story_5032_50321101_202_dialog_content = "Isso realmente doeu! Pare de pisar no meu pé!",
  ui_story_5032_50321101_203_dialog_content = "Hmph! Isso vai te ensinar a tirar sarro de mim, PlayerName.",
  ui_story_5032_50321101_204_dialog_content = "Tudo bem, pessoal, isso é o suficiente por enquanto.",
  ui_story_5032_50321101_205_dialog_content = "Tudo foi resolvido do seu lado, Carleen?",
  ui_story_5032_50321101_206_dialog_content = "*Suspiro* Você pode dizer isso, sim.",
  ui_story_5032_50321101_207_dialog_content = "Não consegui chegar a um acordo com Loewe e Matthieu sobre a melhor forma de proceder. Por mais frustrante que tenha sido, eles não querem mais manter tudo em segredo.",
  ui_story_5032_50321101_208_dialog_content = "Receberam meu itinerário esta manhã e voltaram para Lumopolis.",
  ui_story_5032_50321101_209_dialog_content = "Meu pai ficou bastante descontente quando eu o enganei anteriormente... Ainda tenho que descobrir o que vou dizer a ele quando voltar.",
  ui_story_5032_50321101_210_dialog_content = "Isso mesmo... você estava basicamente escondendo a verdade de Lord Schwartz por causa de Harbour City.",
  ui_story_5032_50321101_211_dialog_content = "Felizmente, Matthieu e os outros não sabem muito sobre o Windstone.",
  ui_story_5032_50321101_212_dialog_content = "No mínimo, isso é uma coisa a menos para se preocupar.",
  ui_story_5032_50321101_213_dialog_content = "A Casa Modali está em completa desordem agora... Eles ainda precisam nomear um novo laird, também.",
  ui_story_5032_50321101_214_dialog_content = "Se a notícia do Windstone se espalhar, eles nunca serão capazes de lidar com as coisas.",
  ui_story_5032_50321101_215_dialog_content = "Err...",
  ui_story_5032_50321101_216_dialog_content = "Isso significa que Elvis ainda não mostrou nenhum sinal de acordar?",
  ui_story_5032_50321101_217_dialog_content = "De fato. Atualmente, ele ainda está em coma profundo.",
  ui_story_5032_50321101_218_dialog_content = "Se não fosse por Jeno ajudando-o a carregar a carga para reativar o Windstone, Elvis já estaria morto.",
  ui_story_5032_50321101_219_dialog_content = "No entanto, mesmo os melhores médicos não têm como acordá-lo de um coma como este.",
  ui_story_5032_50321101_220_dialog_content = "*Suspiro* É tão triste vê-lo assim, e depois de todas as batalhas que ele viveu...",
  ui_story_5032_50321101_221_dialog_content = "Talvez... este seja o destino de Elvis?",
  ui_story_5032_50321101_222_dialog_content = "O desejo de Elvis de proteger seu povo levou a esse desastre em primeiro lugar.",
  ui_story_5032_50321101_223_dialog_content = "E assim, a única maneira de salvar seu povo de seus próprios erros era se sacrificar.",
  ui_story_5032_50321101_224_dialog_content = "De certa forma, pode-se dizer que ele realizou o que se propôs a fazer desde o início.",
  ui_story_5032_50321101_225_dialog_content = "Alguém como ele já deve ter feito as pazes com isso como um possível resultado.",
  ui_story_5032_50321101_226_dialog_content = "...",
  ui_story_5032_50321101_227_dialog_content = "Incrível... Você sempre consegue falar tão bem quando é mais importante, Fia.",
  ui_story_5032_50321101_228_dialog_content = "Não posso deixar de admirá-lo um pouco mais depois de dizer isso.",
  ui_story_5032_50321101_229_dialog_content = "O que? Quer dizer que não poderia chegar a uma conclusão tão simples sozinho, PlayerName?",
  ui_story_5032_50321101_230_dialog_content = "Você não vai durar um dia na sociedade se não começar a pensar um pouco mais por si mesmo, sabe!",
  ui_story_5032_50321101_231_dialog_content = "Eu só estava te fazendo um elogio! Não deixe subir à cabeça!",
  ui_story_5032_50321101_232_dialog_content = "Continue assim, e talvez eu mude de ideia sobre ajudá-lo a explicar as coisas ao seu mestre!",
  ui_story_5032_50321101_233_dialog_content = "O-o quê?! Não por favor! Qualquer coisa menos isso!",
  ui_story_5032_50321101_234_dialog_content = "Você já prometeu ajudar! Que tipo de pessoa você seria se não cumprisse suas promessas?!",
  ui_story_5032_50321101_235_dialog_content = "Fia faz um bom ponto, você sabe.",
  ui_story_5032_50321101_236_dialog_content = "Este pode ser o resultado que Elvis mais desejava.",
  ui_story_5032_50321101_237_dialog_content = "Afinal, a paz finalmente voltou a Harbour City.",
  ui_story_5032_50321101_238_dialog_content = "É triste que, apesar de todo o seu trabalho duro e sacrifício, a Síndrome de Modali ainda seja um problema.",
  ui_story_5032_50321101_239_dialog_content = "Na verdade, este é um assunto que não requer muita preocupação, pelo menos por enquanto.",
  ui_story_5032_50321101_240_dialog_content = "Jeno me disse que o Windstone parece ter absorvido uma grande quantidade de Lumina do Cloudwhale durante a última batalha.",
